    var expectedAmount = data.expectedAmount || "";
    if (typeof expectedAmount === "string") {
      var numOnly = expectedAmount.replace(/[^0-9]/g, "");
      if (numOnly) expectedAmount = parseInt(numOnly, 10);
    }
