  // Script
  html += '<script>';
  html += 'var WS_REQUIRED_PIN_TOKEN = ' + jsStringLiteral_(currentPinToken) + ';\n';
  html += 'var WS_VALID_AUTH_TOKENS = ' + JSON.stringify(validAuthTokensList) + ';\n';
  html += 'var WS_SERVER_PRE_TOKEN = ' + jsStringLiteral_(isServerPreAuthed ? cleanPreTok : "") + ';\n';
  html += 'var WS_PIN_STORAGE_KEY = "ws_dashboard_auth_token_v2";\n';
  html += 'var WS_USER_STORAGE_KEY = "ws_dashboard_auth_user_v2";\n';
  html += 'var WS_PIN_FAIL_KEY = "ws_pin_fail_count_v1";\n';
  html += 'var WS_PIN_LOCK_UNTIL_KEY = "ws_pin_lock_until_v1";\n';
  html += 'var WS_PIN_MAX_ATTEMPTS = 5;\n';
  html += 'var WS_PIN_LOCKOUT_MS = 180000;\n';
  html += 'var wsPinLockTimerId = null;\n';
  html += 'function checkAndRenderWsPinLockout() {\n';
  html += '  try {\n';
  html += '    var lockUntilRaw = (typeof localStorage !== "undefined" && localStorage && typeof localStorage.getItem === "function") ? localStorage.getItem(WS_PIN_LOCK_UNTIL_KEY) : "0";\n';
  html += '    var lockUntil = parseInt(lockUntilRaw || "0", 10) || 0;\n';
  html += '    var nowMs = Date.now();\n';
  html += '    var nameInp = document.getElementById("wsAccessNameInput");\n';
  html += '    var inp = document.getElementById("wsAccessPinInput");\n';
  html += '    var btn = document.getElementById("wsAccessPinBtn");\n';
  html += '    var errEl = document.getElementById("wsAccessPinError");\n';
  html += '    if (lockUntil > nowMs) {\n';
  html += '      var remainSec = Math.ceil((lockUntil - nowMs) / 1000);\n';
  html += '      var m = Math.floor(remainSec / 60);\n';
  html += '      var s = remainSec % 60;\n';
  html += '      var timeText = (m > 0 ? m + "분 " : "") + s + "초";\n';
  html += '      if (nameInp) { nameInp.disabled = true; nameInp.style.background = "#f1f5f9"; }\n';
  html += '      if (inp) { inp.disabled = true; inp.value = ""; inp.placeholder = "입력 제한 중 (" + timeText + ")"; inp.style.background = "#f1f5f9"; }\n';
  html += '      if (btn) { btn.disabled = true; btn.style.background = "#94a3b8"; btn.style.cursor = "not-allowed"; btn.innerText = "⛔ 입력 잠금 중 (" + timeText + ")"; }\n';
  html += '      if (errEl) { errEl.style.display = "block"; errEl.innerText = "⛔ 인증 5회 연속 오류로 3분간 잠겼습니다. (" + timeText + " 후 재시도)"; }\n';
  html += '      if (!wsPinLockTimerId) {\n';
  html += '        wsPinLockTimerId = setInterval(checkAndRenderWsPinLockout, 1000);\n';
  html += '      }\n';
  html += '      return true;\n';
  html += '    } else {\n';
  html += '      if (wsPinLockTimerId) { clearInterval(wsPinLockTimerId); wsPinLockTimerId = null; }\n';
  html += '      if (lockUntil > 0) {\n';
  html += '        try { if (typeof localStorage !== "undefined" && localStorage) { localStorage.removeItem(WS_PIN_LOCK_UNTIL_KEY); localStorage.removeItem(WS_PIN_FAIL_KEY); } } catch (eCl) {}\n';
  html += '        if (nameInp) { nameInp.disabled = false; nameInp.style.background = "#f8fafc"; }\n';
  html += '        if (inp) { inp.disabled = false; inp.placeholder = "공용 비밀번호 입력"; inp.style.background = "#f8fafc"; inp.focus(); }\n';
  html += '        if (btn) { btn.disabled = false; btn.style.background = "#2563eb"; btn.style.cursor = "pointer"; btn.innerText = "인증하고 대시보드 열기"; }\n';
  html += '        if (errEl) { errEl.style.display = "none"; }\n';
  html += '      }\n';
  html += '      return false;\n';
  html += '    }\n';
  html += '  } catch (eLk) { return false; }\n';
  html += '}\n';
  html += '(function() {\n';
  html += '  try {\n';
  html += '    var savedTok = WS_SERVER_PRE_TOKEN || "";\n';
  html += '    var savedUsr = "";\n';
  html += '    if (typeof localStorage !== "undefined" && localStorage && typeof localStorage.getItem === "function") {\n';
  html += '      if (!savedTok) savedTok = localStorage.getItem(WS_PIN_STORAGE_KEY) || "";\n';
  html += '      savedUsr = localStorage.getItem(WS_USER_STORAGE_KEY) || "";\n';
  html += '    }\n';
  html += '    if (!savedTok && typeof sessionStorage !== "undefined" && sessionStorage && typeof sessionStorage.getItem === "function") {\n';
  html += '      savedTok = sessionStorage.getItem(WS_PIN_STORAGE_KEY) || "";\n';
  html += '    }\n';
  html += '    var lockEl = document.getElementById("wsAccessLockOverlay");\n';
  html += '    if (savedTok && Array.isArray(WS_VALID_AUTH_TOKENS) && WS_VALID_AUTH_TOKENS.indexOf(savedTok) !== -1) {\n';
  html += '      if (lockEl) lockEl.style.display = "none";\n';
  html += '    } else {\n';
  html += '      var nameInp = document.getElementById("wsAccessNameInput");\n';
  html += '      if (nameInp && savedUsr && savedUsr.toLowerCase() !== "admin" && !nameInp.value) {\n';
  html += '        nameInp.value = savedUsr;\n';
  html += '      }\n';
  html += '      checkAndRenderWsPinLockout();\n';
  html += '      setTimeout(function() {\n';
  html += '        var nEl = document.getElementById("wsAccessNameInput");\n';
  html += '        var pEl = document.getElementById("wsAccessPinInput");\n';
  html += '        if (nEl && !nEl.disabled && !nEl.value) nEl.focus();\n';
  html += '        else if (pEl && !pEl.disabled) pEl.focus();\n';
  html += '      }, 120);\n';
  html += '    }\n';
  html += '    if (typeof window !== "undefined") {\n';
  html += '      window.addEventListener("message", function(ev) {\n';
  html += '        var d = ev && ev.data;\n';
  html += '        if (!d || d.type !== "WS_RESTORE_AUTH") return;\n';
  html += '        if (d.token && Array.isArray(WS_VALID_AUTH_TOKENS) && WS_VALID_AUTH_TOKENS.indexOf(d.token) !== -1) {\n';
  html += '          var lk = document.getElementById("wsAccessLockOverlay");\n';
  html += '          if (lk) lk.style.display = "none";\n';
  html += '          try { if (typeof sessionStorage !== "undefined" && sessionStorage) sessionStorage.setItem(WS_PIN_STORAGE_KEY, d.token); } catch (eR) {}\n';
  html += '        } else if (d.user && String(d.user).toLowerCase() !== "admin") {\n';
  html += '          var nInp = document.getElementById("wsAccessNameInput");\n';
  html += '          if (nInp && !nInp.value) nInp.value = String(d.user);\n';
  html += '        }\n';
  html += '      });\n';
  html += '      try { if (window.top && window.top !== window) window.top.postMessage({ type: "WS_AUTH_INIT" }, "*"); } catch (eTopI) {}\n';
  html += '      try { if (window.parent && window.parent !== window && window.parent !== window.top) window.parent.postMessage({ type: "WS_AUTH_INIT" }, "*"); } catch (eParI) {}\n';
  html += '    }\n';
  html += '  } catch (eLock) {}\n';
  html += '})();\n';
  html += 'function computeClientWsPinToken(pinStr) {\n';
  html += '  var s = "ws_pin_v1::" + String(pinStr || "").trim();\n';
  html += '  var h1 = 5381;\n';
  html += '  for (var i = 0; i < s.length; i++) {\n';
  html += '    h1 = (((h1 << 5) + h1) ^ s.charCodeAt(i)) >>> 0;\n';
  html += '  }\n';
  html += '  return "WSPIN_" + h1.toString(16).toUpperCase() + "_" + s.length;\n';
  html += '}\n';
  html += 'function computeClientWsUserToken(userStr, pinStr) {\n';
  html += '  var cleanUser = String(userStr || "").replace(/\\s+/g, "").trim();\n';
  html += '  if (cleanUser.toLowerCase() === "admin") cleanUser = "admin";\n';
  html += '  var s = "ws_auth_v2::" + cleanUser + "::" + String(pinStr || "").trim();\n';
  html += '  var h1 = 5381;\n';
  html += '  for (var i = 0; i < s.length; i++) {\n';
  html += '    h1 = (((h1 << 5) + h1) ^ s.charCodeAt(i)) >>> 0;\n';
  html += '  }\n';
  html += '  return "WSAUTH_" + h1.toString(16).toUpperCase() + "_" + s.length;\n';
  html += '}\n';
  html += 'function unlockWsDashboardWithToken(token, userName) {\n';
  html += '  if (Array.isArray(WS_VALID_AUTH_TOKENS) && WS_VALID_AUTH_TOKENS.indexOf(token) === -1) {\n';
  html += '    WS_VALID_AUTH_TOKENS.push(token);\n';
  html += '  }\n';
  html += '  var keepChk = document.getElementById("wsAccessKeepLoginChk");\n';
  html += '  var keepPersistent = keepChk ? !!keepChk.checked : true;\n';
  html += '  var cleanU = String(userName || "").replace(/\\s+/g, "").trim();\n';
  html += '  try {\n';
  html += '    if (typeof localStorage !== "undefined" && localStorage) {\n';
  html += '      localStorage.removeItem(WS_PIN_FAIL_KEY);\n';
  html += '      localStorage.removeItem(WS_PIN_LOCK_UNTIL_KEY);\n';
  html += '      if (keepPersistent) {\n';
  html += '        localStorage.setItem(WS_PIN_STORAGE_KEY, token);\n';
  html += '        if (cleanU && cleanU.toLowerCase() !== "admin") localStorage.setItem(WS_USER_STORAGE_KEY, cleanU);\n';
  html += '      } else {\n';
  html += '        localStorage.removeItem(WS_PIN_STORAGE_KEY);\n';
  html += '      }\n';
  html += '    }\n';
  html += '    if (typeof sessionStorage !== "undefined" && sessionStorage) {\n';
  html += '      sessionStorage.setItem(WS_PIN_STORAGE_KEY, token);\n';
  html += '    }\n';
  html += '    if (typeof window !== "undefined") {\n';
  html += '      var authMsg = { type: "WS_SAVE_AUTH", token: token, user: cleanU, keep: keepPersistent };\n';
  html += '      try { if (window.top && window.top !== window) window.top.postMessage(authMsg, "*"); } catch (eTopS) {}\n';
  html += '      try { if (window.parent && window.parent !== window && window.parent !== window.top) window.parent.postMessage(authMsg, "*"); } catch (eParS) {}\n';
  html += '    }\n';
  html += '  } catch (eS) {}\n';
  html += '  var lockEl = document.getElementById("wsAccessLockOverlay");\n';
  html += '  var errEl = document.getElementById("wsAccessPinError");\n';
  html += '  if (lockEl) lockEl.style.display = "none";\n';
  html += '  if (errEl) errEl.style.display = "none";\n';
  html += '  if (typeof showToast === "function") {\n';
  html += '    showToast(keepPersistent ? "🔓 구성원 인증이 완료되었습니다. (이 기기에서 자동 유지됩니다)" : "🔓 1회성 인증 완료 (브라우저 창을 닫으면 자동으로 잠깁니다)");\n';
  html += '  }\n';
  html += '}\n';
  html += 'function showWsAccessPinError(customMsg) {\n';
  html += '  var inp = document.getElementById("wsAccessPinInput");\n';
  html += '  var errEl = document.getElementById("wsAccessPinError");\n';
  html += '  var btn = document.getElementById("wsAccessPinBtn");\n';
  html += '  var failCount = 0;\n';
  html += '  try {\n';
  html += '    if (typeof localStorage !== "undefined" && localStorage) {\n';
  html += '      failCount = (parseInt(localStorage.getItem(WS_PIN_FAIL_KEY) || "0", 10) || 0) + 1;\n';
  html += '      if (failCount >= WS_PIN_MAX_ATTEMPTS) {\n';
  html += '        localStorage.setItem(WS_PIN_LOCK_UNTIL_KEY, String(Date.now() + WS_PIN_LOCKOUT_MS));\n';
  html += '        localStorage.setItem(WS_PIN_FAIL_KEY, "0");\n';
  html += '      } else {\n';
  html += '        localStorage.setItem(WS_PIN_FAIL_KEY, String(failCount));\n';
  html += '      }\n';
  html += '    }\n';
  html += '  } catch (eFc) {}\n';
  html += '  if (checkAndRenderWsPinLockout()) return;\n';
  html += '  if (btn) { btn.disabled = false; btn.innerText = "인증하고 대시보드 열기"; }\n';
  html += '  if (errEl) {\n';
  html += '    errEl.style.display = "block";\n';
  html += '    var baseMsg = customMsg || "등록된 구성원 이름이 아니거나 비밀번호가 일치하지 않습니다.";\n';
  html += '    errEl.innerText = "❌ " + baseMsg + " (오류 " + failCount + "/" + WS_PIN_MAX_ATTEMPTS + "회)";\n';
  html += '  }\n';
  html += '  if (inp) {\n';
  html += '    inp.classList.remove("ws-pin-shake");\n';
  html += '    void inp.offsetWidth;\n';
  html += '    inp.classList.add("ws-pin-shake");\n';
  html += '    inp.value = "";\n';
  html += '    inp.focus();\n';
  html += '  }\n';
  html += '}\n';
  html += 'function submitWsAccessPin() {\n';
  html += '  if (checkAndRenderWsPinLockout()) return;\n';
  html += '  var nameInp = document.getElementById("wsAccessNameInput");\n';
  html += '  var inp = document.getElementById("wsAccessPinInput");\n';
  html += '  var errEl = document.getElementById("wsAccessPinError");\n';
  html += '  var btn = document.getElementById("wsAccessPinBtn");\n';
  html += '  var valName = nameInp ? String(nameInp.value || "").replace(/\\s+/g, "").trim() : "";\n';
  html += '  var val = inp ? String(inp.value || "").trim() : "";\n';
  html += '  if (!valName) {\n';
  html += '    if (errEl) { errEl.style.display = "block"; errEl.innerText = "⚠️ 구성원 이름을 입력해 주세요."; }\n';
  html += '    if (nameInp) nameInp.focus();\n';
  html += '    return;\n';
  html += '  }\n';
  html += '  if (!val) {\n';
  html += '    if (errEl) { errEl.style.display = "block"; errEl.innerText = "⚠️ 비밀번호를 입력해 주세요."; }\n';
  html += '    if (inp) inp.focus();\n';
  html += '    return;\n';
  html += '  }\n';
  html += '  var candidateToken = computeClientWsUserToken(valName, val);\n';
  html += '  if (Array.isArray(WS_VALID_AUTH_TOKENS) && WS_VALID_AUTH_TOKENS.indexOf(candidateToken) !== -1) {\n';
  html += '    unlockWsDashboardWithToken(candidateToken, valName);\n';
  html += '    return;\n';
  html += '  }\n';
  html += '  if (btn) { btn.disabled = true; btn.innerText = "구성원 및 비밀번호 확인 중..."; }\n';
  html += '  if (typeof google !== "undefined" && google.script && google.script.run) {\n';
  html += '    google.script.run\n';
  html += '      .withSuccessHandler(function(res) {\n';
  html += '        if (btn) { btn.disabled = false; btn.innerText = "인증하고 대시보드 열기"; }\n';
  html += '        if (res && res.success && res.token) {\n';
  html += '          unlockWsDashboardWithToken(res.token, valName);\n';
  html += '        } else {\n';
  html += '          showWsAccessPinError(res && res.error);\n';
  html += '        }\n';
  html += '      })\n';
  html += '      .withFailureHandler(function() { showWsAccessPinError(); })\n';
  html += '      .verifyDashboardAccessPinFromWeb(val, valName);\n';
  html += '  } else {\n';
  html += '    var apiUrl = (typeof SCRIPT_URL !== "undefined" ? SCRIPT_URL : (window.location.href.split("?")[0]));\n';
  html += '    fetch(apiUrl + "?action=verifyDashboardPin&user=" + encodeURIComponent(valName) + "&pin=" + encodeURIComponent(val))\n';
  html += '      .then(function(r) { return r.json(); })\n';
  html += '      .then(function(res) {\n';
  html += '        if (btn) { btn.disabled = false; btn.innerText = "인증하고 대시보드 열기"; }\n';
  html += '        if (res && res.success && res.token) {\n';
  html += '          unlockWsDashboardWithToken(res.token, valName);\n';
  html += '        } else {\n';
  html += '          showWsAccessPinError(res && res.error);\n';
  html += '        }\n';
  html += '      })\n';
  html += '      .catch(function() { showWsAccessPinError(); });\n';
  html += '  }\n';
  html += '}\n';

  // ========================================================
  // [마스터 설정 관리: 거래처, 공종 및 구성원 실시간 클라이언트 엔진]
  // ========================================================
  html += '\n';
  html += 'let currentSettingsTab = "partners";\n';
  html += 'let currentSettingsData = { partners: [], tasks: [], members: [] };\n';
  html += 'let originalSettingsData = { partners: [], tasks: [], members: [] };\n';
  html += 'let hasSettingsPendingChanges = false;\n';
  html += 'let settingsPendingChangesCount = 0;\n';
  html += 'let settingsSearchQuery = "";\n';
  html += 'let editingPartnerRow = null;\n';
  html += 'let editingTaskRow = null;\n';
  html += 'let editingMemberRow = null;\n';
  html += 'let settingsColumnFilters = { biz: "", category: "", priority: "", status: "", taskCat: "", memberRole: "", memberReceive: "" };\n';
  html += 'let settingsMovedPartnerRow = null;\n';
  html += 'let settingsMovedTaskRow = null;\n';
  html += 'let settingsMovedMemberRow = null;\n';
  html += '\n';
  html += 'function markSettingsChanged() {\n';
  html += '  hasSettingsPendingChanges = true;\n';
  html += '  settingsPendingChangesCount++;\n';
  html += '  updateSettingsSaveBtn();\n';
  html += '}\n';
  html += '\n';
  html += 'function updateSettingsSaveBtn(isSaving) {\n';
  html += '  const btn = document.getElementById("settingsSaveAllBtn");\n';
  html += '  const label = document.getElementById("settingsSaveBtnLabel");\n';
  html += '  if (!btn || !label) return;\n';
  html += '  if (isSaving) {\n';
  html += '    btn.disabled = true;\n';
  html += '    btn.style.opacity = "0.75";\n';
  html += '    btn.style.cursor = "wait";\n';
  html += '    label.innerText = "시트에 저장 중...";\n';
  html += '    return;\n';
  html += '  }\n';
  html += '  btn.disabled = false;\n';
  html += '  btn.style.opacity = "1";\n';
  html += '  btn.style.cursor = "pointer";\n';
  html += '  if (hasSettingsPendingChanges) {\n';
  html += '    btn.style.background = "#2563eb";\n';
  html += '    btn.style.boxShadow = "0 2px 6px rgba(37,99,235,0.4)";\n';
  html += '    label.innerText = "저장하기 (변경됨)";\n';
  html += '  } else {\n';
  html += '    btn.style.background = "#64748b";\n';
  html += '    btn.style.boxShadow = "none";\n';
  html += '    label.innerText = "저장 완료됨";\n';
  html += '  }\n';
  html += '}\n';
  html += '\n';
  html += 'function openSettingsModal() {\n';
  html += '  const modal = document.getElementById("settingsModalOverlay");\n';
  html += '  if (!modal) return;\n';
  html += '  modal.style.display = "flex";\n';
  html += '  const cont = document.getElementById("settingsListContent");\n';
  html += '  if (cont) cont.scrollTop = 0;\n';
  html += '  renderSettingsView();\n';
  html += '  loadSettingsData();\n';
  html += '}\n';
  html += '\n';
  html += 'function closeSettingsModal() {\n';
  html += '  if (hasSettingsPendingChanges) {\n';
  html += '    if (!confirm("저장되지 않은 마스터 설정 변경사항이 있습니다.\\n저장하지 않고 창을 닫으시겠습니까?")) {\n';
  html += '      return;\n';
  html += '    }\n';
  html += '  }\n';
  html += '  currentSettingsData = JSON.parse(JSON.stringify(originalSettingsData));\n';
  html += '  hasSettingsPendingChanges = false;\n';
  html += '  settingsPendingChangesCount = 0;\n';
  html += '  updateSettingsSaveBtn();\n';
  html += '  const modal = document.getElementById("settingsModalOverlay");\n';
  html += '  if (modal) modal.style.display = "none";\n';
  html += '  closePartnerFormModal();\n';
  html += '  closeTaskFormModal();\n';
  html += '  closeMemberFormModal();\n';
  html += '}\n';
  html += '\n';
  html += 'function switchSettingsTab(tab) {\n';
  html += '  currentSettingsTab = tab;\n';
  html += '  const cont = document.getElementById("settingsListContent");\n';
  html += '  if (cont) cont.scrollTop = 0;\n';
  html += '  const tabP = document.getElementById("settingsTabPartners");\n';
  html += '  const tabT = document.getElementById("settingsTabTasks");\n';
  html += '  const tabM = document.getElementById("settingsTabMembers");\n';
  html += '  if (tabP) { tabP.style.background = (tab === "partners") ? "#2563eb" : "#f1f5f9"; tabP.style.color = (tab === "partners") ? "#ffffff" : "#475569"; tabP.style.boxShadow = (tab === "partners") ? "0 1px 2px rgba(37,99,235,0.2)" : "none"; }\n';
  html += '  if (tabT) { tabT.style.background = (tab === "tasks") ? "#2563eb" : "#f1f5f9"; tabT.style.color = (tab === "tasks") ? "#ffffff" : "#475569"; tabT.style.boxShadow = (tab === "tasks") ? "0 1px 2px rgba(37,99,235,0.2)" : "none"; }\n';
  html += '  if (tabM) { tabM.style.background = (tab === "members") ? "#2563eb" : "#f1f5f9"; tabM.style.color = (tab === "members") ? "#ffffff" : "#475569"; tabM.style.boxShadow = (tab === "members") ? "0 1px 2px rgba(37,99,235,0.2)" : "none"; }\n';
  html += '  const addBtn = document.getElementById("settingsAddBtn");\n';
  html += '  if (addBtn) {\n';
  html += '    if (tab === "partners") {\n';
  html += '      addBtn.innerText = "+ 신규 거래처 추가";\n';
  html += '      addBtn.onclick = openAddPartnerModal;\n';
  html += '    } else if (tab === "tasks") {\n';
  html += '      addBtn.innerText = "+ 신규 공종 추가";\n';
  html += '      addBtn.onclick = openAddTaskModal;\n';
  html += '    } else {\n';
  html += '      addBtn.innerText = "+ 신규 구성원 추가";\n';
  html += '      addBtn.onclick = openAddMemberModal;\n';
  html += '    }\n';
  html += '  }\n';
  html += '  renderSettingsView();\n';
  html += '}\n';
  html += '\n';
  html += 'function onSettingsSearchInput(val) {\n';
  html += '  settingsSearchQuery = String(val || "").trim().toLowerCase();\n';
  html += '  renderSettingsView();\n';
  html += '}\n';
  html += '\n';
  html += 'function onSettingsColumnFilterChange(field, val) {\n';
  html += '  settingsColumnFilters[field] = val || "";\n';
  html += '  renderSettingsView();\n';
  html += '}\n';
  html += '\n';
  html += 'function clearSettingsColumnFilter(field) {\n';
  html += '  settingsColumnFilters[field] = "";\n';
  html += '  renderSettingsView();\n';
  html += '}\n';
  html += '\n';
  html += 'function clearSettingsSearchFilter() {\n';
  html += '  settingsSearchQuery = "";\n';
  html += '  const sInp = document.getElementById("settingsSearchInput");\n';
  html += '  if (sInp) sInp.value = "";\n';
  html += '  renderSettingsView();\n';
  html += '}\n';
  html += '\n';
  html += 'function clearAllSettingsFilters() {\n';
  html += '  settingsColumnFilters = { biz: "", category: "", priority: "", status: "", taskCat: "", memberRole: "", memberReceive: "" };\n';
  html += '  settingsSearchQuery = "";\n';
  html += '  const sInp = document.getElementById("settingsSearchInput");\n';
  html += '  if (sInp) sInp.value = "";\n';
  html += '  renderSettingsView();\n';
  html += '}\n';
  html += '\n';
  html += 'function updateSettingsActiveFiltersBar() {\n';
  html += '  const bar = document.getElementById("settingsActiveFiltersBar");\n';
  html += '  if (!bar) return;\n';
  html += '  var badges = [];\n';
  html += '  if (currentSettingsTab === "partners") {\n';
  html += '    if (settingsColumnFilters.biz) badges.push({ field: "biz", label: "대표공종: " + settingsColumnFilters.biz });\n';
  html += '    if (settingsColumnFilters.category) badges.push({ field: "category", label: "대구분: " + settingsColumnFilters.category });\n';
  html += '    if (settingsColumnFilters.priority) badges.push({ field: "priority", label: "우선순위: " + settingsColumnFilters.priority });\n';
  html += '    if (settingsColumnFilters.status) badges.push({ field: "status", label: "관리상태: " + settingsColumnFilters.status });\n';
  html += '  } else if (currentSettingsTab === "tasks") {\n';
  html += '    if (settingsColumnFilters.taskCat) badges.push({ field: "taskCat", label: "구분: " + settingsColumnFilters.taskCat });\n';
  html += '  } else {\n';
  html += '    if (settingsColumnFilters.memberRole) badges.push({ field: "memberRole", label: "직급/역할: " + settingsColumnFilters.memberRole });\n';
  html += '    if (settingsColumnFilters.memberReceive) badges.push({ field: "memberReceive", label: "수신여부: " + (settingsColumnFilters.memberReceive === "Y" ? "수신함" : "미수신") });\n';
  html += '  }\n';
  html += '  if (settingsSearchQuery) {\n';
  html += '    badges.push({ field: "search", label: "검색: \\\"" + settingsSearchQuery + "\\\"" });\n';
  html += '  }\n';
  html += '  if (badges.length === 0) {\n';
  html += '    bar.style.display = "none";\n';
  html += '    bar.innerHTML = "";\n';
  html += '    return;\n';
  html += '  }\n';
  html += '  bar.style.display = "flex";\n';
  html += '  var bHtml = \'<div style="display:flex;align-items:center;gap:6px;flex-wrap:wrap;">\';\n';
  html += '  bHtml += \'<span style="font-weight:700;color:#475569;">🔍 적용된 필터:</span>\';\n';
  html += '  badges.forEach(function(b) {\n';
  html += '    if (b.field === "search") {\n';
  html += '      bHtml += \'<span class="settings-active-filter-badge">\' + escapeSettingsHtml(b.label) + \' <button type="button" onclick="clearSettingsSearchFilter()" title="검색 해제">✕</button></span>\';\n';
  html += '    } else {\n';
  html += '      bHtml += \'<span class="settings-active-filter-badge">\' + escapeSettingsHtml(b.label) + \' <button type="button" onclick="clearSettingsColumnFilter(\\\'\' + b.field + \'\\\')" title="필터 해제">✕</button></span>\';\n';
  html += '    }\n';
  html += '  });\n';
  html += '  bHtml += \'</div>\';\n';
  html += '  bHtml += \'<button type="button" onclick="clearAllSettingsFilters()" style="border:none;background:#e2e8f0;color:#334155;border-radius:6px;padding:3px 8px;font-size:11px;font-weight:700;cursor:pointer;">🔄 전체 필터 해제</button>\';\n';
  html += '  bar.innerHTML = bHtml;\n';
  html += '}\n';
  html += '\n';
  html += 'function loadSettingsData(silent) {\n';
  html += '  if (!silent) {\n';
  html += '    const listArea = document.getElementById("settingsListContent");\n';
  html += '    if (listArea && (!currentSettingsData.partners.length && !currentSettingsData.tasks.length && !currentSettingsData.members.length)) {\n';
  html += '      listArea.innerHTML = \'<div style="text-align:center;padding:50px 20px;color:#64748b;font-weight:600;"><div class="spinner" style="width:26px;height:26px;border-width:3px;margin:0 auto 12px;"></div>설정 데이터를 불러오는 중입니다...</div>\';\n';
  html += '    }\n';
  html += '  }\n';
  html += '  callSettingsApi("getSettingsData", {}, function(res) {\n';
  html += '    applySettingsDataResponse(res);\n';
  html += '  });\n';
  html += '}\n';
  html += '\n';
  html += 'function applySettingsDataResponse(res) {\n';
  html += '  if (res && res.success) {\n';
  html += '    currentSettingsData = {\n';
  html += '      partners: res.partners || [],\n';
  html += '      tasks: res.tasks || [],\n';
  html += '      members: res.members || []\n';
  html += '    };\n';
  html += '    originalSettingsData = JSON.parse(JSON.stringify(currentSettingsData));\n';
  html += '    hasSettingsPendingChanges = false;\n';
  html += '    settingsPendingChangesCount = 0;\n';
  html += '    updateSettingsSaveBtn();\n';
  html += '    const pCountEl = document.getElementById("settingsCountPartners");\n';
  html += '    const tCountEl = document.getElementById("settingsCountTasks");\n';
  html += '    const mCountEl = document.getElementById("settingsCountMembers");\n';
  html += '    if (pCountEl) pCountEl.innerText = currentSettingsData.partners.length;\n';
  html += '    if (tCountEl) tCountEl.innerText = currentSettingsData.tasks.length;\n';
  html += '    if (mCountEl) mCountEl.innerText = currentSettingsData.members.length;\n';
  html += '\n';
  html += '    // 현장 추가/수정에 실시간 연동 (rawData 갱신 및 드롭다운 즉시 동기화)\n';
  html += '    if (typeof rawData !== "undefined" && rawData) {\n';
  html += '      if (res.availablePartners) rawData.partners = res.availablePartners;\n';
  html += '      else if (res.partners) rawData.partners = res.partners.map(function(p) { return p.dropdownVal || p.name; });\n';
  html += '      if (res.availableTasks) rawData.tasks = res.availableTasks;\n';
  html += '      else if (res.tasks) rawData.tasks = res.tasks.map(function(t) { return t.taskName; });\n';
  html += '      if (res.availableManagers) rawData.availableManagers = res.availableManagers;\n';
  html += '      if (res.partnerPhoneMap) rawData.partnerPhoneMap = res.partnerPhoneMap;\n';
  html += '      if (res.memberPhoneMap) rawData.memberPhoneMap = res.memberPhoneMap;\n';
  html += '      if (res.siteSuperintendents) rawData.siteSuperintendents = res.siteSuperintendents;\n';
  html += '      else if (Array.isArray(res.members)) {\n';
  html += '        rawData.siteSuperintendents = res.members.filter(function(m) {\n';
  html += '          return m && m.name && String(m.role || "").replace(/\\s+/g, "").indexOf("소장") !== -1;\n';
  html += '        }).map(function(m) {\n';
  html += '          return { name: m.name, role: m.role || "소장", phone: m.phone || "" };\n';
  html += '        });\n';
  html += '      }\n';
  html += '      if (typeof populateTaskSelectOptions === "function") {\n';
  html += '        populateTaskSelectOptions(rawData.tasks);\n';
  html += '      }\n';
  html += '      if (typeof populatePartnerSelectOptions === "function") {\n';
  html += '        populatePartnerSelectOptions(rawData.partners);\n';
  html += '      }\n';
  html += '    }\n';
  html += '    renderSettingsView();\n';
  html += '  } else {\n';
  html += '    showToast("⚠️ " + ((res && res.error) || "데이터 로드 실패"));\n';
  html += '  }\n';
  html += '}\n';
  html += '\n';
  html += 'function renderSettingsView() {\n';
  html += '  const container = document.getElementById("settingsListContent");\n';
  html += '  if (!container) return;\n';
  html += '  if (currentSettingsTab === "partners") {\n';
  html += '    renderPartnersTable(container);\n';
  html += '  } else if (currentSettingsTab === "tasks") {\n';
  html += '    renderTasksTable(container);\n';
  html += '  } else {\n';
  html += '    renderMembersTable(container);\n';
  html += '  }\n';
  html += '}\n';
  html += '\n';
  html += 'function renderPartnersTable(container) {\n';
  html += '  updateSettingsActiveFiltersBar();\n';
  html += '  const rawList = currentSettingsData.partners || [];\n';
  html += '  const bizCounts = {};\n';
  html += '  const catCounts = {};\n';
  html += '  const prioCounts = {};\n';
  html += '  const statCounts = {};\n';
  html += '  rawList.forEach(function(p) {\n';
  html += '    const b = p.biz || "미지정";\n';
  html += '    bizCounts[b] = (bizCounts[b] || 0) + 1;\n';
  html += '    const c = p.category || "기타";\n';
  html += '    catCounts[c] = (catCounts[c] || 0) + 1;\n';
  html += '    const pr = p.priority || "미지정";\n';
  html += '    prioCounts[pr] = (prioCounts[pr] || 0) + 1;\n';
  html += '    const st = p.status || "운영 중";\n';
  html += '    statCounts[st] = (statCounts[st] || 0) + 1;\n';
  html += '  });\n';
  html += '  let list = rawList.filter(function(p) {\n';
  html += '    if (settingsSearchQuery) {\n';
  html += '      const q = settingsSearchQuery;\n';
  html += '      const match = (p.name && p.name.toLowerCase().includes(q)) ||\n';
  html += '                    (p.biz && p.biz.toLowerCase().includes(q)) ||\n';
  html += '                    (p.category && p.category.toLowerCase().includes(q)) ||\n';
  html += '                    (p.priority && p.priority.toLowerCase().includes(q)) ||\n';
  html += '                    (p.manager && p.manager.toLowerCase().includes(q)) ||\n';
  html += '                    (p.phone && p.phone.includes(q)) ||\n';
  html += '                    (p.status && p.status.toLowerCase().includes(q)) ||\n';
  html += '                    (p.feature && p.feature.toLowerCase().includes(q)) ||\n';
  html += '                    (p.orderMethod && p.orderMethod.toLowerCase().includes(q)) ||\n';
  html += '                    (p.note && p.note.toLowerCase().includes(q));\n';
  html += '      if (!match) return false;\n';
