  html += '    if (settingsColumnFilters.biz && (p.biz || "미지정") !== settingsColumnFilters.biz) return false;\n';
  html += '    if (settingsColumnFilters.category && (p.category || "기타") !== settingsColumnFilters.category) return false;\n';
  html += '    if (settingsColumnFilters.priority && (p.priority || "미지정") !== settingsColumnFilters.priority) return false;\n';
  html += '    if (settingsColumnFilters.status && (p.status || "운영 중") !== settingsColumnFilters.status) return false;\n';
  html += '    return true;\n';
  html += '  });\n';
  html += '  if (list.length === 0) {\n';
  html += '    container.innerHTML = \'<div style="text-align:center;padding:50px 20px;color:#94a3b8;font-weight:600;"><span style="font-size:24px;display:block;margin-bottom:8px;">🔍</span>조건에 일치하는 거래처가 없습니다. <button type="button" onclick="clearAllSettingsFilters()" style="margin-top:10px;padding:5px 12px;background:#2563eb;color:#fff;border:none;border-radius:6px;font-size:12px;cursor:pointer;">필터 초기화</button></div>\';\n';
  html += '    return;\n';
  html += '  }\n';
  html += '  let tHtml = \'<table style="width:100%;border-collapse:separate;border-spacing:0;font-size:12px;min-width:1250px;margin:0;padding:0;">\';\n';
  html += '  tHtml += \'<thead style="position:sticky;top:0;z-index:20;"><tr>\';\n';
  html += '  tHtml += \'<th class="settings-th-sticky" style="padding:10px 8px 10px 22px;text-align:center;width:60px;">순서</th>\';\n';
  html += '  tHtml += \'<th class="settings-th-sticky" style="padding:10px 6px;text-align:center;width:65px;">순서이동</th>\';\n';
  html += '  tHtml += \'<th class="settings-th-sticky" style="padding:10px 10px;text-align:left;width:140px;">업체 / 반장명</th>\';\n';
  html += '  tHtml += \'<th class="settings-th-sticky" style="padding:8px 8px;text-align:left;width:120px;">\';\n';
  html += '  tHtml += \'  <div style="font-weight:800;color:#334155;">대표 공종</div>\';\n';
  html += '  tHtml += \'  <select class="settings-filter-select\' + (settingsColumnFilters.biz ? \' settings-filter-active\' : \'\') + \'" onchange="onSettingsColumnFilterChange(\\\'biz\\\', this.value)">\';\n';
  html += '  tHtml += \'    <option value="">전체 (\' + rawList.length + \')</option>\';\n';
  html += '  Object.keys(bizCounts).sort().forEach(function(bKey) {\n';
  html += '    const sel = (settingsColumnFilters.biz === bKey) ? \' selected\' : \'\';\n';
  html += '    tHtml += \'  <option value="\' + escapeSettingsHtml(bKey) + \'"\' + sel + \'>\' + escapeSettingsHtml(bKey) + \' (\' + bizCounts[bKey] + \')</option>\';\n';
  html += '  });\n';
  html += '  tHtml += \'  </select>\';\n';
  html += '  tHtml += \'</th>\';\n';
  html += '  tHtml += \'<th class="settings-th-sticky" style="padding:8px 6px;text-align:center;width:95px;">\';\n';
  html += '  tHtml += \'  <div style="font-weight:800;color:#334155;">대구분</div>\';\n';
  html += '  tHtml += \'  <select class="settings-filter-select\' + (settingsColumnFilters.category ? \' settings-filter-active\' : \'\') + \'" onchange="onSettingsColumnFilterChange(\\\'category\\\', this.value)">\';\n';
  html += '  tHtml += \'    <option value="">전체</option>\';\n';
  html += '  Object.keys(catCounts).sort().forEach(function(cKey) {\n';
  html += '    const sel = (settingsColumnFilters.category === cKey) ? \' selected\' : \'\';\n';
  html += '    tHtml += \'  <option value="\' + escapeSettingsHtml(cKey) + \'"\' + sel + \'>\' + escapeSettingsHtml(cKey) + \' (\' + catCounts[cKey] + \')</option>\';\n';
  html += '  });\n';
  html += '  tHtml += \'  </select>\';\n';
  html += '  tHtml += \'</th>\';\n';
  html += '  tHtml += \'<th class="settings-th-sticky" style="padding:8px 6px;text-align:center;width:95px;">\';\n';
  html += '  tHtml += \'  <div style="font-weight:800;color:#334155;">우선순위</div>\';\n';
  html += '  tHtml += \'  <select class="settings-filter-select\' + (settingsColumnFilters.priority ? \' settings-filter-active\' : \'\') + \'" onchange="onSettingsColumnFilterChange(\\\'priority\\\', this.value)">\';\n';
  html += '  tHtml += \'    <option value="">전체</option>\';\n';
  html += '  Object.keys(prioCounts).sort().forEach(function(prKey) {\n';
  html += '    const sel = (settingsColumnFilters.priority === prKey) ? \' selected\' : \'\';\n';
  html += '    tHtml += \'  <option value="\' + escapeSettingsHtml(prKey) + \'"\' + sel + \'>\' + escapeSettingsHtml(prKey) + \' (\' + prioCounts[prKey] + \')</option>\';\n';
  html += '  });\n';
  html += '  tHtml += \'  </select>\';\n';
  html += '  tHtml += \'</th>\';\n';
  html += '  tHtml += \'<th class="settings-th-sticky" style="padding:10px 8px;text-align:left;width:105px;">담당자 / 직책</th>\';\n';
  html += '  tHtml += \'<th class="settings-th-sticky" style="padding:10px 8px;text-align:left;width:140px;white-space:nowrap;">연락처</th>\';\n';
  html += '  tHtml += \'<th class="settings-th-sticky" style="padding:8px 6px;text-align:center;width:95px;">\';\n';
  html += '  tHtml += \'  <div style="font-weight:800;color:#334155;">관리상태</div>\';\n';
  html += '  tHtml += \'  <select class="settings-filter-select\' + (settingsColumnFilters.status ? \' settings-filter-active\' : \'\') + \'" onchange="onSettingsColumnFilterChange(\\\'status\\\', this.value)">\';\n';
  html += '  tHtml += \'    <option value="">전체</option>\';\n';
  html += '  Object.keys(statCounts).sort().forEach(function(stKey) {\n';
  html += '    const sel = (settingsColumnFilters.status === stKey) ? \' selected\' : \'\';\n';
  html += '    tHtml += \'  <option value="\' + escapeSettingsHtml(stKey) + \'"\' + sel + \'>\' + escapeSettingsHtml(stKey) + \' (\' + statCounts[stKey] + \')</option>\';\n';
  html += '  });\n';
  html += '  tHtml += \'  </select>\';\n';
  html += '  tHtml += \'</th>\';\n';
  html += '  tHtml += \'<th class="settings-th-sticky" style="padding:10px 8px;text-align:left;width:150px;">주력분야 및 특징</th>\';\n';
  html += '  tHtml += \'<th class="settings-th-sticky" style="padding:10px 8px;text-align:left;width:110px;">발주/접수방식</th>\';\n';
  html += '  tHtml += \'<th class="settings-th-sticky" style="padding:10px 8px;text-align:left;min-width:110px;">비고</th>\';\n';
  html += '  tHtml += \'<th class="settings-th-sticky" style="padding:10px 22px 10px 8px;text-align:center;width:105px;">관리</th>\';\n';
  html += '  tHtml += \'</tr></thead><tbody>\';\n';
  html += '  list.forEach(function(p, idx) {\n';
  html += '    const isFirst = (idx === 0);\n';
  html += '    const isLast = (idx === list.length - 1);\n';
  html += '    const pStyle = getSettingsPriorityStyle(p.priority);\n';
  html += '    const sStyle = (function(st) {\n';
  html += '      if (st === "운영 중" || !st) return "background:#f0fdf4;color:#166534;border:1px solid #bbf7d0;";\n';
  html += '      if (st === "확인 필요") return "background:#fffbeb;color:#b45309;border:1px solid #fde68a;";\n';
  html += '      if (st === "신규 발굴") return "background:#eff6ff;color:#1d4ed8;border:1px solid #bfdbfe;";\n';
  html += '      if (st === "보류") return "background:#fef2f2;color:#991b1b;border:1px solid #fecaca;";\n';
  html += '      return "background:#f1f5f9;color:#64748b;border:1px solid #cbd5e1;";\n';
  html += '    })(p.status);\n';
  html += '    const isMoved = (p.row === settingsMovedPartnerRow);\n';
  html += '    tHtml += \'<tr class="\' + (isMoved ? \'settings-row-moved\' : \'\') + \'" style="border-bottom:1px solid #f1f5f9;transition:background 0.15s;" onmouseover="this.style.background=\\\'#f8fafc\\\'" onmouseout="this.style.background=\\\'#ffffff\\\'">\';\n';
  html += '    tHtml += \'<td style="padding:8px 8px 8px 22px;text-align:center;font-weight:700;color:#64748b;border-bottom:1px solid #f1f5f9;white-space:nowrap;">\' + (idx + 1) + \'</td>\';\n';
  html += '    tHtml += \'<td style="padding:8px 6px;text-align:center;border-bottom:1px solid #f1f5f9;white-space:nowrap;">\';\n';
  html += '    tHtml += \'  <div style="display:inline-flex;gap:3px;">\';\n';
  html += '    tHtml += \'    <button type="button" onclick="reorderPartner(\' + p.row + \', \\\'up\\\')" \' + (isFirst ? \'disabled style="opacity:0.3;cursor:not-allowed;\' : \'style="cursor:pointer;\') + \'border:1px solid #cbd5e1;background:#ffffff;border-radius:4px;padding:2px 6px;font-size:10px;font-weight:800;" title="위로 이동">▲</button>\';\n';
  html += '    tHtml += \'    <button type="button" onclick="reorderPartner(\' + p.row + \', \\\'down\\\')" \' + (isLast ? \'disabled style="opacity:0.3;cursor:not-allowed;\' : \'style="cursor:pointer;\') + \'border:1px solid #cbd5e1;background:#ffffff;border-radius:4px;padding:2px 6px;font-size:10px;font-weight:800;" title="아래로 이동">▼</button>\';\n';
  html += '    tHtml += \'  </div>\';\n';
  html += '    tHtml += \'</td>\';\n';
  html += '    tHtml += \'<td style="padding:8px 10px;font-weight:800;color:#0f172a;border-bottom:1px solid #f1f5f9;">\' + escapeSettingsHtml(p.name) + \'</td>\';\n';
  html += '    tHtml += \'<td style="padding:8px 8px;border-bottom:1px solid #f1f5f9;"><span style="display:inline-block;padding:2px 6px;background:#f1f5f9;color:#334155;border-radius:5px;font-size:11.5px;font-weight:700;">\' + escapeSettingsHtml(p.biz || "-") + \'</span></td>\';\n';
  html += '    tHtml += \'<td style="padding:8px 6px;text-align:center;border-bottom:1px solid #f1f5f9;color:#475569;font-size:11.5px;">\' + escapeSettingsHtml(p.category || "-") + \'</td>\';\n';
  html += '    tHtml += \'<td style="padding:8px 6px;text-align:center;border-bottom:1px solid #f1f5f9;"><span style="display:inline-block;padding:2px 6px;border-radius:5px;font-size:11px;font-weight:800;\' + pStyle + \'">\' + escapeSettingsHtml(p.priority || "미지정") + \'</span></td>\';\n';
  html += '    tHtml += \'<td style="padding:8px 8px;border-bottom:1px solid #f1f5f9;color:#334155;font-weight:600;white-space:nowrap;">\' + escapeSettingsHtml(p.manager || "-") + \'</td>\';\n';
  html += '    tHtml += \'<td style="padding:8px 8px;border-bottom:1px solid #f1f5f9;white-space:nowrap;">\';\n';
  html += '    if (p.phone) {\n';
