  html += '    tHtml += \'</td>\';\n';
  html += '    tHtml += \'<td style="padding:8px 6px;text-align:center;border-bottom:1px solid #f1f5f9;"><span style="display:inline-block;padding:2px 6px;border-radius:5px;font-size:11px;font-weight:700;\' + sStyle + \'">\' + escapeSettingsHtml(p.status || "운영 중") + \'</span></td>\';\n';
  html += '    tHtml += \'<td style="padding:8px 8px;border-bottom:1px solid #f1f5f9;color:#475569;font-size:11.5px;">\' + escapeSettingsHtml(p.feature || "-") + \'</td>\';\n';
  html += '    tHtml += \'<td style="padding:8px 8px;border-bottom:1px solid #f1f5f9;color:#475569;font-size:11.5px;">\' + escapeSettingsHtml(p.orderMethod || "-") + \'</td>\';\n';
  html += '    tHtml += \'<td style="padding:8px 8px;border-bottom:1px solid #f1f5f9;color:#64748b;font-size:11.5px;">\' + escapeSettingsHtml(p.note || "-") + \'</td>\';\n';
  html += '    tHtml += \'<td style="padding:8px 22px 8px 6px;text-align:center;border-bottom:1px solid #f1f5f9;">\';\n';
  html += '    tHtml += \'  <div style="display:inline-flex;gap:4px;">\';\n';
  html += '    tHtml += \'    <button type="button" onclick="openEditPartnerModal(\' + p.row + \')" style="border:1px solid #cbd5e1;background:#ffffff;color:#1e293b;border-radius:5px;padding:3px 6px;font-size:11px;font-weight:700;cursor:pointer;">✏️</button>\';\n';
  html += '    tHtml += \'    <button type="button" onclick="deletePartner(\' + p.row + \', \\\'\' + escapeSettingsQuotes(p.name) + \'\\\')" style="border:1px solid #fecaca;background:#fff1f2;color:#e11d48;border-radius:5px;padding:3px 6px;font-size:11px;font-weight:700;cursor:pointer;">🗑️</button>\';\n';
  html += '    tHtml += \'  </div>\';\n';
  html += '    tHtml += \'</td>\';\n';
  html += '    tHtml += \'</tr>\';\n';
  html += '  });\n';
  html += '  tHtml += \'</tbody></table>\';\n';
  html += '  container.innerHTML = tHtml;\n';
  html += '}\n';
  html += '\n';
  html += 'function renderTasksTable(container) {\n';
  html += '  updateSettingsActiveFiltersBar();\n';
  html += '  const rawList = currentSettingsData.tasks || [];\n';
  html += '  const taskCatCounts = {};\n';
  html += '  rawList.forEach(function(t) {\n';
  html += '    const c = t.category || "기타";\n';
  html += '    taskCatCounts[c] = (taskCatCounts[c] || 0) + 1;\n';
  html += '  });\n';
  html += '  let list = rawList.filter(function(t) {\n';
  html += '    if (settingsSearchQuery) {\n';
  html += '      const q = settingsSearchQuery;\n';
  html += '      const match = (t.taskName && t.taskName.toLowerCase().includes(q)) ||\n';
  html += '                    (t.category && t.category.toLowerCase().includes(q)) ||\n';
  html += '                    (t.note && t.note.toLowerCase().includes(q));\n';
  html += '      if (!match) return false;\n';
  html += '    }\n';
  html += '    if (settingsColumnFilters.taskCat && (t.category || "기타") !== settingsColumnFilters.taskCat) return false;\n';
  html += '    return true;\n';
  html += '  });\n';
  html += '  if (list.length === 0) {\n';
  html += '    container.innerHTML = \'<div style="text-align:center;padding:50px 20px;color:#94a3b8;font-weight:600;"><span style="font-size:24px;display:block;margin-bottom:8px;">🔍</span>조건에 일치하는 공종이 없습니다. <button type="button" onclick="clearAllSettingsFilters()" style="margin-top:10px;padding:5px 12px;background:#2563eb;color:#fff;border:none;border-radius:6px;font-size:12px;cursor:pointer;">필터 초기화</button></div>\';\n';
  html += '    return;\n';
  html += '  }\n';
  html += '  let tHtml = \'<table style="width:100%;border-collapse:separate;border-spacing:0;font-size:12px;min-width:750px;margin:0;padding:0;">\';\n';
  html += '  tHtml += \'<thead style="position:sticky;top:0;z-index:20;"><tr>\';\n';
  html += '  tHtml += \'<th class="settings-th-sticky" style="padding:10px 8px 10px 22px;text-align:center;width:65px;">순서</th>\';\n';
  html += '  tHtml += \'<th class="settings-th-sticky" style="padding:10px 8px;text-align:center;width:70px;">순서이동</th>\';\n';
  html += '  tHtml += \'<th class="settings-th-sticky" style="padding:10px 12px;text-align:left;width:180px;">공종명</th>\';\n';
  html += '  tHtml += \'<th class="settings-th-sticky" style="padding:8px 10px;text-align:left;width:140px;">\';\n';
  html += '  tHtml += \'  <div style="font-weight:800;color:#334155;">구분</div>\';\n';
  html += '  tHtml += \'  <select class="settings-filter-select\' + (settingsColumnFilters.taskCat ? \' settings-filter-active\' : \'\') + \'" onchange="onSettingsColumnFilterChange(\\\'taskCat\\\', this.value)">\';\n';
  html += '  tHtml += \'    <option value="">전체 (\' + rawList.length + \')</option>\';\n';
  html += '  Object.keys(taskCatCounts).sort().forEach(function(cKey) {\n';
  html += '    const sel = (settingsColumnFilters.taskCat === cKey) ? \' selected\' : \'\';\n';
  html += '    tHtml += \'  <option value="\' + escapeSettingsHtml(cKey) + \'"\' + sel + \'>\' + escapeSettingsHtml(cKey) + \' (\' + taskCatCounts[cKey] + \')</option>\';\n';
  html += '  });\n';
  html += '  tHtml += \'  </select>\';\n';
  html += '  tHtml += \'</th>\';\n';
  html += '  tHtml += \'<th class="settings-th-sticky" style="padding:10px 12px;text-align:left;">비고 / 작업 설명</th>\';\n';
  html += '  tHtml += \'<th class="settings-th-sticky" style="padding:10px 22px 10px 8px;text-align:center;width:105px;">관리</th>\';\n';
  html += '  tHtml += \'</tr></thead><tbody>\';\n';
  html += '  list.forEach(function(t, idx) {\n';
  html += '    const isFirst = (idx === 0);\n';
  html += '    const isLast = (idx === list.length - 1);\n';
  html += '    const isMoved = (t.row === settingsMovedTaskRow);\n';
  html += '    tHtml += \'<tr class="\' + (isMoved ? \'settings-row-moved\' : \'\') + \'" style="border-bottom:1px solid #f1f5f9;transition:background 0.15s;" onmouseover="this.style.background=\\\'#f8fafc\\\'" onmouseout="this.style.background=\\\'#ffffff\\\'">\';\n';
  html += '    tHtml += \'<td style="padding:9px 8px 9px 22px;text-align:center;font-weight:700;color:#64748b;border-bottom:1px solid #f1f5f9;">\' + (idx + 1) + \'</td>\';\n';
  html += '    tHtml += \'<td style="padding:9px 8px;text-align:center;border-bottom:1px solid #f1f5f9;">\';\n';
  html += '    tHtml += \'  <div style="display:inline-flex;gap:3px;">\';\n';
  html += '    tHtml += \'    <button type="button" onclick="reorderTask(\' + t.row + \', \\\'up\\\')" \' + (isFirst ? \'disabled style="opacity:0.3;cursor:not-allowed;\' : \'style="cursor:pointer;\') + \'border:1px solid #cbd5e1;background:#ffffff;border-radius:4px;padding:2px 6px;font-size:10px;font-weight:800;" title="위로 이동">▲</button>\';\n';
  html += '    tHtml += \'    <button type="button" onclick="reorderTask(\' + t.row + \', \\\'down\\\')" \' + (isLast ? \'disabled style="opacity:0.3;cursor:not-allowed;\' : \'style="cursor:pointer;\') + \'border:1px solid #cbd5e1;background:#ffffff;border-radius:4px;padding:2px 6px;font-size:10px;font-weight:800;" title="아래로 이동">▼</button>\';\n';
  html += '    tHtml += \'  </div>\';\n';
  html += '    tHtml += \'</td>\';\n';
  html += '    tHtml += \'<td style="padding:9px 12px;font-weight:900;color:#0f172a;border-bottom:1px solid #f1f5f9;"><span style="display:inline-block;padding:3px 8px;background:#eff6ff;color:#1d4ed8;border:1px solid #bfdbfe;border-radius:6px;font-size:12.5px;">\' + escapeSettingsHtml(t.taskName) + \'</span></td>\';\n';
  html += '    tHtml += \'<td style="padding:9px 12px;border-bottom:1px solid #f1f5f9;"><span style="display:inline-block;padding:2px 7px;background:#f1f5f9;color:#475569;border-radius:5px;font-size:11.5px;font-weight:700;">\' + escapeSettingsHtml(t.category || "기타") + \'</span></td>\';\n';
  html += '    tHtml += \'<td style="padding:9px 12px;border-bottom:1px solid #f1f5f9;color:#64748b;font-size:12px;">\' + escapeSettingsHtml(t.note || "-") + \'</td>\';\n';
  html += '    tHtml += \'<td style="padding:9px 22px 9px 8px;text-align:center;border-bottom:1px solid #f1f5f9;">\';\n';
  html += '    tHtml += \'  <div style="display:inline-flex;gap:4px;">\';\n';
  html += '    tHtml += \'    <button type="button" onclick="openEditTaskModal(\' + t.row + \')" style="border:1px solid #cbd5e1;background:#ffffff;color:#1e293b;border-radius:5px;padding:3px 6px;font-size:11px;font-weight:700;cursor:pointer;">✏️</button>\';\n';
  html += '    tHtml += \'    <button type="button" onclick="deleteTask(\' + t.row + \', \\\'\' + escapeSettingsQuotes(t.taskName) + \'\\\')" style="border:1px solid #fecaca;background:#fff1f2;color:#e11d48;border-radius:5px;padding:3px 6px;font-size:11px;font-weight:700;cursor:pointer;">🗑️</button>\';\n';
  html += '    tHtml += \'  </div>\';\n';
  html += '    tHtml += \'</td>\';\n';
  html += '    tHtml += \'</tr>\';\n';
  html += '  });\n';
  html += '  tHtml += \'</tbody></table>\';\n';
  html += '  container.innerHTML = tHtml;\n';
  html += '}\n';
  html += '\n';
  html += 'function renderMembersTable(container) {\n';
  html += '  updateSettingsActiveFiltersBar();\n';
  html += '  const rawList = currentSettingsData.members || [];\n';
  html += '  const roleCounts = {};\n';
  html += '  let recvYesCount = 0, recvNoCount = 0;\n';
  html += '  rawList.forEach(function(m) {\n';
  html += '    const r = m.role || "미지정";\n';
  html += '    roleCounts[r] = (roleCounts[r] || 0) + 1;\n';
  html += '    if (m.receive !== false && String(m.receive) !== "false") recvYesCount++;\n';
  html += '    else recvNoCount++;\n';
  html += '  });\n';
  html += '  let list = rawList.filter(function(m) {\n';
  html += '    if (settingsSearchQuery) {\n';
  html += '      const q = settingsSearchQuery;\n';
  html += '      const match = (m.name && m.name.toLowerCase().includes(q)) ||\n';
  html += '                    (m.role && m.role.toLowerCase().includes(q)) ||\n';
  html += '                    (m.phone && m.phone.includes(q)) ||\n';
  html += '                    (m.email && m.email.toLowerCase().includes(q)) ||\n';
  html += '                    (m.note && m.note.toLowerCase().includes(q));\n';
  html += '      if (!match) return false;\n';
  html += '    }\n';
  html += '    if (settingsColumnFilters.memberRole && (m.role || "미지정") !== settingsColumnFilters.memberRole) return false;\n';
  html += '    if (settingsColumnFilters.memberReceive) {\n';
  html += '      const isRecv = (m.receive !== false && String(m.receive) !== "false");\n';
  html += '      if (settingsColumnFilters.memberReceive === "Y" && !isRecv) return false;\n';
  html += '      if (settingsColumnFilters.memberReceive === "N" && isRecv) return false;\n';
  html += '    }\n';
  html += '    return true;\n';
  html += '  });\n';
  html += '  if (list.length === 0) {\n';
  html += '    container.innerHTML = \'<div style="text-align:center;padding:50px 20px;color:#94a3b8;font-weight:600;"><span style="font-size:24px;display:block;margin-bottom:8px;">🔍</span>조건에 일치하는 구성원이 없습니다. <button type="button" onclick="clearAllSettingsFilters()" style="margin-top:10px;padding:5px 12px;background:#2563eb;color:#fff;border:none;border-radius:6px;font-size:12px;cursor:pointer;">필터 초기화</button></div>\';\n';
  html += '    return;\n';
  html += '  }\n';
  html += '  let tHtml = \'<table style="width:100%;border-collapse:separate;border-spacing:0;font-size:12px;min-width:980px;margin:0;padding:0;">\';\n';
  html += '  tHtml += \'<thead style="position:sticky;top:0;z-index:20;"><tr>\';\n';
  html += '  tHtml += \'<th class="settings-th-sticky" style="padding:10px 8px 10px 22px;text-align:center;width:55px;white-space:nowrap;">순서</th>\';\n';
  html += '  tHtml += \'<th class="settings-th-sticky" style="padding:10px 6px;text-align:center;width:65px;white-space:nowrap;">순서이동</th>\';\n';
  html += '  tHtml += \'<th class="settings-th-sticky" style="padding:10px 12px;text-align:left;width:105px;white-space:nowrap;">이름 (성명)</th>\';\n';
  html += '  tHtml += \'<th class="settings-th-sticky" style="padding:8px 10px;text-align:left;width:115px;white-space:nowrap;">\';\n';
  html += '  tHtml += \'  <div style="font-weight:800;color:#334155;">직급 / 역할</div>\';\n';
  html += '  tHtml += \'  <select class="settings-filter-select\' + (settingsColumnFilters.memberRole ? \' settings-filter-active\' : \'\') + \'" onchange="onSettingsColumnFilterChange(\\\'memberRole\\\', this.value)">\';\n';
  html += '  tHtml += \'    <option value="">전체 (\' + rawList.length + \')</option>\';\n';
  html += '  Object.keys(roleCounts).sort().forEach(function(rKey) {\n';
  html += '    const sel = (settingsColumnFilters.memberRole === rKey) ? \' selected\' : \'\';\n';
  html += '    tHtml += \'  <option value="\' + escapeSettingsHtml(rKey) + \'"\' + sel + \'>\' + escapeSettingsHtml(rKey) + \' (\' + roleCounts[rKey] + \')</option>\';\n';
  html += '  });\n';
  html += '  tHtml += \'  </select>\';\n';
  html += '  tHtml += \'</th>\';\n';
  html += '  tHtml += \'<th class="settings-th-sticky" style="padding:10px 10px;text-align:left;width:155px;white-space:nowrap;">연락처</th>\';\n';
  html += '  tHtml += \'<th class="settings-th-sticky" style="padding:10px 10px;text-align:left;width:220px;white-space:nowrap;">이메일</th>\';\n';
  html += '  tHtml += \'<th class="settings-th-sticky" style="padding:8px 8px;text-align:center;width:125px;white-space:nowrap;">\';\n';
  html += '  tHtml += \'  <div style="font-weight:800;color:#334155;">알림톡/브리핑</div>\';\n';
  html += '  tHtml += \'  <select class="settings-filter-select\' + (settingsColumnFilters.memberReceive ? \' settings-filter-active\' : \'\') + \'" onchange="onSettingsColumnFilterChange(\\\'memberReceive\\\', this.value)">\';\n';
  html += '  tHtml += \'    <option value="">전체</option>\';\n';
  html += '  tHtml += \'    <option value="Y"\' + (settingsColumnFilters.memberReceive === "Y" ? \' selected\' : \'\') + \'>수신함 (\' + recvYesCount + \')</option>\';\n';
  html += '  tHtml += \'    <option value="N"\' + (settingsColumnFilters.memberReceive === "N" ? \' selected\' : \'\') + \'>미수신 (\' + recvNoCount + \')</option>\';\n';
  html += '  tHtml += \'  </select>\';\n';
  html += '  tHtml += \'</th>\';\n';
  html += '  tHtml += \'<th class="settings-th-sticky" style="padding:10px 10px;text-align:left;min-width:140px;">비고 / 메모</th>\';\n';
  html += '  tHtml += \'<th class="settings-th-sticky" style="padding:10px 22px 10px 8px;text-align:center;width:90px;white-space:nowrap;">관리</th>\';\n';
  html += '  tHtml += \'</tr></thead><tbody>\';\n';
  html += '  list.forEach(function(m, idx) {\n';
  html += '    const isFirst = (idx === 0);\n';
  html += '    const isLast = (idx === list.length - 1);\n';
  html += '    const isMoved = (m.row === settingsMovedMemberRow);\n';
  html += '    const isRecv = (m.receive !== false && String(m.receive) !== "false");\n';
  html += '    tHtml += \'<tr class="\' + (isMoved ? \'settings-row-moved\' : \'\') + \'" style="border-bottom:1px solid #f1f5f9;transition:background 0.15s;" onmouseover="this.style.background=\\\'#f8fafc\\\'" onmouseout="this.style.background=\\\'#ffffff\\\'">\';\n';
  html += '    tHtml += \'<td style="padding:8px 8px 8px 22px;text-align:center;font-weight:700;color:#64748b;border-bottom:1px solid #f1f5f9;white-space:nowrap;">\' + (idx + 1) + \'</td>\';\n';
  html += '    tHtml += \'<td style="padding:8px 6px;text-align:center;border-bottom:1px solid #f1f5f9;white-space:nowrap;">\';\n';
  html += '    tHtml += \'  <div style="display:inline-flex;gap:3px;">\';\n';
  html += '    tHtml += \'    <button type="button" onclick="reorderMember(\' + m.row + \', \\\'up\\\')" \' + (isFirst ? \'disabled style="opacity:0.3;cursor:not-allowed;\' : \'style="cursor:pointer;\') + \'border:1px solid #cbd5e1;background:#ffffff;border-radius:4px;padding:2px 6px;font-size:10px;font-weight:800;" title="위로 이동">▲</button>\';\n';
  html += '    tHtml += \'    <button type="button" onclick="reorderMember(\' + m.row + \', \\\'down\\\')" \' + (isLast ? \'disabled style="opacity:0.3;cursor:not-allowed;\' : \'style="cursor:pointer;\') + \'border:1px solid #cbd5e1;background:#ffffff;border-radius:4px;padding:2px 6px;font-size:10px;font-weight:800;" title="아래로 이동">▼</button>\';\n';
  html += '    tHtml += \'  </div>\';\n';
  html += '    tHtml += \'</td>\';\n';
  html += '    tHtml += \'<td style="padding:8px 12px;font-weight:900;color:#0f172a;border-bottom:1px solid #f1f5f9;white-space:nowrap;"><span style="display:inline-block;padding:2px 8px;background:#f0fdf4;color:#166534;border:1px solid #bbf7d0;border-radius:6px;font-size:12.5px;">\' + escapeSettingsHtml(m.name) + \'</span></td>\';\n';
  html += '    tHtml += \'<td style="padding:8px 10px;border-bottom:1px solid #f1f5f9;white-space:nowrap;"><span style="display:inline-block;padding:2px 7px;background:#f1f5f9;color:#334155;border-radius:5px;font-size:11.5px;font-weight:700;">\' + escapeSettingsHtml(m.role || "미지정") + \'</span></td>\';\n';
  html += '    tHtml += \'<td style="padding:8px 10px;border-bottom:1px solid #f1f5f9;white-space:nowrap;">\';\n';
  html += '    if (m.phone) {\n';
  html += '      tHtml += \'  <a href="tel:\' + escapeSettingsHtml(m.phone) + \'" style="color:#2563eb;text-decoration:none;font-weight:700;font-size:11.5px;white-space:nowrap;display:inline-block;">📞 \' + escapeSettingsHtml(m.phone) + \'</a>\';\n';
  html += '    } else {\n';
  html += '      tHtml += \'  <span style="color:#94a3b8;">-</span>\';\n';
  html += '    }\n';
  html += '    tHtml += \'</td>\';\n';
  html += '    tHtml += \'<td style="padding:8px 10px;border-bottom:1px solid #f1f5f9;white-space:nowrap;">\';\n';
  html += '    if (m.email) {\n';
  html += '      tHtml += \'  <a href="mailto:\' + escapeSettingsHtml(m.email) + \'" style="color:#0284c7;text-decoration:none;font-size:11.5px;white-space:nowrap;display:inline-block;">\' + escapeSettingsHtml(m.email) + \'</a>\';\n';
  html += '    } else {\n';
  html += '      tHtml += \'  <span style="color:#94a3b8;">-</span>\';\n';
  html += '    }\n';
  html += '    tHtml += \'</td>\';\n';
  html += '    tHtml += \'<td style="padding:8px 8px;text-align:center;border-bottom:1px solid #f1f5f9;white-space:nowrap;">\';\n';
  html += '    tHtml += \'  <button type="button" onclick="toggleMemberReceive(\' + m.row + \')" style="border:none;cursor:pointer;padding:3px 8px;border-radius:6px;font-size:11px;font-weight:800;transition:all 0.15s;white-space:nowrap;\' + (isRecv ? \'background:#dcfce7;color:#15803d;border:1px solid #86efac;\' : \'background:#f1f5f9;color:#94a3b8;border:1px solid #cbd5e1;\') + \'" title="클릭 시 수신 상태 즉시 전환">\';\n';
  html += '    tHtml += (isRecv ? \'🔔 수신 대상\' : \'🔕 미수신\');\n';
  html += '    tHtml += \'  </button>\';\n';
  html += '    tHtml += \'</td>\';\n';
  html += '    tHtml += \'<td style="padding:8px 10px;border-bottom:1px solid #f1f5f9;color:#64748b;font-size:11.5px;">\' + escapeSettingsHtml(m.note || "-") + \'</td>\';\n';
  html += '    tHtml += \'<td style="padding:8px 22px 8px 6px;text-align:center;border-bottom:1px solid #f1f5f9;white-space:nowrap;">\';\n';
  html += '    tHtml += \'  <div style="display:inline-flex;gap:4px;">\';\n';
  html += '    tHtml += \'    <button type="button" onclick="openEditMemberModal(\' + m.row + \')" style="border:1px solid #cbd5e1;background:#ffffff;color:#1e293b;border-radius:5px;padding:3px 6px;font-size:11px;font-weight:700;cursor:pointer;">✏️</button>\';\n';
  html += '    tHtml += \'    <button type="button" onclick="deleteMember(\' + m.row + \', \\\'\' + escapeSettingsQuotes(m.name) + \'\\\')" style="border:1px solid #fecaca;background:#fff1f2;color:#e11d48;border-radius:5px;padding:3px 6px;font-size:11px;font-weight:700;cursor:pointer;">🗑️</button>\';\n';
  html += '    tHtml += \'  </div>\';\n';
  html += '    tHtml += \'</td>\';\n';
  html += '    tHtml += \'</tr>\';\n';
  html += '  });\n';
  html += '  tHtml += \'</tbody></table>\';\n';
  html += '  container.innerHTML = tHtml;\n';
  html += '}\n';
  html += '\n';
  html += 'function getSettingsPriorityStyle(priority) {\n';
  html += '  const p = String(priority || "").trim();\n';
  html += '  if (p === "A팀") return "background:#eff6ff;color:#1d4ed8;border:1px solid #bfdbfe;";\n';
  html += '  if (p === "B팀") return "background:#f0fdf4;color:#166534;border:1px solid #bbf7d0;";\n';
  html += '  if (p === "C팀") return "background:#fefce8;color:#854d0e;border:1px solid #fef08a;";\n';
  html += '  if (p === "본사") return "background:#faf5ff;color:#6b21a8;border:1px solid #e9d5ff;";\n';
  html += '  if (p === "LX 대리점") return "background:#f0fdfa;color:#0f766e;border:1px solid #99f6e4;";\n';
  html += '  return "background:#f1f5f9;color:#64748b;border:1px solid #e2e8f0;";\n';
  html += '}\n';
  html += '\n';
  html += 'function escapeSettingsHtml(str) {\n';
  html += '  if (!str) return "";\n';
  html += '  return String(str)\n';
  html += '    .replace(/&/g, "&amp;")\n';
  html += '    .replace(/</g, "&lt;")\n';
  html += '    .replace(/>/g, "&gt;")\n';
  html += '    .replace(/"/g, "&quot;")\n';
  html += '    .replace(/\'/g, "&#039;");\n';
  html += '}\n';
  html += '\n';
  html += 'function escapeSettingsQuotes(str) {\n';
  html += '  if (!str) return "";\n';
  html += '  return String(str).replace(/\'/g, "\\\\\'").replace(/"/g, "&quot;");\n';
  html += '}\n';
  html += '\n';
  html += 'function openAddPartnerModal() {\n';
  html += '  editingPartnerRow = null;\n';
  html += '  const title = document.getElementById("partnerFormTitle");\n';
  html += '  if (title) title.innerText = "🤝 신규 거래처 등록";\n';
  html += '  document.getElementById("partnerInpName").value = "";\n';
  html += '  document.getElementById("partnerInpBiz").value = "";\n';
  html += '  document.getElementById("partnerInpCategory").value = "시공";\n';
  html += '  document.getElementById("partnerInpPriority").value = "A팀";\n';
  html += '  document.getElementById("partnerInpManager").value = "";\n';
  html += '  document.getElementById("partnerInpPhone").value = "";\n';
  html += '  document.getElementById("partnerInpStatus").value = "운영 중";\n';
  html += '  document.getElementById("partnerInpOrderMethod").value = "";\n';
  html += '  document.getElementById("partnerInpFeature").value = "";\n';
  html += '  document.getElementById("partnerInpNote").value = "";\n';
  html += '  const dl = document.getElementById("partnerBizSuggestions");\n';
  html += '  if (dl) {\n';
  html += '    dl.innerHTML = "";\n';
  html += '    const taskList = currentSettingsData.tasks || [];\n';
  html += '    taskList.forEach(function(t) {\n';
  html += '      const opt = document.createElement("option");\n';
  html += '      opt.value = t.taskName;\n';
  html += '      dl.appendChild(opt);\n';
  html += '    });\n';
  html += '  }\n';
  html += '  const modal = document.getElementById("partnerFormModal");\n';
  html += '  if (modal) modal.style.display = "flex";\n';
  html += '}\n';
  html += '\n';
  html += 'function openEditPartnerModal(row) {\n';
  html += '  const p = (currentSettingsData.partners || []).find(function(item) { return item.row === row; });\n';
  html += '  if (!p) {\n';
  html += '    showToast("⚠️ 해당 거래처 데이터를 찾을 수 없습니다.");\n';
  html += '    return;\n';
  html += '  }\n';
  html += '  editingPartnerRow = row;\n';
  html += '  const title = document.getElementById("partnerFormTitle");\n';
  html += '  if (title) title.innerText = "🤝 거래처 정보 수정";\n';
  html += '  document.getElementById("partnerInpName").value = p.name || "";\n';
  html += '  document.getElementById("partnerInpBiz").value = p.biz || "";\n';
  html += '  document.getElementById("partnerInpCategory").value = p.category || "시공";\n';
  html += '  document.getElementById("partnerInpPriority").value = p.priority || "미지정";\n';
  html += '  document.getElementById("partnerInpManager").value = p.manager || "";\n';
  html += '  document.getElementById("partnerInpPhone").value = p.phone || "";\n';
  html += '  document.getElementById("partnerInpStatus").value = p.status || "운영 중";\n';
  html += '  document.getElementById("partnerInpOrderMethod").value = p.orderMethod || "";\n';
  html += '  document.getElementById("partnerInpFeature").value = p.feature || "";\n';
  html += '  document.getElementById("partnerInpNote").value = p.note || "";\n';
  html += '  const dl = document.getElementById("partnerBizSuggestions");\n';
  html += '  if (dl) {\n';
  html += '    dl.innerHTML = "";\n';
  html += '    const taskList = currentSettingsData.tasks || [];\n';
  html += '    taskList.forEach(function(t) {\n';
  html += '      const opt = document.createElement("option");\n';
  html += '      opt.value = t.taskName;\n';
  html += '      dl.appendChild(opt);\n';
  html += '    });\n';
  html += '  }\n';
  html += '  const modal = document.getElementById("partnerFormModal");\n';
  html += '  if (modal) modal.style.display = "flex";\n';
  html += '}\n';
  html += '\n';
  html += 'function closePartnerFormModal() {\n';
  html += '  const modal = document.getElementById("partnerFormModal");\n';
  html += '  if (modal) modal.style.display = "none";\n';
  html += '  editingPartnerRow = null;\n';
  html += '}\n';
  html += '\n';
  html += 'function savePartnerForm() {\n';
  html += '  const name = (document.getElementById("partnerInpName") || {}).value.trim();\n';
  html += '  const biz = (document.getElementById("partnerInpBiz") || {}).value.trim();\n';
  html += '  if (!name) {\n';
  html += '    alert("업체/반장명을 입력해주세요.");\n';
  html += '    return;\n';
  html += '  }\n';
  html += '  const payload = {\n';
  html += '    name: name,\n';
  html += '    biz: biz,\n';
  html += '    category: (document.getElementById("partnerInpCategory") || {}).value || "시공",\n';
  html += '    priority: (document.getElementById("partnerInpPriority") || {}).value || "미지정",\n';
  html += '    manager: (document.getElementById("partnerInpManager") || {}).value.trim() || "",\n';
  html += '    phone: (document.getElementById("partnerInpPhone") || {}).value.trim() || "",\n';
  html += '    status: (document.getElementById("partnerInpStatus") || {}).value || "운영 중",\n';
  html += '    orderMethod: (document.getElementById("partnerInpOrderMethod") || {}).value.trim() || "",\n';
  html += '    feature: (document.getElementById("partnerInpFeature") || {}).value.trim() || "",\n';
  html += '    note: (document.getElementById("partnerInpNote") || {}).value.trim() || "",\n';
  html += '    dropdownVal: biz ? (biz + "_" + name) : name\n';
  html += '  };\n';
  html += '  if (editingPartnerRow) {\n';
  html += '    const p = (currentSettingsData.partners || []).find(function(item) { return item.row === editingPartnerRow; });\n';
  html += '    if (p) {\n';
  html += '      Object.assign(p, payload);\n';
  html += '      settingsMovedPartnerRow = p.row;\n';
  html += '    }\n';
  html += '    showToast("✏️ 거래처 정보가 수정되었습니다. (하단 [저장하기]를 누르면 시트에 일괄 반영됩니다)");\n';
  html += '  } else {\n';
  html += '    let maxRow = 1;\n';
  html += '    (currentSettingsData.partners || []).forEach(function(item) { if (item.row > maxRow) maxRow = item.row; });\n';
  html += '    payload.row = maxRow + 1;\n';
  html += '    currentSettingsData.partners.unshift(payload);\n';
  html += '    settingsMovedPartnerRow = payload.row;\n';
  html += '    showToast("➕ 신규 거래처가 추가되었습니다. (하단 [저장하기]를 누르면 시트에 일괄 반영됩니다)");\n';
  html += '  }\n';
  html += '  closePartnerFormModal();\n';
  html += '  markSettingsChanged();\n';
  html += '  renderSettingsView();\n';
  html += '}\n';
  html += '\n';
