  html += '    showToast("❌ 서버 통신 오류: " + err);\n';
  html += '  });\n';
  html += '}\n';
  html += '\n';
  html += 'function callSettingsApi(action, params, onSuccess, onError) {\n';
  html += '  if (typeof google !== "undefined" && google.script && google.script.run) {\n';
  html += '    var runner = google.script.run\n';
  html += '      .withSuccessHandler(onSuccess)\n';
  html += '      .withFailureHandler(onError || function(err) { showToast("❌ 통신 오류: " + err); });\n';
  html += '    if (action === "getSettingsData") runner.getSettingsManagementData();\n';
  html += '    else if (action === "saveAllSettingsBatch") runner.saveAllSettingsBatchFromWeb(params.data);\n';
  html += '    else if (action === "addMember") runner.addMemberItemFromWeb(params.data);\n';
  html += '    else if (action === "updateMember") runner.updateMemberItemFromWeb(params.row, params.data);\n';
  html += '    else if (action === "deleteMember") runner.deleteMemberItemFromWeb(params.row, params.name);\n';
  html += '    else if (action === "reorderMember") runner.reorderMemberItemFromWeb(params.row, params.direction);\n';
  html += '  } else {\n';
  html += '    var apiUrl = (typeof SCRIPT_URL !== "undefined" ? SCRIPT_URL : (window.location.href.split("?")[0]));\n';
  html += '    var qs = "?action=" + encodeURIComponent(action);\n';
  html += '    if (params) {\n';
  html += '      for (var k in params) {\n';
  html += '        if (params.hasOwnProperty(k)) {\n';
  html += '          var val = params[k];\n';
  html += '          if (typeof val === "object") val = JSON.stringify(val);\n';
  html += '          qs += "&" + encodeURIComponent(k) + "=" + encodeURIComponent(val);\n';
  html += '        }\n';
  html += '      }\n';
  html += '    }\n';
  html += '    fetch(apiUrl + qs)\n';
  html += '      .then(function(r) { return r.json(); })\n';
  html += '      .then(onSuccess)\n';
  html += '      .catch(onError || function(err) { showToast("❌ 통신 에러: " + err); });\n';
  html += '  }\n';
  html += '}\n';
  html += '\n';

  // ========================================================
  // [To-Do 매트릭스 보드 클라이언트 엔진]
  // ========================================================
  html += 'function formatTodoDateYmd(d) {\n';
  html += '  if (!d) return "";\n';
  html += '  if (d instanceof Date) {\n';
  html += '    if (isNaN(d.getTime())) return "";\n';
  html += '    const y = d.getFullYear();\n';
  html += '    const m = String(d.getMonth() + 1).padStart(2, "0");\n';
  html += '    const day = String(d.getDate()).padStart(2, "0");\n';
  html += '    return y + "-" + m + "-" + day;\n';
  html += '  }\n';
  html += '  let s = String(d).trim().replace(/\\./g, "-").replace(/\\//g, "-");\n';
  html += '  const parts = s.split("-");\n';
  html += '  if (parts.length === 3) {\n';
  html += '    const y = parts[0].length === 2 ? ("20" + parts[0]) : parts[0];\n';
  html += '    const m = parts[1].padStart(2, "0");\n';
  html += '    const day = parts[2].padStart(2, "0");\n';
  html += '    return y + "-" + m + "-" + day;\n';
  html += '  }\n';
  html += '  return s;\n';
  html += '}\n';
  html += 'function formatDateYYMMDD(d) {\n';
  html += '  return formatTodoDateYmd(d);\n';
  html += '}\n';
  html += 'let todoDataList = [];\n';
  html += 'let todoMembersList = [];\n';
  html += 'let todoActiveSitesList = [];\n';
  html += 'let currentTodoMemberFilter = "all";\n';
  html += 'let todoDraggedId = null;\n';
  html += 'let isTodoLoaded = false;\n';
  html += 'let currentEditingTodoId = null;\n';
  html += 'let expandedCompletedManagers = new Set();\n';
  html += 'let mobileTodoViewType = "manager";\n';
  html += 'let mobileTodoSelectedStatusTab = "important";\n';
  html += 'let collapsedManagerSet = new Set();\n';
  html += '\n';
  html += 'function setMobileTodoViewType(type) {\n';
  html += '  mobileTodoViewType = type || "manager";\n';
  html += '  renderTodoDashboard();\n';
  html += '}\n';
  html += 'function setMobileTodoStatusTab(tab) {\n';
  html += '  mobileTodoSelectedStatusTab = tab || "important";\n';
  html += '  renderTodoDashboard();\n';
  html += '}\n';
  html += 'function toggleManagerCollapse(mem) {\n';
  html += '  if (collapsedManagerSet.has(mem)) collapsedManagerSet.delete(mem);\n';
  html += '  else collapsedManagerSet.add(mem);\n';
  html += '  renderTodoDashboard();\n';
  html += '}\n';
  html += '\n';
  html += 'function changeTodoStatusQuick(id, newStatus) {\n';
  html += '  const item = (todoDataList || []).find(it => it.id === id);\n';
  html += '  if (!item) return;\n';
  html += '  item.status = newStatus;\n';
  html += '  if (newStatus === "중요") {\n';
  html += '    item.isImportant = true;\n';
  html += '  } else if (newStatus === "미완료") {\n';
  html += '    item.isImportant = false;\n';
  html += '  }\n';
  html += '  if (newStatus === "완료") {\n';
  html += '    item.completedAt = formatDateYYMMDD(new Date()) + " " + (new Date().toTimeString().slice(0, 8));\n';
  html += '  } else {\n';
  html += '    item.completedAt = "";\n';
  html += '  }\n';
  html += '  renderTodoDashboard();\n';
  html += '  showToast("💾 [" + item.title + "] " + newStatus + "(으)로 변경 중...");\n';
  html += '  if (typeof google !== "undefined" && google.script && google.script.run) {\n';
  html += '    google.script.run\n';
  html += '      .withSuccessHandler(res => {\n';
  html += '        if (res && res.success) showToast("✅ [" + item.title + "] " + newStatus + "(으)로 변경되었습니다.");\n';
  html += '        else { showToast("❌ 상태 저장 실패: " + ((res && res.error) || "")); loadTodoList(true); }\n';
  html += '      })\n';
  html += '      .withFailureHandler(err => {\n';
  html += '        showToast("❌ 통신 오류: " + err);\n';
  html += '        loadTodoList(true);\n';
  html += '      })\n';
  html += '      .updateTodoStatusFromWeb(id, newStatus, item.manager, item.isImportant);\n';
  html += '  } else {\n';
  html += '    const apiUrl = (typeof SCRIPT_URL !== "undefined" ? SCRIPT_URL : (window.location.href.split("?")[0]));\n';
  html += '    fetch(apiUrl + "?action=updateTodoStatus&id=" + encodeURIComponent(id) + "&status=" + encodeURIComponent(newStatus) + "&manager=" + encodeURIComponent(item.manager || "") + "&isImportant=" + encodeURIComponent(item.isImportant ? "true" : "false"))\n';
  html += '      .then(r => r.json()).then(res => {\n';
  html += '        if (res && res.success) showToast("✅ [" + item.title + "] " + newStatus + "(으)로 변경되었습니다.");\n';
  html += '        else { showToast("❌ 실패: " + res.error); loadTodoList(true); }\n';
  html += '      })\n';
  html += '      .catch(err => { showToast("❌ 통신 에러: " + err); loadTodoList(true); });\n';
  html += '  }\n';
  html += '}\n';
  html += '\n';
  html += 'function renderMobileTodoCardHtml(card, todayYmd, showManagerBadge) {\n';
  html += '  const isDone = (card.status === "완료");\n';
  html += '  const isOverdue = (!isDone && card.dueDate && card.dueDate < todayYmd);\n';
  html += '  const isImp = (card.isImportant === true || card.status === "중요") && !isDone;\n';
  html += '  let cHtml = "";\n';
  html += '  cHtml += \'<div class="mobile-todo-card" style="background:#ffffff;border:1.5px solid \' + (isOverdue ? "#fca5a5;box-shadow:0 1px 3px rgba(225,29,72,0.08);" : (isImp ? "#fde68a;box-shadow:0 1px 3px rgba(217,119,6,0.08);" : "#e2e8f0;")) + \'border-radius:10px;padding:12px;margin-bottom:10px;">\';\n';
  html += '  cHtml += \'  <div style="display:flex;align-items:flex-start;justify-content:space-between;gap:8px;">\';\n';
  html += '  cHtml += \'    <label style="display:inline-flex;align-items:center;gap:8px;flex:1;min-width:0;margin:0;cursor:pointer;">\';\n';
  html += '  cHtml += \'      <input type="checkbox" \' + (isDone ? "checked" : "") + \' onclick="event.stopPropagation();toggleTodoComplete(\\\'\' + card.id + \'\\\', this.checked)" style="width:17px;height:17px;cursor:pointer;accent-color:#2563eb;flex-shrink:0;">\';\n';
  html += '  cHtml += \'      <span style="font-size:14px;font-weight:800;color:\' + (isDone ? "#94a3b8" : "#0f172a") + \';\' + (isDone ? "text-decoration:line-through;" : "") + \'word-break:break-all;line-height:1.4;">\' + escapeHtml(card.title) + \'</span>\';\n';
  html += '  cHtml += \'    </label>\';\n';
  html += '  cHtml += \'    <div style="display:flex;align-items:center;gap:6px;flex-shrink:0;">\';\n';
  html += '  cHtml += \'      <span onclick="event.stopPropagation();toggleTodoImportant(\\\'\' + card.id + \'\\\')" style="cursor:pointer;font-size:16px;color:\' + (card.isImportant ? "#eab308" : "#cbd5e1") + \';" title="중요 표시 토글">★</span>\';\n';
  html += '  cHtml += \'      <span onclick="event.stopPropagation();openEditTodoModal(\\\'\' + card.id + \'\\\')" style="cursor:pointer;font-size:13px;color:#64748b;padding:2px 4px;" title="수정">✏️</span>\';\n';
  html += '  cHtml += \'      <span onclick="event.stopPropagation();confirmDeleteTodo(\\\'\' + card.id + \'\\\')" style="cursor:pointer;font-size:13px;color:#cbd5e1;padding:2px 4px;" title="삭제">🗑️</span>\';\n';
  html += '  cHtml += \'    </div>\';\n';
  html += '  cHtml += \'  </div>\';\n';
  html += '  cHtml += \'  <div style="display:flex;align-items:center;gap:5px;flex-wrap:wrap;margin-top:8px;font-size:11px;">\';\n';
  html += '  if (showManagerBadge && card.manager) {\n';
  html += '    cHtml += \'    <span style="background:#eff6ff;color:#1d4ed8;padding:2px 7px;border-radius:4px;font-weight:800;">👤 \' + escapeHtml(card.manager) + \'</span>\';\n';
  html += '  } else if (showManagerBadge && !card.manager) {\n';
  html += '    cHtml += \'    <span style="background:#f1f5f9;color:#94a3b8;padding:2px 7px;border-radius:4px;font-weight:700;">👤 미지정</span>\';\n';
  html += '  }\n';
  html += '  if (card.tag) {\n';
  html += '    cHtml += \'    <span style="background:#e0f2fe;color:#0369a1;padding:2px 6px;border-radius:4px;font-weight:700;">\' + escapeHtml(card.tag) + \'</span>\';\n';
  html += '  }\n';
  html += '  if (card.siteName) {\n';
  html += '    cHtml += \'    <span style="background:#f1f5f9;color:#475569;padding:2px 6px;border-radius:4px;font-weight:600;">📍 \' + escapeHtml(card.siteName) + \'</span>\';\n';
  html += '  }\n';
  html += '  if (card.dueDate) {\n';
  html += '    cHtml += \'    <span style="color:\' + (isOverdue ? "#e11d48;font-weight:800;background:#fff1f2;padding:2px 6px;border-radius:4px;" : "#64748b;") + \'">📅 \' + escapeHtml(card.dueDate) + (isOverdue ? " (지남)" : "") + \'</span>\';\n';
  html += '  }\n';
  html += '  cHtml += \'  </div>\';\n';
  html += '  if (card.detail) {\n';
  html += '    cHtml += \'  <div style="margin-top:6px;padding:6px 8px;background:#f8fafc;border-radius:6px;font-size:12px;color:#475569;line-height:1.4;word-break:break-word;">\' + escapeHtml(card.detail) + \'</div>\';\n';
  html += '  }\n';
  html += '  const curSt = card.status || "미완료";\n';
  html += '  cHtml += \'  <div style="display:flex;align-items:center;justify-content:space-between;margin-top:10px;padding-top:8px;border-top:1px dashed #f1f5f9;">\';\n';
  html += '  cHtml += \'    <span style="font-size:11px;font-weight:700;color:#94a3b8;">상태 변경</span>\';\n';
  html += '  cHtml += \'    <div style="display:inline-flex;gap:4px;">\';\n';
  html += '  cHtml += \'      <button type="button" onclick="event.stopPropagation();changeTodoStatusQuick(\\\'\' + card.id + \'\\\', \\\'미완료\\\')" style="padding:4px 9px;border-radius:5px;border:1px solid \' + (curSt === "미완료" && !card.isImportant ? "#64748b;background:#f1f5f9;color:#1e293b;font-weight:800;" : "#e2e8f0;background:#ffffff;color:#94a3b8;font-weight:600;") + \'font-size:11px;cursor:pointer;">미완료</button>\';\n';
  html += '  cHtml += \'      <button type="button" onclick="event.stopPropagation();changeTodoStatusQuick(\\\'\' + card.id + \'\\\', \\\'중요\\\')" style="padding:4px 9px;border-radius:5px;border:1px solid \' + (curSt === "중요" || card.isImportant ? "#fde68a;background:#fffbeb;color:#d97706;font-weight:800;" : "#e2e8f0;background:#ffffff;color:#94a3b8;font-weight:600;") + \'font-size:11px;cursor:pointer;">★ 중요</button>\';\n';
  html += '  cHtml += \'      <button type="button" onclick="event.stopPropagation();changeTodoStatusQuick(\\\'\' + card.id + \'\\\', \\\'완료\\\')" style="padding:4px 9px;border-radius:5px;border:1px solid \' + (curSt === "완료" ? "#86efac;background:#f0fdf4;color:#16a34a;font-weight:800;" : "#e2e8f0;background:#ffffff;color:#94a3b8;font-weight:600;") + \'font-size:11px;cursor:pointer;">✅ 완료</button>\';\n';
  html += '  cHtml += \'    </div>\';\n';
  html += '  cHtml += \'  </div>\';\n';
  html += '  cHtml += \'</div>\';\n';
  html += '  return cHtml;\n';
  html += '}\n';
  html += '\n';

  html += 'function toggleCompletedExpand(mem) {\n';
  html += '  if (expandedCompletedManagers.has(mem)) {\n';
  html += '    expandedCompletedManagers.delete(mem);\n';
  html += '  } else {\n';
  html += '    expandedCompletedManagers.add(mem);\n';
  html += '  }\n';
  html += '  renderTodoDashboard();\n';
  html += '}\n';
  html += '\n';
  html += 'function renderTodoCardHtml(card, todayYmd) {\n';
  html += '  const isDone = (card.status === "완료");\n';
  html += '  const isOverdue = (!isDone && card.dueDate && card.dueDate < todayYmd);\n';
  html += '  let cHtml = "";\n';
  html += '  cHtml += \'  <div class="todo-item-card" draggable="true" ondragstart="onTodoDragStart(event, \\\'\' + card.id + \'\\\')" style="background:#ffffff;border:1px solid \' + (isOverdue ? "#fca5a5" : "#e2e8f0") + \';border-radius:8px;padding:9px 11px;margin-bottom:7px;box-shadow:0 1px 2px rgba(0,0,0,0.04);cursor:grab;transition:all 0.15s ease;">\';\n';
  html += '  cHtml += \'    <div style="display:flex;align-items:flex-start;justify-content:space-between;gap:6px;">\';\n';
  html += '  cHtml += \'      <label style="display:inline-flex;align-items:center;gap:6px;cursor:pointer;flex:1;min-width:0;margin:0;">\';\n';
  html += '  cHtml += \'        <input type="checkbox" \' + (isDone ? "checked" : "") + \' onclick="event.stopPropagation();toggleTodoComplete(\\\'\' + card.id + \'\\\', this.checked)" style="width:15px;height:15px;cursor:pointer;accent-color:#2563eb;flex-shrink:0;">\';\n';
  html += '  cHtml += \'        <span style="font-size:12.5px;font-weight:700;color:\' + (isDone ? "#94a3b8" : "#0f172a") + \';\' + (isDone ? "text-decoration:line-through;" : "") + \'word-break:break-all;">\' + escapeHtml(card.title) + \'</span>\';\n';
  html += '  cHtml += \'      </label>\';\n';
  html += '  cHtml += \'      <div style="display:flex;align-items:center;gap:4px;flex-shrink:0;">\';\n';
  html += '  cHtml += \'        <span onclick="event.stopPropagation();toggleTodoImportant(\\\'\' + card.id + \'\\\')" style="cursor:pointer;font-size:13px;color:\' + (card.isImportant ? "#eab308" : "#cbd5e1") + \';" title="중요 표시 토글">★</span>\';\n';
  html += '  cHtml += \'        <span onclick="event.stopPropagation();openEditTodoModal(\\\'\' + card.id + \'\\\')" style="cursor:pointer;font-size:11px;color:#94a3b8;" title="수정">✏️</span>\';\n';
  html += '  cHtml += \'        <span onclick="event.stopPropagation();confirmDeleteTodo(\\\'\' + card.id + \'\\\')" style="cursor:pointer;font-size:11px;color:#cbd5e1;" title="삭제">🗑️</span>\';\n';
  html += '  cHtml += \'      </div>\';\n';
  html += '  cHtml += \'    </div>\';\n';
  html += '  if (card.tag || card.siteName || card.dueDate) {\n';
  html += '    cHtml += \'    <div style="display:flex;align-items:center;gap:5px;flex-wrap:wrap;margin-top:6px;font-size:10.5px;">\';\n';
  html += '    if (card.tag) {\n';
  html += '      cHtml += \'      <span style="background:#e0f2fe;color:#0369a1;padding:2px 6px;border-radius:4px;font-weight:700;">\' + escapeHtml(card.tag) + \'</span>\';\n';
  html += '    }\n';
  html += '    if (card.siteName) {\n';
  html += '      cHtml += \'      <span style="background:#f1f5f9;color:#475569;padding:2px 6px;border-radius:4px;font-weight:600;">📍 \' + escapeHtml(card.siteName) + \'</span>\';\n';
  html += '    }\n';
  html += '    if (card.dueDate) {\n';
  html += '      cHtml += \'      <span style="color:\' + (isOverdue ? "#e11d48;font-weight:700;" : "#64748b;") + \'">📅 \' + escapeHtml(card.dueDate) + (isOverdue ? " (지남)" : "") + \'</span>\';\n';
  html += '    }\n';
  html += '    cHtml += \'    </div>\';\n';
  html += '  }\n';
  html += '  if (card.detail) {\n';
  html += '    cHtml += \'    <div style="margin-top:5px;font-size:11px;color:#64748b;overflow:hidden;text-overflow:ellipsis;white-space:nowrap;" title="\' + escapeHtml(card.detail) + \'">\' + escapeHtml(card.detail) + \'</div>\';\n';
  html += '  }\n';
  html += '  cHtml += \'  </div>\';\n';
  html += '  return cHtml;\n';
  html += '}\n';
  html += '\n';

  html += 'function loadTodoList(force) {\n';
  html += '  if (isTodoLoaded && !force && Array.isArray(todoDataList)) {\n';
  html += '    renderTodoDashboard();\n';
  html += '    return;\n';
  html += '  }\n';
  html += '  const contentArea = document.getElementById("contentArea");\n';
  html += '  const isCurrentTodoActive = (calViewMode === "todo" || (typeof isMobileTodoMode !== "undefined" && isMobileTodoMode));\n';
  html += '  if (isCurrentTodoActive && contentArea && (!todoDataList || todoDataList.length === 0)) {\n';
  html += '    contentArea.innerHTML = \'<div style="padding:60px 20px;text-align:center;color:#64748b;font-weight:700;"><span style="font-size:28px;">⏳</span><div style="margin-top:10px;font-size:14px;">To-Do 데이터를 불러오는 중...</div></div>\';\n';
  html += '  }\n';
  html += '  if (typeof google !== "undefined" && google.script && google.script.run) {\n';
  html += '    google.script.run\n';
  html += '      .withSuccessHandler(res => {\n';
  html += '        if (res && res.success) {\n';
  html += '          todoDataList = (res.list || []).map(it => (it ? Object.assign({}, it, { dueDate: formatTodoDateYmd(it.dueDate) }) : it));\n';
  html += '          if (res.members && res.members.length > 0) todoMembersList = res.members;\n';
  html += '          if (res.activeSites && res.activeSites.length > 0) todoActiveSitesList = res.activeSites;\n';
  html += '          isTodoLoaded = true;\n';
  html += '          if (calViewMode === "todo" || (typeof isMobileTodoMode !== "undefined" && isMobileTodoMode)) {\n';
  html += '            renderTodoDashboard();\n';
  html += '          }\n';
  html += '        } else {\n';
  html += '          if (isCurrentTodoActive) showToast("❌ To-Do 불러오기 실패: " + ((res && res.error) || "알 수 없는 오류"));\n';
  html += '        }\n';
  html += '      })\n';
  html += '      .withFailureHandler(err => {\n';
  html += '        if (isCurrentTodoActive) showToast("❌ To-Do 통신 오류: " + ((err && err.message) || err));\n';
  html += '      })\n';
  html += '      .getTodoListFromWeb(!!force);\n';
  html += '  } else {\n';
  html += '    const apiUrl = (typeof SCRIPT_URL !== "undefined" ? SCRIPT_URL : (window.location.href.split("?")[0]));\n';
  html += '    fetch(apiUrl + "?action=getTodoList" + (force ? "&force=true" : ""))\n';
  html += '      .then(r => r.json())\n';
  html += '      .then(res => {\n';
  html += '        if (res && res.success) {\n';
  html += '          todoDataList = (res.list || []).map(it => (it ? Object.assign({}, it, { dueDate: formatTodoDateYmd(it.dueDate) }) : it));\n';
  html += '          if (res.members && res.members.length > 0) todoMembersList = res.members;\n';
  html += '          if (res.activeSites && res.activeSites.length > 0) todoActiveSitesList = res.activeSites;\n';
  html += '          isTodoLoaded = true;\n';
  html += '          if (calViewMode === "todo" || (typeof isMobileTodoMode !== "undefined" && isMobileTodoMode)) {\n';
  html += '            renderTodoDashboard();\n';
  html += '          }\n';
  html += '        } else {\n';
  html += '          if (isCurrentTodoActive) showToast("❌ To-Do 로드 실패: " + (res && res.error));\n';
  html += '        }\n';
  html += '      })\n';
  html += '      .catch(err => { if (isCurrentTodoActive) showToast("❌ To-Do 통신 에러: " + err); });\n';
  html += '  }\n';
  html += '}\n';
  html += '\n';

  html += 'function setTodoMemberFilter(mem) {\n';
  html += '  currentTodoMemberFilter = mem || "all";\n';
  html += '  renderTodoDashboard();\n';
  html += '}\n';
  html += '\n';

  html += 'function renderTodoDashboard() {\n';
  html += '  const contentArea = document.getElementById("contentArea");\n';
  html += '  if (!contentArea) return;\n';
  html += '  let tHtml = "";\n';
  html += '  const isNarrowTodo = (typeof window !== "undefined" && typeof window.innerWidth === "number" && window.innerWidth < 768);\n';
  html += '  tHtml += \'<div class="todo-dashboard-container" style="padding:\' + (isNarrowTodo ? "8px 10px 80px 10px;" : "16px 20px;") + \'max-width:1440px;margin:0 auto;">\';\n';
  html += '\n';

  // 1. 상단 담당자 필터 칩 바
  html += '  tHtml += \'  <div style="display:flex;align-items:center;gap:8px;overflow-x:auto;padding-bottom:12px;margin-bottom:12px;border-bottom:1px solid #e2e8f0;">\';\n';
  html += '  tHtml += \'    <span style="font-size:12px;font-weight:800;color:#64748b;white-space:nowrap;margin-right:4px;">담당자</span>\';\n';
  html += '  const isAllAct = (currentTodoMemberFilter === "all");\n';
  html += '  tHtml += \'    <button type="button" onclick="setTodoMemberFilter(\\\'all\\\')" style="padding:5px 12px;border-radius:20px;border:1.5px solid \' + (isAllAct ? "#2563eb;background:#eff6ff;color:#1d4ed8;font-weight:800;" : "#cbd5e1;background:#ffffff;color:#475569;font-weight:600;") + \'font-size:12px;cursor:pointer;white-space:nowrap;">전체</button>\';\n';
  html += '  (todoMembersList || []).forEach(m => {\n';
  html += '    const mClean = String(m || "").trim();\n';
  html += '    if (!mClean) return;\n';
  html += '    const isAct = (currentTodoMemberFilter === mClean);\n';
  html += '    const firstLetter = mClean.charAt(0);\n';
  html += '    tHtml += \'    <button type="button" onclick="setTodoMemberFilter(\\\'\' + escapeHtml(mClean) + \'\\\')" style="padding:4px 10px;border-radius:20px;border:1.5px solid \' + (isAct ? "#2563eb;background:#eff6ff;color:#1d4ed8;font-weight:800;" : "#cbd5e1;background:#ffffff;color:#475569;font-weight:600;") + \'font-size:12px;cursor:pointer;display:inline-flex;align-items:center;gap:5px;white-space:nowrap;">\';\n';
  html += '    tHtml += \'      <span style="width:18px;height:18px;border-radius:50%;background:\' + (isAct ? "#2563eb;color:#ffffff;" : "#e2e8f0;color:#475569;") + \'display:inline-flex;align-items:center;justify-content:center;font-size:10px;font-weight:800;">\' + escapeHtml(firstLetter) + \'</span>\';\n';
  html += '    tHtml += \'      <span>\' + escapeHtml(mClean) + \'</span>\';\n';
  html += '    tHtml += \'    </button>\';\n';
  html += '  });\n';
  html += '  const isUnassignedAct = (currentTodoMemberFilter === "unassigned");\n';
  html += '  tHtml += \'    <button type="button" onclick="setTodoMemberFilter(\\\'unassigned\\\')" style="padding:5px 12px;border-radius:20px;border:1.5px solid \' + (isUnassignedAct ? "#2563eb;background:#eff6ff;color:#1d4ed8;font-weight:800;" : "#cbd5e1;background:#ffffff;color:#475569;font-weight:600;") + \'font-size:12px;cursor:pointer;white-space:nowrap;">담당 미지정</button>\';\n';
  html += '  tHtml += \'  </div>\';\n';
  html += '\n';

  // 2. 타이틀 & 액션 버튼
  html += '  tHtml += \'  <div style="display:flex;align-items:center;justify-content:space-between;gap:12px;margin-bottom:14px;flex-wrap:wrap;">\';\n';
  html += '  tHtml += \'    <h2 style="font-size:18px;font-weight:900;color:#0f172a;margin:0;display:flex;align-items:center;gap:8px;"><span>To-Do List</span></h2>\';\n';
  html += '  tHtml += \'    <div style="display:flex;align-items:center;gap:8px;">\';\n';
  html += '  tHtml += \'      <button type="button" onclick="openAddTodoModal()" style="padding:8px 16px;background:#2563eb;color:#ffffff;border:none;border-radius:8px;font-size:13px;font-weight:800;cursor:pointer;display:inline-flex;align-items:center;gap:5px;box-shadow:0 1px 3px rgba(37,99,235,0.3);"><span>+</span> 업무 추가</button>\';\n';
  html += '  tHtml += \'    </div>\';\n';
  html += '  tHtml += \'  </div>\';\n';
  html += '\n';

  // 3. 통계 요약 뱃지 계산
  html += '  const todayYmd = formatDateYYMMDD(new Date());\n';
  html += '  let uncompletedCount = 0;\n';
  html += '  let overdueCount = 0;\n';
  html += '  let importantCount = 0;\n';
  html += '  let completedCount = 0;\n';
  html += '  (todoDataList || []).forEach(it => {\n';
  html += '    const st = it.status || "미완료";\n';
  html += '    const isImp = (it.isImportant === true || st === "중요");\n';
  html += '    if (st === "완료") {\n';
  html += '      completedCount++;\n';
  html += '    } else {\n';
  html += '      if (isImp) {\n';
  html += '        importantCount++;\n';
  html += '      } else {\n';
  html += '        uncompletedCount++;\n';
  html += '      }\n';
  html += '      if (it.dueDate && it.dueDate < todayYmd) overdueCount++;\n';
  html += '    }\n';
  html += '  });\n';
  html += '\n';
  html += '  tHtml += \'  <div style="display:flex;align-items:center;gap:10px;margin-bottom:16px;flex-wrap:wrap;">\';\n';
  html += '  tHtml += \'    <div style="padding:6px 14px;background:#ffffff;border:1.5px solid #cbd5e1;border-radius:8px;font-size:12.5px;font-weight:800;color:#0f172a;">미완료 <span style="margin-left:4px;">\' + uncompletedCount + \'</span></div>\';\n';
  html += '  tHtml += \'    <div style="padding:6px 14px;background:\' + (overdueCount > 0 ? "#fff1f2" : "#ffffff") + \';border:1.5px solid \' + (overdueCount > 0 ? "#fca5a5" : "#cbd5e1") + \';border-radius:8px;font-size:12.5px;font-weight:800;color:\' + (overdueCount > 0 ? "#e11d48" : "#64748b") + \';">지남 <span style="margin-left:4px;">\' + overdueCount + \'</span></div>\';\n';
  html += '  tHtml += \'    <div style="padding:6px 14px;background:#fffbeb;border:1.5px solid #fde68a;border-radius:8px;font-size:12.5px;font-weight:800;color:#d97706;">중요 <span style="margin-left:4px;">\' + importantCount + \'</span></div>\';\n';
