  html += '  }';
  html += '  return "";';
  html += '}';
  html += '';
  html += 'function buildPartnerWorkGuideText(siteName, taskObj) {';
  html += '  const sName = siteName || (taskObj && taskObj.siteName) || curSiteName || selectedPcSiteName || "";';
  html += '  const sInfo = getSiteInfoFromMap(sName);';
  html += '  let taskName = "";';
  html += '  let partner = "";';
  html += '  let dateDisp = "";';
  html += '  let mgr = "";';
  html += '  const now = new Date();';
  html += '  const nowY = now.getFullYear();';
  html += '  const nowM = String(now.getMonth() + 1).padStart(2, "0");';
  html += '  const nowD = String(now.getDate()).padStart(2, "0");';
  html += '  const todayHyphen = nowY + "-" + nowM + "-" + nowD;';
  html += '  const todayDot = nowY + "." + nowM + "." + nowD;';
  html += '  const todayFormatted = todayDot + " (" + formatKoreanDOW(now) + ")";';
  html += '  if (taskObj) {';
  html += '    taskName = taskObj.taskName || "";';
  html += '    partner = taskObj.partner ? (" (" + taskObj.partner + ")") : "";';
  html += '    dateDisp = taskObj.dateDisplay || taskObj.startDateStr || todayFormatted;';
  html += '    try {';
  html += '      if (taskObj.startDateStr) {';
  html += '        const sClean = String(taskObj.startDateStr).replace(/\\./g, "-");';
  html += '        const sParts = sClean.split("-");';
  html += '        if (sParts.length === 3) {';
  html += '          const sObj = new Date(parseInt(sParts[0], 10), parseInt(sParts[1], 10) - 1, parseInt(sParts[2], 10));';
  html += '          const dow = formatKoreanDOW(sObj);';
  html += '          if (taskObj.endDateStr && taskObj.endDateStr !== taskObj.startDateStr) {';
  html += '            const eClean = String(taskObj.endDateStr).replace(/\\./g, "-");';
  html += '            const eParts = eClean.split("-");';
  html += '            let dowEnd = "";';
  html += '            if (eParts.length === 3) {';
  html += '              const eObj = new Date(parseInt(eParts[0], 10), parseInt(eParts[1], 10) - 1, parseInt(eParts[2], 10));';
  html += '              dowEnd = formatKoreanDOW(eObj);';
  html += '            }';
  html += '            dateDisp = String(taskObj.startDateStr).replace(/-/g, ".") + (dow ? " (" + dow + ")" : "") + " ~ " + String(taskObj.endDateStr).replace(/-/g, ".") + (dowEnd ? " (" + dowEnd + ")" : "");';
  html += '          } else {';
  html += '            dateDisp = String(taskObj.startDateStr).replace(/-/g, ".") + " (" + dow + ")";';
  html += '          }';
  html += '        }';
  html += '      }';
  html += '    } catch(eTaskDate) {}';
  html += '    mgr = (typeof formatManagerName === "function" ? formatManagerName(taskObj.manager) : "") || taskObj.manager || "현장 담당자";';
  html += '  } else {';
  html += '    let siteObj = null;';
  html += '    if (rawData && Array.isArray(rawData.sites)) {';
  html += '      siteObj = rawData.sites.find(s => s && s.siteName === sName);';
  html += '    }';
  html += '    let todayTasks = [];';
  html += '    if (siteObj && Array.isArray(siteObj.tasks)) {';
  html += '      todayTasks = siteObj.tasks.filter(t => {';
  html += '        if (!t) return false;';
  html += '        const st = String(t.status || "").trim();';
  html += '        if (st.indexOf("취소") !== -1) return false;';
  html += '        const sStr = String(t.startDateStr || "").replace(/\\./g, "-").trim();';
  html += '        const eStr = String(t.endDateStr || sStr).replace(/\\./g, "-").trim();';
  html += '        if (!sStr) return false;';
  html += '        return (sStr <= todayHyphen && todayHyphen <= eStr);';
  html += '      });';
  html += '    }';
  html += '    if (todayTasks.length > 0) {';
  html += '      dateDisp = todayFormatted;';
  html += '      const tNames = todayTasks.map(t => {';
  html += '        return t.taskName || "";';
  html += '      }).filter(Boolean);';
  html += '      taskName = tNames.join(", ");';
  html += '      const mgrSet = [];';
  html += '      todayTasks.forEach(t => {';
  html += '        if (t.manager) {';
  html += '          String(t.manager).split(/[,/]/).forEach(m => {';
  html += '            const tr = m.trim();';
  html += '            if (tr && !mgrSet.includes(tr)) mgrSet.push(tr);';
  html += '          });';
  html += '        }';
  html += '      });';
  html += '      if (mgrSet.length > 0) {';
  html += '        mgr = mgrSet.join(", ");';
  html += '      } else if (siteObj && (siteObj.primaryManager || siteObj.manager)) {';
  html += '        mgr = siteObj.primaryManager || siteObj.manager;';
  html += '      } else {';
