  html += '    } else {';
  html += '      let fallbackTask = null;';
  html += '      if (siteObj && Array.isArray(siteObj.tasks)) {';
  html += '        fallbackTask = siteObj.tasks.find(t => t && t.status && t.status.indexOf("진행") !== -1 && t.status.indexOf("취소") === -1);';
  html += '        if (!fallbackTask) {';
  html += '          const upcoming = siteObj.tasks.filter(t => {';
  html += '            if (!t) return false;';
  html += '            const sStr = String(t.startDateStr || "").replace(/\\./g, "-").trim();';
  html += '            return (sStr > todayHyphen && (!t.status || t.status.indexOf("취소") === -1));';
  html += '          });';
  html += '          if (upcoming.length > 0) {';
