  html += '    counterBadge.innerText = (idx + 1) + " / " + total + (tName ? " [" + tName + "]" : "");';
  html += '  }';
  html += '  const textEl = document.getElementById("partnerGuideModalText");';
  html += '  if (textEl) {';
