  html += '      nextSideBtn.disabled = (idx === total - 1);';
  html += '    }';
  html += '    if (footerNav) footerNav.style.display = "flex";';
  html += '    if (prevFooterBtn) prevFooterBtn.disabled = (idx === 0);';
  html += '    if (nextFooterBtn) nextFooterBtn.disabled = (idx === total - 1);';
