  html += '}';
  html += '';
  html += 'function copyAllPartnerGuidesFromModal() {';
  html += '  const textEl = document.getElementById("partnerGuideModalText");';
  html += '  if (textEl) {';
  html += '    partnerGuideTexts[partnerGuideCurrentIndex] = textEl.value;';
