  html += '  const separator = "\\n\\n" + "━━━━━━━━━━━━━━━━━━" + "\\n\\n";';
  html += '  const allCombined = validTexts.join(separator);';
  html += '  copyTextToClipboard(allCombined, "📲 체크된 모든 공정(" + validTexts.length + "개) 카카오톡 안내문이 복사되었습니다!");';
  html += '  const copyAllBtn = document.getElementById("btnDoPartnerGuideCopyAll");';
