  html += '}';
  html += '';
  html += 'function clearCheckedSiteTasks() {';
  html += '  if (typeof checkedSiteTasks !== "undefined" && checkedSiteTasks && checkedSiteTasks.size > 0) {';
  html += '    checkedSiteTasks.clear();';
  html += '  }';
