  html += '    if (rowEl && rowEl.style.display === "none") return;';
  html += '    cb.checked = checked;';
  html += '    if (rowEl) rowEl.classList.toggle("row-selected", checked);';
  html += '    const r = cb.getAttribute("data-row");';
