  html += '';
  html += 'function updateSelectAllCheckboxState() {';
  html += '  const allCb = document.getElementById("pcSiteTaskSelectAll");';
  html += '  if (!allCb) return;';
  html += '  const cbs = Array.from(document.querySelectorAll(".pc-site-task-cb")).filter(cb => {';
  html += '    const rowEl = cb.closest("tr");';
  html += '    return !rowEl || rowEl.style.display !== "none";';
