  html += '  if (titleEl) titleEl.innerText = "[" + sName + "] 파일 업로드";';
  html += '  const targetBox = document.getElementById("siteUploadTargetFolderInfo");';
  html += '  if (targetBox) {';
  html += '    if (driveUrl) {';
  html += '      targetBox.style.background = "#f0fdf4";';
  html += '      targetBox.style.borderColor = "#bbf7d0";';
  html += '      targetBox.innerHTML = \'<div style="display:flex;align-items:center;justify-content:space-between;gap:6px;">\' +';
  html += '        \'<span style="font-size:11.5px;font-weight:700;color:#166534;display:flex;align-items:center;gap:4px;"><span>📁</span> 연결 폴더: <b>드라이브 자료실</b></span>\' +';
  html += '        \'<a href="\' + escapeHtml(driveUrl) + \'" target="_blank" rel="noopener noreferrer" style="font-size:11px;font-weight:800;color:#15803d;text-decoration:underline;" onclick="event.stopPropagation()">폴더 열기 ↗</a>\' +';
  html += '        \'</div>\';';
  html += '    } else {';
  html += '      targetBox.style.background = "#fffbeb";';
  html += '      targetBox.style.borderColor = "#fde68a";';
  html += '      targetBox.innerHTML = \'<div style="display:flex;align-items:center;justify-content:space-between;gap:6px;">\' +';
  html += '        \'<span style="font-size:11.5px;font-weight:700;color:#92400e;">⚠️ 등록된 드라이브 폴더 링크가 없습니다.</span>\' +';
  html += '        \'<button type="button" onclick="closeSiteFileUploadModal();openSiteInfoEditModal(currentUploadSiteName)" style="border:none;background:#fef3c7;color:#b45309;padding:2px 7px;border-radius:4px;font-size:11px;font-weight:800;cursor:pointer;">링크 등록</button>\' +';
  html += '        \'</div>\';';
