  html += '  renderSelectedUploadFilesList();';
  html += '  const modal = document.getElementById("siteFileUploadModalOverlay");';
  html += '  if (modal) modal.classList.add("active");';
  html += '}';
  html += '';
  html += 'let isUploadingSiteFiles = false;';
  html += 'function closeSiteFileUploadModal(e) {';
  html += '  if (isUploadingSiteFiles) return;';
  html += '  if (e && e.target && e.target !== document.getElementById("siteFileUploadModalOverlay") && !e.target.classList.contains("sheet-close") && !e.target.classList.contains("btn-site-info-cancel")) return;';
  html += '  const modal = document.getElementById("siteFileUploadModalOverlay");';
  html += '  if (modal) modal.classList.remove("active");';
  html += '  selectedUploadFiles = [];';
  html += '}';
  html += '';
  html += 'function onSiteUploadFilesSelected(files) {';
  html += '  if (!files || !files.length) return;';
  html += '  for (let i = 0; i < files.length; i++) {';
  html += '    selectedUploadFiles.push(files[i]);';
  html += '  }';
  html += '  renderSelectedUploadFilesList();';
  html += '  const fileInp = document.getElementById("siteUploadFileInput");';
  html += '  if (fileInp) fileInp.value = "";';
  html += '  const camInp = document.getElementById("siteUploadCameraInput");';
  html += '  if (camInp) camInp.value = "";';
  html += '}';
  html += '';
  html += 'function removeSelectedUploadFile(index) {';
  html += '  selectedUploadFiles.splice(index, 1);';
  html += '  renderSelectedUploadFilesList();';
  html += '}';
  html += '';
  html += 'function renderSelectedUploadFilesList() {';
  html += '  const container = document.getElementById("siteUploadSelectedFilesList");';
  html += '  const countEl = document.getElementById("siteUploadSelectedCount");';
  html += '  const btnUpload = document.getElementById("btnExecuteSiteUpload");';
  html += '  if (!container) return;';
  html += '  if (countEl) countEl.innerText = selectedUploadFiles.length + "개 선택됨";';
  html += '  if (selectedUploadFiles.length === 0) {';
  html += '    container.innerHTML = \'<div style="text-align:center;padding:14px;color:#94a3b8;font-size:11.5px;font-weight:600;background:#f8fafc;border-radius:7px;border:1px solid #f1f5f9;">선택된 파일이 없습니다.</div>\';';
  html += '    if (btnUpload) {';
  html += '      btnUpload.disabled = true;';
  html += '      btnUpload.style.opacity = "0.5";';
  html += '      btnUpload.style.cursor = "not-allowed";';
  html += '    }';
  html += '    return;';
  html += '  }';
  html += '  if (btnUpload) {';
  html += '    btnUpload.disabled = false;';
  html += '    btnUpload.style.opacity = "1";';
  html += '    btnUpload.style.cursor = "pointer";';
  html += '  }';
  html += '  let lHtml = \'<div style="display:flex;flex-direction:column;gap:5px;max-height:160px;overflow-y:auto;">\';';
  html += '  selectedUploadFiles.forEach(function(file, idx) {';
  html += '    const szKb = (file.size / 1024).toFixed(1);';
  html += '    const szStr = file.size > 1024 * 1024 ? (file.size / (1024 * 1024)).toFixed(1) + " MB" : szKb + " KB";';
  html += '    const isImg = file.type && file.type.startsWith("image/");';
  html += '    const icon = isImg ? "🖼️" : "📄";';
  html += '    lHtml += \'<div style="display:flex;align-items:center;justify-content:space-between;padding:6px 10px;background:#f8fafc;border:1px solid #e2e8f0;border-radius:6px;font-size:11.5px;">\';';
  html += '    lHtml += \'  <div style="display:flex;align-items:center;gap:6px;min-width:0;flex:1;">\';';
  html += '    lHtml += \'    <span>\' + icon + \'</span>\';';
  html += '    lHtml += \'    <span style="font-weight:700;color:#1e293b;overflow:hidden;text-overflow:ellipsis;white-space:nowrap;" title="\' + escapeHtml(file.name) + \'">\' + escapeHtml(file.name) + \'</span>\';';
  html += '    lHtml += \'    <span style="font-size:10.5px;color:#64748b;flex-shrink:0;">(\' + szStr + \')</span>\';';
  html += '    lHtml += \'  </div>\';';
  html += '    lHtml += \'  <button type="button" onclick="removeSelectedUploadFile(\' + idx + \')" style="border:none;background:none;color:#94a3b8;font-size:13px;font-weight:bold;cursor:pointer;padding:0 4px;margin-left:6px;" title="제거">✕</button>\';';
  html += '    lHtml += \'</div>\';';
  html += '  });';
  html += '  lHtml += \'</div>\';';
  html += '  container.innerHTML = lHtml;';
  html += '}';
  html += '';
  html += 'function executeSiteFileUpload() {';
  html += '  if (isUploadingSiteFiles) return;';
  html += '  if (!selectedUploadFiles || !selectedUploadFiles.length) {';
  html += '    showToast("⚠️ 업로드할 파일을 먼저 선택해주세요.");';
  html += '    return;';
  html += '  }';
  html += '  const info = getSiteInfoFromMap(currentUploadSiteName);';
  html += '  const driveUrl = String(info.driveUrl || info.driveLink || "").trim();';
  html += '  if (!driveUrl) {';
  html += '    showToast("⚠️ [" + currentUploadSiteName + "] 등록된 드라이브 폴더 링크가 없습니다. 먼저 링크를 등록해주세요.", 3500);';
  html += '    closeSiteFileUploadModal();';
  html += '    openSiteInfoEditModal(currentUploadSiteName);';
  html += '    return;';
  html += '  }';
  html += '  const btn = document.getElementById("btnExecuteSiteUpload");';
  html += '  const btnLabel = document.getElementById("btnExecuteSiteUploadLabel");';
  html += '  const cancelBtn = document.querySelector("#siteFileUploadModalOverlay .btn-site-info-cancel");';
  html += '  const closeBtn = document.querySelector("#siteFileUploadModalOverlay .sheet-close");';
  html += '  isUploadingSiteFiles = true;';
  html += '  if (btn) {';
  html += '    btn.disabled = true;';
  html += '    btn.style.opacity = "0.7";';
  html += '    btn.style.cursor = "wait";';
  html += '  }';
  html += '  if (btnLabel) btnLabel.innerText = "파일 준비 중...";';
  html += '  if (cancelBtn) cancelBtn.disabled = true;';
  html += '  if (closeBtn) closeBtn.disabled = true;';
  html += '  showToast("⏳ 업로드할 파일을 준비하고 있습니다...", 3000);';
  html += '  const readers = selectedUploadFiles.map(function(file) {';
  html += '    return new Promise(function(resolve, reject) {';
  html += '      const reader = new FileReader();';
  html += '      reader.onload = function(e) {';
  html += '        resolve({';
  html += '          name: file.name,';
  html += '          mimeType: file.type || "application/octet-stream",';
  html += '          data: e.target.result';
  html += '        });';
  html += '      };';
  html += '      reader.onerror = function(err) {';
  html += '        reject(err);';
  html += '      };';
  html += '      reader.readAsDataURL(file);';
  html += '    });';
  html += '  });';
  html += '  Promise.all(readers)';
  html += '    .then(function(payloads) {';
  html += '      if (btnLabel) btnLabel.innerText = "드라이브로 업로드 중 (" + payloads.length + "개)...";';
  html += '      showToast("☁️ [" + currentUploadSiteName + "] 구글 드라이브로 " + payloads.length + "개 파일 전송 중...", 6000);';
  html += '      function resetUploadButtonState() {';
  html += '        isUploadingSiteFiles = false;';
  html += '        if (btn) {';
  html += '          btn.disabled = false;';
  html += '          btn.style.opacity = "1";';
  html += '          btn.style.cursor = "pointer";';
  html += '        }';
  html += '        if (btnLabel) btnLabel.innerText = "드라이브로 업로드";';
  html += '        if (cancelBtn) cancelBtn.disabled = false;';
  html += '        if (closeBtn) closeBtn.disabled = false;';
  html += '      }';
  html += '      if (typeof google !== "undefined" && google.script && google.script.run) {';
  html += '        google.script.run';
  html += '          .withSuccessHandler(function(res) {';
  html += '            resetUploadButtonState();';
  html += '            if (res && res.success) {';
  html += '              selectedUploadFiles = [];';
  html += '              renderSelectedUploadFilesList();';
  html += '              const modal = document.getElementById("siteFileUploadModalOverlay");';
  html += '              if (modal) modal.classList.remove("active");';
  html += '              showToast("✅ [" + currentUploadSiteName + "] " + (res.uploadedCount || payloads.length) + "개 파일이 드라이브에 안전하게 업로드되었습니다!", 4000);';
  html += '            } else {';
  html += '              showToast("⚠️ 업로드 실패: " + ((res && res.error) || "알 수 없는 오류"), (res && res.isAuthRequired) ? 7000 : 4500);';
  html += '            }';
  html += '          })';
  html += '          .withFailureHandler(function(err) {';
  html += '            resetUploadButtonState();';
  html += '            console.error("uploadSiteFilesToDriveFromWeb error:", err);';
  html += '            var errStr = (err && (err.message || err.toString())) || "";';
  html += '            if (errStr.indexOf("DriveApp") !== -1 || errStr.indexOf("권한이 없습니다") !== -1 || errStr.indexOf("auth/drive") !== -1) {';
  html += '              showToast("⚠️ 구글 드라이브 권한 필요: 시트 상단 [🚀 현장 관리 > ☁️ 구글 드라이브 업로드 권한 1회 승인]을 눌러주세요.", 7000);';
  html += '            } else {';
  html += '              showToast("❌ 드라이브 업로드 통신 에러: " + errStr, 5000);';
  html += '            }';
  html += '          })';
  html += '          .uploadSiteFilesToDriveFromWeb(currentUploadSiteName, payloads, driveUrl);';
  html += '      } else {';
  html += '        setTimeout(function() {';
  html += '          resetUploadButtonState();';
  html += '          selectedUploadFiles = [];';
  html += '          renderSelectedUploadFilesList();';
  html += '          const modal = document.getElementById("siteFileUploadModalOverlay");';
  html += '          if (modal) modal.classList.remove("active");';
  html += '          showToast("✅ [가상 테스트] " + payloads.length + "개 파일 업로드 완료", 3000);';
  html += '        }, 1200);';
  html += '      }';
  html += '    })';
  html += '    .catch(function(readErr) {';
  html += '      isUploadingSiteFiles = false;';
  html += '      if (btn) {';
  html += '        btn.disabled = false;';
  html += '        btn.style.opacity = "1";';
  html += '        btn.style.cursor = "pointer";';
  html += '      }';
  html += '      if (btnLabel) btnLabel.innerText = "드라이브로 업로드";';
  html += '      if (cancelBtn) cancelBtn.disabled = false;';
  html += '      if (closeBtn) closeBtn.disabled = false;';
  html += '      console.error("FileReader error:", readErr);';
  html += '      showToast("⚠️ 파일 읽기 오류: 파일을 읽을 수 없습니다.", 3500);';
  html += '    });';
  html += '}';
  html += '';
  html += '';
  html += 'function saveSiteInfoEditModal() {';
  html += '  const sName = document.getElementById("editSiteInfoSiteName").value.trim();';
  html += '  if (!sName) return;';
  html += '  const addr = document.getElementById("editSiteInfoAddress").value.trim();';
  html += '  const pwd = document.getElementById("editSiteInfoDoorPassword").value.trim();';
  html += '  const phone = document.getElementById("editSiteInfoOfficePhone").value.trim();';
  html += '  const memo = document.getElementById("editSiteInfoMemo").value.trim();';
  html += '  const driveInp = document.getElementById("editSiteInfoDriveUrl");';
  html += '  const driveUrl = driveInp ? driveInp.value.trim() : "";';
  html += '  if (!rawData) rawData = {};';
  html += '  if (!rawData.siteInfoMap) rawData.siteInfoMap = {};';
  html += '  const curInfo = getSiteInfoFromMap(sName);';
  html += '  if (!rawData.siteInfoMap[sName]) {';
  html += '    rawData.siteInfoMap[sName] = Object.assign({ siteName: sName, consentDone: false, elevatorCoverDone: false, officeNoticeDone: false }, curInfo);';
  html += '  }';
  html += '  const info = rawData.siteInfoMap[sName];';
  html += '  info.address = addr;';
  html += '  info.doorPassword = pwd;';
  html += '  info.officePhone = phone;';
  html += '  info.memo = memo;';
  html += '  info.driveUrl = driveUrl;';
  html += '  const sNoSp = sName.replace(/\\s+/g, "");';
  html += '  rawData.siteInfoMap[sNoSp] = info;';
  html += '  try { if (typeof localStorage !== "undefined" && localStorage && localStorage.setItem) localStorage.setItem("ws_dashboard_cache_v2", JSON.stringify(rawData)); } catch(eLs) {}';
  html += '  const saveBtn = document.getElementById("btnSaveSiteInfo");';
  html += '  if (saveBtn) { saveBtn.disabled = true; saveBtn.innerText = "저장 중..."; }';
  html += '  showToast("💾 [" + sName + "] 현장 정보 저장 중...");';
  html += '  closeSiteInfoEditModal();';
  html += '  if (isCalendarMode && calViewMode === "list") renderList(); else if (isCalendarMode) renderCurrentCalendarView(); else renderList();';
  html += '  if (typeof google !== "undefined" && google.script && google.script.run) {';
  html += '    google.script.run';
  html += '      .withSuccessHandler(function(res) {';
  html += '        if (saveBtn) { saveBtn.disabled = false; saveBtn.innerText = "💾 저장하기"; }';
  html += '        showToast("✅ [" + sName + "] 현장 정보가 시트에 저장되었습니다!");';
  html += '      })';
  html += '      .withFailureHandler(function(err) {';
  html += '        if (saveBtn) { saveBtn.disabled = false; saveBtn.innerText = "💾 저장하기"; }';
  html += '        console.error("saveFullSiteInfo error:", err);';
  html += '        showToast("⚠️ 현장 정보 저장 통신 실패");';
  html += '      })';
  html += '      .saveFullSiteInfoFromWeb(sName, { address: addr, doorPassword: pwd, officePhone: phone, memo: memo, driveUrl: driveUrl });';
  html += '  }';
  html += '}';

  html += 'function getTaskStatusIcon(status) {';
  html += '  const st = String(status || "").replace(/\\s+/g, "");';
  html += '  if (st.indexOf("완료") !== -1 || st.indexOf("✅") !== -1) return "✅";';
  html += '  if (st.indexOf("진행") !== -1 || st.indexOf("▶") !== -1) return "▶️";';
  html += '  if (st.indexOf("AS") !== -1 || st.indexOf("A/S") !== -1 || st.indexOf("as") !== -1 || st.indexOf("🛠") !== -1) return "🛠️";';
  html += '  return "";';
  html += '}';

  html += 'let toastTimer = null;';
  html += 'function showToast(msg, duration) {';
  html += '  const t = document.getElementById("toast");';
  html += '  if (!t) return;';
  html += '  t.innerText = msg;';
  html += '  t.classList.add("show");';
  html += '  if (toastTimer) clearTimeout(toastTimer);';
  html += '  toastTimer = setTimeout(() => t.classList.remove("show"), duration || 2500);';
  html += '}';

  html += 'function onSiteCheckboxClick(e, cb) {';
  html += '  e.stopPropagation();';
  html += '  const siteName = decodeURIComponent(cb.dataset.sitename || "");';
  html += '  if (cb.checked) {';
  html += '    checkedSites.add(siteName);';
  html += '  } else {';
  html += '    checkedSites.delete(siteName);';
  html += '  }';
  html += '  updateCheckedStatusUI();';
  html += '  if (currentFilter === "checked") {';
  html += '    renderList();';
  html += '  }';
  html += '  if (isCalendarMode) {';
  html += '    renderCurrentCalendarView();';
  html += '  }';
  html += '}';

  html += 'function updateCheckedStatusUI() {';
  html += '  const count = checkedSites.has("__NONE__") ? 0 : checkedSites.size;';
  html += '  const tab = document.getElementById("checkedTab");';
  html += '  const tabCount = document.getElementById("checkedTabCount");';
  html += '  const bar = document.getElementById("checkedActionBar");';
  html += '  const countMsg = document.getElementById("checkedCountMsg");';
  html += '  if (tabCount) tabCount.innerText = count;';
  html += '  if (tab) tab.style.display = (count > 0) ? "block" : "none";';
  html += '  if (bar) bar.style.display = (count > 0) ? "flex" : "none";';
  html += '  if (countMsg) countMsg.innerText = "☑️ " + count + "개 현장 선택됨";';
  html += '  if (typeof renderPcSidebarSites === "function") renderPcSidebarSites();';
  html += '  if (typeof updateFilterVisualStates === "function") updateFilterVisualStates();';
  html += '}';

  html += 'function clearAllChecked() {';
  html += '  checkedSites.clear();';
  html += '  if (typeof clearCheckedSiteTasks === "function") clearCheckedSiteTasks();';
  html += '  document.querySelectorAll(".site-check").forEach(cb => cb.checked = false);';
  html += '  updateCheckedStatusUI();';
  html += '  if (currentFilter === "checked") {';
  html += '    setFilter("all");';
  html += '  } else {';
  html += '    renderList();';
  html += '  }';
  html += '  if (isCalendarMode) {';
  html += '    renderCurrentCalendarView();';
  html += '  }';
  html += '}';

  html += 'function onLogoClick() {';
