  html += '  });';
  html += '  opts += \'<option value="__NONE__"\' + (selectedMember === "__NONE__" || selectedMember === "담당자 없음" ? " selected" : "") + \'>🚫 담당자 없음</option>\';';
  html += '  sel.innerHTML = opts;';
  html += '  if (typeof updateFilterVisualStates === "function") updateFilterVisualStates();';
