  html += '';
  html += 'function updatePcSidebarKPIs() {';
  html += '  if (!rawData || !rawData.kpi) return;';
  html += '  const todayEl = document.getElementById("pcKpiToday");';
  html += '  const delayEl = document.getElementById("pcKpiDelay");';
  html += '  if (todayEl) todayEl.innerText = (rawData.kpi.todayCount || 0) + "건";';
  html += '  if (delayEl) delayEl.innerText = (rawData.kpi.delayedCount || 0) + "건";';
  html += '  document.querySelectorAll(".pc-kpi-box").forEach(box => {';
  html += '    box.classList.toggle("active", box.dataset.filter === currentFilter);';
  html += '  });';
  html += '}';

  html += 'let isMobileTodoMode = false;';
  html += 'function updateMobileHeaderVisibility(isTodo) {';
  html += '  const selectors = [".kpi-grid", ".search-box", ".filter-tabs", "#memberFilterBar", "#mobileScopeTabsWrapper", "#checkedActionBar"];';
  html += '  selectors.forEach(sel => {';
  html += '    const el = document.querySelector(sel);';
  html += '    if (el) el.style.display = isTodo ? "none" : "";';
  html += '  });';
  html += '  const headerEl = document.querySelector(".header");';
  html += '  const titleRow = document.querySelector(".title-row");';
  html += '  if (headerEl) { headerEl.style.padding = isTodo ? "10px 14px" : ""; }';
  html += '  if (titleRow) { titleRow.style.marginBottom = isTodo ? "0px" : ""; }';
  html += '}';
  html += '';
  html += 'function toggleMobileTodoView() {';
  html += '  isMobileTodoMode = !isMobileTodoMode;';
  html += '  const todoBtn = document.getElementById("mobileTodoBtn");';
  html += '  const addTaskBtn = document.getElementById("btnOpenAddTask");';
  html += '  const calBtn = document.getElementById("calendarToggleBtn");';
  html += '  const pageTitle = document.getElementById("pageTitle");';
  html += '  const contentArea = document.getElementById("contentArea");';
  html += '  const calArea = document.getElementById("calendarArea");';
  html += '  if (isMobileTodoMode) {';
  html += '    calViewMode = "todo";';
  html += '    if (isCalendarMode) {';
  html += '      isCalendarMode = false;';
  html += '      if (calArea) { if (calArea.classList) calArea.classList.add("hidden"); calArea.style.display = "none"; }';
  html += '      if (calBtn) calBtn.innerText = "📅 캘린더 보기";';
  html += '    }';
  html += '    if (contentArea) { if (contentArea.classList) contentArea.classList.remove("hidden"); contentArea.style.display = ""; }';
  html += '    updateMobileHeaderVisibility(true);';
  html += '    if (todoBtn) {';
  html += '      todoBtn.innerHTML = "<span>📋</span> 현장 목록";';
  html += '      todoBtn.style.background = "#eff6ff";';
  html += '      todoBtn.style.color = "#1d4ed8";';
  html += '      todoBtn.style.borderColor = "#93c5fd";';
  html += '    }';
  html += '    if (addTaskBtn) {';
  html += '      addTaskBtn.innerHTML = "➕ 할 일 추가";';
  html += '      addTaskBtn.onclick = function() { openAddTodoModal(); };';
  html += '    }';
  html += '    if (pageTitle) pageTitle.innerText = "✅ To-Do List";';
  html += '    loadTodoList(false);';
  html += '  } else {';
  html += '    calViewMode = "month";';
  html += '    updateMobileHeaderVisibility(false);';
  html += '    if (todoBtn) {';
  html += '      todoBtn.innerHTML = "<span>✅</span> To-do";';
  html += '      todoBtn.style.background = "#f0fdf4";';
  html += '      todoBtn.style.color = "#166534";';
  html += '      todoBtn.style.borderColor = "#86efac";';
  html += '    }';
  html += '    if (addTaskBtn) {';
  html += '      addTaskBtn.innerHTML = "➕ 일정 추가";';
  html += '      addTaskBtn.onclick = function() { openNewTaskModal(); };';
  html += '    }';
  html += '    if (pageTitle) pageTitle.innerText = isMobileMode ? "📱 우성아이디 현장 대시보드" : "🏗️ 우성아이디 현장 대시보드";';
  html += '    if (contentArea) { if (contentArea.classList) contentArea.classList.remove("hidden"); contentArea.style.display = ""; }';
  html += '    renderList();';
  html += '  }';
  html += '}';
  html += '';
  html += 'function toggleCalendarView() {';
  html += '  if (typeof isMobileTodoMode !== "undefined" && isMobileTodoMode) {';
  html += '    isMobileTodoMode = false;';
  html += '    calViewMode = "month";';
  html += '    if (typeof updateMobileHeaderVisibility === "function") updateMobileHeaderVisibility(false);';
  html += '    const tBtn = document.getElementById("mobileTodoBtn");';
  html += '    if (tBtn) {';
  html += '      tBtn.innerHTML = "<span>✅</span> To-do";';
  html += '      tBtn.style.background = "#f0fdf4";';
  html += '      tBtn.style.color = "#166534";';
  html += '      tBtn.style.borderColor = "#86efac";';
  html += '    }';
  html += '    const addBtn = document.getElementById("btnOpenAddTask");';
  html += '    if (addBtn) {';
  html += '      addBtn.innerHTML = "➕ 일정 추가";';
  html += '      addBtn.onclick = function() { openNewTaskModal(); };';
  html += '    }';
  html += '  }';
  html += '  isCalendarMode = !isCalendarMode;';
  html += '  const btn = document.getElementById("calendarToggleBtn");';
  html += '  const contentArea = document.getElementById("contentArea");';
  html += '  const calArea = document.getElementById("calendarArea");';
  html += '  const pageTitle = document.getElementById("pageTitle");';
  html += '  if (isCalendarMode) {';
  html += '    if (btn) {';
  html += '      btn.innerText = "📋 목록 보기";';
  html += '    }';
  html += '    if (pageTitle) {';
  html += '      pageTitle.innerText = "📅 우성아이디 현장 캘린더";';
  html += '    }';
  html += '    if (contentArea) contentArea.style.display = "none";';
  html += '    if (calArea) calArea.style.display = "block";';
  html += '    renderCurrentCalendarView();';
  html += '  } else {';
  html += '    if (btn) {';
  html += '      btn.innerText = "📅 캘린더 보기";';
  html += '    }';
  html += '    if (pageTitle) {';
  html += '      pageTitle.innerText = isMobileMode ? "📱 우성아이디 현장 대시보드" : "🏗️ 우성아이디 현장 대시보드";';
  html += '    }';
  html += '    if (contentArea) contentArea.style.display = "";';
  html += '    if (calArea) calArea.style.display = "none";';
  html += '    renderList();';
  html += '  }';
  html += '}';

  html += 'function setCalendarMode(mode) {';
  html += '  calViewMode = mode;';
  html += '  const btnM = document.getElementById("btnModeMonth");';
  html += '  const btnW = document.getElementById("btnModeWeek");';
  html += '  const wkBar = document.getElementById("calWeekdaysBar");';
  html += '  const grid = document.getElementById("calGrid");';
  html += '  const wkList = document.getElementById("calWeekList");';
  html += '  if (btnM) btnM.classList.toggle("active", mode === "month");';
  html += '  if (btnW) btnW.classList.toggle("active", mode === "week");';
  html += '  if (mode === "week") {';
  html += '    if (wkBar) { wkBar.classList.add("hidden"); wkBar.style.setProperty("display", "none", "important"); }';
  html += '    if (grid) { grid.classList.add("hidden"); grid.style.setProperty("display", "none", "important"); }';
  html += '    if (wkList) {';
  html += '      wkList.classList.remove("hidden");';
  html += '      wkList.style.removeProperty("display");';
  html += '      const isPc = (window.innerWidth >= 768);';
  html += '      wkList.style.setProperty("display", isPc ? "grid" : "flex", "important");';
  html += '    }';
  html += '    renderWeeklyCalendar();';
  html += '  } else {';
  html += '    if (wkList) {';
  html += '      wkList.classList.add("hidden");';
  html += '      wkList.style.setProperty("display", "none", "important");';
  html += '      wkList.className = "cal-week-list hidden";';
  html += '    }';
  html += '    if (wkBar) {';
  html += '      wkBar.classList.remove("hidden");';
  html += '      wkBar.style.removeProperty("display");';
  html += '      wkBar.style.setProperty("display", "grid", "important");';
  html += '    }';
  html += '    if (grid) {';
  html += '      grid.classList.remove("hidden");';
  html += '      grid.style.removeProperty("display");';
  html += '      grid.style.setProperty("display", "grid", "important");';
  html += '    }';
  html += '    renderCalendar();';
  html += '  }';
  html += '}';
  html += '';
  html += 'function navPrevPeriod() {';
  html += '  if (calViewMode === "week") prevWeek(); else prevMonth();';
  html += '}';
  html += '';
  html += 'function navNextPeriod() {';
  html += '  if (calViewMode === "week") nextWeek(); else nextMonth();';
  html += '}';
  html += '';
  html += 'function navTodayPeriod() {';
  html += '  if (calViewMode === "week") goToThisWeek(); else goToTodayMonth();';
  html += '}';
  html += '';
  html += 'function prevMonth() {';
  html += '  if (typeof clearCheckedSiteTasks === "function") clearCheckedSiteTasks();';
  html += '  calMonth--;';
  html += '  if (calMonth < 1) { calMonth = 12; calYear--; }';
  html += '  renderCalendar("prev");';
  html += '}';
  html += '';
  html += 'function nextMonth() {';
  html += '  if (typeof clearCheckedSiteTasks === "function") clearCheckedSiteTasks();';
  html += '  calMonth++;';
  html += '  if (calMonth > 12) { calMonth = 1; calYear++; }';
  html += '  renderCalendar("next");';
  html += '}';
  html += '';
  html += 'function goToTodayMonth() {';
  html += '  if (typeof clearCheckedSiteTasks === "function") clearCheckedSiteTasks();';
  html += '  const now = new Date();';
  html += '  calYear = now.getFullYear();';
  html += '  calMonth = now.getMonth() + 1;';
  html += '  renderCalendar();';
  html += '}';
  html += '';
  html += 'function prevWeek() {';
  html += '  if (typeof clearCheckedSiteTasks === "function") clearCheckedSiteTasks();';
  html += '  calWeekStartDate.setDate(calWeekStartDate.getDate() - 7);';
  html += '  renderWeeklyCalendar("prev");';
  html += '}';
  html += '';
  html += 'function nextWeek() {';
  html += '  if (typeof clearCheckedSiteTasks === "function") clearCheckedSiteTasks();';
  html += '  calWeekStartDate.setDate(calWeekStartDate.getDate() + 7);';
  html += '  renderWeeklyCalendar("next");';
  html += '}';
  html += '';
  html += 'function goToThisWeek() {';
  html += '  if (typeof clearCheckedSiteTasks === "function") clearCheckedSiteTasks();';
  html += '  calWeekStartDate = getSundayOfCurrentWeek(new Date());';
  html += '  renderWeeklyCalendar();';
  html += '}';
  html += '';
  html += 'function renderCurrentCalendarView(direction) {';
  html += '  if (calViewMode === "week") renderWeeklyCalendar(direction); else renderCalendar(direction);';
  html += '}';
  html += '';
  html += 'function loadWeatherData() {';
  html += '  if (Object.keys(activeWeatherData).length > 0) return;';
  html += '  const url = "https://api.open-meteo.com/v1/forecast?latitude=37.5665&longitude=126.9780&daily=weathercode,temperature_2m_max,temperature_2m_min,precipitation_probability_max&timezone=Asia%2FTokyo&forecast_days=8";';
  html += '  fetch(url).then(r => r.json()).then(data => {';
  html += '    if (data && data.daily && data.daily.time) {';
  html += '      data.daily.time.forEach((dateStr, idx) => {';
  html += '        const code = data.daily.weathercode ? data.daily.weathercode[idx] : 0;';
  html += '        const maxT = data.daily.temperature_2m_max ? Math.round(data.daily.temperature_2m_max[idx]) : null;';
  html += '        const minT = data.daily.temperature_2m_min ? Math.round(data.daily.temperature_2m_min[idx]) : null;';
  html += '        const pop = data.daily.precipitation_probability_max ? data.daily.precipitation_probability_max[idx] : 0;';
  html += '        let icon = "☀️", desc = "맑음";';
  html += '        if (code >= 1 && code <= 2) { icon = "⛅"; desc = "구름조금"; }';
  html += '        else if (code === 3) { icon = "☁️"; desc = "흐림"; }';
  html += '        else if (code === 45 || code === 48) { icon = "🌫️"; desc = "안개"; }';
  html += '        else if ((code >= 51 && code <= 67) || (code >= 80 && code <= 82)) { icon = "🌧️"; desc = "비"; }';
  html += '        else if ((code >= 71 && code <= 77) || (code >= 85 && code <= 86)) { icon = "❄️"; desc = "눈"; }';
  html += '        else if (code >= 95) { icon = "⛈️"; desc = "뇌우"; }';
  html += '        const isRain = (icon === "🌧️" || icon === "⛈️");';
  html += '        const isSnow = (icon === "❄️");';
  html += '        let badgeText = icon;';
  html += '        if (pop >= 30) badgeText += " " + pop + "%";';
  html += '        else if (maxT !== null) badgeText += " " + maxT + "°";';
  html += '        activeWeatherData[dateStr] = {';
  html += '          icon: icon, desc: desc, maxT: maxT, minT: minT, pop: pop, isRain: isRain, isSnow: isSnow,';
  html += '          badgeText: badgeText,';
  html += '          fullText: icon + " " + desc + (maxT !== null ? " " + maxT + "°/" + minT + "°" : "") + (pop > 0 ? " (강수 " + pop + "%)" : "")';
  html += '        };';
  html += '      });';
  html += '    }';
  html += '    if (isCalendarMode) renderCurrentCalendarView();';
  html += '  }).catch(e => console.warn("날씨 비동기 로드 생략", e));';
  html += '}';
  html += '';
  html += 'function captureCalendarScreen() {';
  html += '  const topBtn = document.querySelector(".pc-btn-action-top");';
  html += '  const calBtn = document.getElementById("btnCaptureCal");';
  html += '  const btn = topBtn || calBtn;';
  html += '  const origText = btn ? btn.innerHTML : "📸 캡쳐";';
  html += '  if (btn) { btn.disabled = true; btn.innerHTML = "📸 캡쳐 중..."; }';
  html += '  function doCapture() {';
  html += '    let target = null;';
  html += '    let captureType = "calendar";';
  html += '    let filename = "";';
  html += '    const contentArea = document.getElementById("contentArea");';
  html += '    const isSiteDetailActive = contentArea && !contentArea.classList.contains("hidden") && contentArea.style.display !== "none";';
  html += '    if (isSiteDetailActive) {';
  html += '      target = document.querySelector(".pc-site-detail-pane");';
  html += '      captureType = "site";';
  html += '      const siteTitleEl = document.querySelector(".pc-detail-site-title");';
  html += '      const sName = siteTitleEl ? siteTitleEl.innerText.trim() : (selectedPcSiteName || "현장상세");';
  html += '      const now = new Date();';
  html += '      const dateTag = now.getFullYear() + "" + ((now.getMonth()+1)<10?"0"+(now.getMonth()+1):(now.getMonth()+1)) + "" + (now.getDate()<10?"0"+now.getDate():now.getDate());';
  html += '      filename = sName.replace(/[/\\?%*:|"<>]/g, "_") + "_공정관리_" + dateTag + ".png";';
  html += '    } else {';
  html += '      target = document.querySelector(".calendar-view") || document.getElementById("calendarArea");';
  html += '      captureType = "calendar";';
  html += '      filename = "현장캘린더_" + calYear + "년" + calMonth + "월.png";';
  html += '    }';
  html += '    if (!target) {';
  html += '      alert("캡쳐할 영역을 찾을 수 없습니다.");';
  html += '      if (btn) { btn.disabled = false; btn.innerHTML = origText; }';
  html += '      return;';
  html += '    }';
  html += '    const origOverflow = target.style.overflow;';
  html += '    const origHeight = target.style.height;';
  html += '    const origMaxHeight = target.style.maxHeight;';
  html += '    const origScrollTop = target.scrollTop;';
  html += '    target.scrollTop = 0;';
  html += '    let captureFullHeight = target.scrollHeight || target.offsetHeight;';
  html += '    let captureFullWidth = target.scrollWidth || target.offsetWidth;';
  html += '    let gridH = 0;';
  html += '    let rowHeights = [];';
  html += '    let calRowCount = 0;';
  html += '    if (captureType === "site") {';
  html += '      const tableCard = target.querySelector(".pc-tasks-table-card");';
  html += '      if (tableCard) {';
  html += '        const tableCardFullHeight = tableCard.scrollHeight;';
  html += '        const heroEl = target.querySelector(".pc-detail-hero");';
  html += '        const alertEl = target.querySelector(".pc-site-alert-banner");';
  html += '        const kpiGridEl = target.querySelector(".pc-kpi-summary-grid");';
  html += '        const progEl = target.querySelector(".pc-detail-prog-section");';
  html += '        let estimatedHeight = 60;';
  html += '        if (heroEl) estimatedHeight += heroEl.offsetHeight + 14;';
  html += '        if (alertEl) estimatedHeight += alertEl.offsetHeight + 14;';
  html += '        if (kpiGridEl) estimatedHeight += kpiGridEl.offsetHeight + 14;';
  html += '        if (progEl) estimatedHeight += progEl.offsetHeight + 14;';
  html += '        estimatedHeight += tableCardFullHeight + 60;';
  html += '        captureFullHeight = Math.max(captureFullHeight, estimatedHeight);';
  html += '      }';
  html += '      target.style.overflow = "visible";';
  html += '      target.style.height = "auto";';
  html += '      target.style.maxHeight = "none";';
  html += '    } else if (captureType === "calendar") {';
  html += '      const calGrid = target.querySelector("#calGrid");';
  html += '      const weekList = target.querySelector("#calWeekList") || target.querySelector(".pc-weekly-grid");';
  html += '      const weekdaysBar = target.querySelector("#calWeekdaysBar") || target.querySelector(".cal-weekdays");';
  html += '      const navBar = target.querySelector(".cal-nav-bar");';
  html += '      const filterNotice = target.querySelector("#calFilterNotice");';
  html += '      const modeBar = target.querySelector(".cal-mode-bar");';
  html += '      if (calGrid) {';
  html += '        calGrid.scrollTop = 0;';
  html += '        captureFullWidth = Math.max(captureFullWidth, calGrid.scrollWidth || 0, calGrid.offsetWidth || 0);';
  html += '      }';
  html += '      if (weekdaysBar) {';
  html += '        captureFullWidth = Math.max(captureFullWidth, weekdaysBar.scrollWidth || 0, weekdaysBar.offsetWidth || 0);';
  html += '      }';
  html += '      if (weekList) weekList.scrollTop = 0;';
  html += '      let headerH = 0;';
  html += '      if (modeBar && modeBar.offsetHeight) headerH += modeBar.offsetHeight;';
  html += '      if (navBar && navBar.offsetHeight) headerH += navBar.offsetHeight;';
  html += '      if (weekdaysBar && weekdaysBar.offsetHeight) headerH += weekdaysBar.offsetHeight;';
  html += '      if (filterNotice && filterNotice.style.display !== "none" && filterNotice.offsetHeight) headerH += filterNotice.offsetHeight;';
  html += '      gridH = 0;';
  html += '      rowHeights = [];';
  html += '      calRowCount = 0;';
  html += '      if (calGrid && calGrid.style.display !== "none") {';
  html += '        const cells = calGrid.querySelectorAll(".cal-day-cell");';
  html += '        if (cells.length >= 7) {';
  html += '          calRowCount = Math.ceil(cells.length / 7);';
  html += '          let sumRows = 0;';
  html += '          for (let r = 0; r < calRowCount; r++) {';
  html += '            let maxInRow = 0;';
  html += '            for (let c = 0; c < 7; c++) {';
  html += '              const cell = cells[r * 7 + c];';
  html += '              if (cell) {';
  html += '                const pills = cell.querySelectorAll(".cal-event-pill");';
  html += '                const pillCount = pills ? pills.length : 0;';
  html += '                const headerEl = cell.querySelector(".cal-day-header");';
  html += '                const hH = headerEl ? Math.max(headerEl.offsetHeight || 0, 26) : 26;';
  html += '                const pillH = hH + (pillCount * 30) + 16;';
  html += '                const evList = cell.querySelector(".cal-events-list");';
  html += '                const evH = evList ? (hH + evList.scrollHeight + 16) : 0;';
  html += '                const neededH = Math.max(cell.scrollHeight || 0, cell.offsetHeight || 0, evH, pillH, 80);';
  html += '                if (neededH > maxInRow) maxInRow = neededH;';
  html += '              }';
  html += '            }';
  html += '            rowHeights.push(maxInRow);';
  html += '            sumRows += maxInRow;';
  html += '          }';
  html += '          gridH = sumRows + (calRowCount * 2);';
  html += '        } else {';
  html += '          gridH = calGrid.scrollHeight;';
  html += '        }';
  html += '      } else if (weekList && weekList.style.display !== "none") {';
  html += '        gridH = weekList.scrollHeight;';
  html += '        const weekCols = weekList.querySelectorAll(".pc-weekly-col, .cal-week-card");';
  html += '        let maxColH = 0;';
  html += '        for (let i = 0; i < weekCols.length; i++) {';
  html += '          const colH = weekCols[i].scrollHeight || weekCols[i].offsetHeight;';
  html += '          if (colH > maxColH) maxColH = colH;';
  html += '        }';
  html += '        if (maxColH > 0) gridH = Math.max(gridH, maxColH + 30);';
  html += '      }';
  html += '      captureFullHeight = Math.max(captureFullHeight, headerH + gridH + 30);';
  html += '      target.style.overflow = "visible";';
  html += '      target.style.height = "auto";';
  html += '      target.style.maxHeight = "none";';
  html += '    }';
  html += '    html2canvas(target, {';
  html += '      scale: 2,';
  html += '      useCORS: true,';
  html += '      backgroundColor: (captureType === "site") ? "#f8fafc" : "#ffffff",';
  html += '      logging: false,';
  html += '      width: captureFullWidth,';
  html += '      height: captureFullHeight,';
  html += '      windowWidth: (captureType === "site") ? (captureFullWidth + 100) : captureFullWidth,';
  html += '      windowHeight: captureFullHeight + 500,';
  html += '      scrollX: 0,';
  html += '      scrollY: 0,';
  html += '      onclone: function(clonedDoc) {';
  html += '        if (captureType === "site") {';
  html += '          const clonedTarget = clonedDoc.querySelector(".pc-site-detail-pane");';
  html += '          if (!clonedTarget) return;';
