  html += '      target.style.overflow = origOverflow;';
  html += '      target.style.height = origHeight;';
  html += '      target.style.maxHeight = origMaxHeight;';
  html += '      target.scrollTop = origScrollTop;';
  html += '      alert("화면 캡쳐 중 오류가 발생했습니다: " + (err && err.message || err));';
  html += '      if (btn) { btn.disabled = false; btn.innerHTML = origText; }';
  html += '    });';
