  html += '      listHtml += \'      <button type="button" class="cal-day-add-btn" style="width:18px;height:18px;font-size:11px;line-height:1;" onclick="event.stopPropagation();openNewTaskModal(\\\'\\\', \\\'\' + curStr + \'\\\')" title="\' + wAddTitle + \'">+</button>\';';
