  html += '      listHtml += \'<div class="cal-week-card\' + (isToday ? " today" : "") + \'" data-date="\' + curStr + \'" ondragover="onCalDayDragOver(event)" ondragleave="onCalDayDragLeave(event)" ondrop="onCalDayDrop(event, \\\'\' + curStr + \'\\\')">\';';
