  html += '}';
  html += '';
  html += 'function onPcSiteTaskSearch(query) {';
  html += '  pcSiteTaskSearchQuery = query;';
  html += '  const q = (query || "").trim().toLowerCase();';
  html += '  const rows = document.querySelectorAll(".pc-tasks-table tbody tr.pc-task-row");';
  html += '  let visibleCount = 0;';
  html += '  rows.forEach(tr => {';
  html += '    const searchTarget = tr.dataset.search || "";';
  html += '    const matchesSearch = !q || searchTarget.indexOf(q) !== -1;';
  html += '    const filterMode = pcSiteDetailFilter || "all";';
  html += '    const status = tr.dataset.status || "";';
  html += '    const isDelayed = (tr.dataset.delayed === "true");';
  html += '    let matchesFilter = true;';
  html += '    if (filterMode === "prog") matchesFilter = (status.indexOf("진행") !== -1);';
  html += '    else if (filterMode === "delay") matchesFilter = isDelayed;';
  html += '    else if (filterMode === "plan") matchesFilter = (status.indexOf("예정") !== -1 || (status.indexOf("진행") === -1 && status.indexOf("완료") === -1 && status.indexOf("취소") === -1 && !isDelayed));';
  html += '    else if (filterMode === "done") matchesFilter = (status.indexOf("완료") !== -1 || status.indexOf("취소") !== -1);';
  html += '    if (matchesSearch && matchesFilter) {';
  html += '      tr.style.display = "";';
  html += '      visibleCount++;';
  html += '    } else {';
  html += '      tr.style.display = "none";';
  html += '    }';
  html += '  });';
  html += '  let noResultRow = document.getElementById("pcTasksEmptyRow");';
  html += '  if (!noResultRow) {';
  html += '    const tbody = document.querySelector(".pc-tasks-table tbody");';
  html += '    if (tbody) {';
  html += '      noResultRow = document.createElement("tr");';
  html += '      noResultRow.id = "pcTasksEmptyRow";';
  html += '      noResultRow.innerHTML = \'<td colspan="8" style="text-align:center;padding:40px;color:#94a3b8;font-weight:600;">조건에 맞는 공정이 없습니다.</td>\';';
  html += '      tbody.appendChild(noResultRow);';
  html += '    }';
  html += '  }';
  html += '  if (noResultRow) {';
  html += '    noResultRow.style.display = (visibleCount === 0) ? "" : "none";';
  html += '  }';
  html += '  updateSelectAllCheckboxState();';
  html += '}';
  html += '';
  html += 'function filterCalendarBySite(siteName) {';
