  html += '  html += \'        <div class="pc-est-info-row"><span class="lbl">최종 계약금액</span><span class="val big-amt" style="color:\' + (contractAmtStr !== \'-\' ? \'#15803d\' : \'#94a3b8\') + \';">\' + contractAmtStr + \'</span></div>\';';
