  html += '  html += \'      <div class="pc-est-card-body">\';';
  html += '  html += \'        <div class="pc-est-info-row"><span class="lbl">문의 접수일</span><span class="val">\' + escapeHtml(formatEstimateDateYMD(est.inquiryDate)) + \'</span></div>\';';
