  html += '  html += \'    </div>\';';
  html += '  html += \'  </div>\';';
  html += '  const isDoneViewTable = (currentFilter === "done");';
  html += '  const tableTitle = isDoneViewTable ? "신규견적 계약 완료 데이터 현황" : "신규견적 시트 전체 데이터 현황";';
  html += '  html += \'  <div class="pc-est-table-card">\';';
