  html += '  html += \'        <h3 style="margin:0;font-size:15px;font-weight:800;color:#0f172a;">\' + tableTitle + \'</h3>\';';
  html += '  html += \'        <span class="pc-est-table-count">\' + (sitesList ? sitesList.length : 0) + \'건</span>\';';
  html += '  html += \'      </div>\';';
  html += '  html += \'      <div style="display:flex;align-items:center;gap:8px;">\';';
  html += '  html += \'        <input type="text" id="pcEstimateSearchInput" placeholder="현장명, 고객명, 연락처 검색..." oninput="onFilterEstimateTable(this.value)" style="padding:6px 12px;border:1.5px solid #cbd5e1;border-radius:7px;font-size:12px;outline:none;width:200px;">\';';
  html += '  html += \'      </div>\';';
  html += '  html += \'    </div>\';';
  html += '  html += \'    <div style="overflow-x:auto;">\';';
  html += '  html += \'      <table class="pc-est-table" id="pcEstimateDataTable">\';';
  html += '  html += \'        <thead>\';';
  html += '  html += \'          <tr>\';';
  html += '  html += \'            <th style="width:40px;text-align:center;">No</th>\';';
  html += '  html += \'            <th style="min-width:160px;">현장명</th>\';';
  html += '  html += \'            <th style="width:105px;text-align:center;">진행 단계</th>\';';
  html += '  html += \'            <th style="width:80px;text-align:center;">우선순위</th>\';';
  html += '  html += \'            <th style="width:95px;text-align:center;">공사 범위</th>\';';
  html += '  html += \'            <th style="width:85px;text-align:center;">유입 경로</th>\';';
  html += '  html += \'            <th style="min-width:90px;text-align:center;">고객명</th>\';';
  html += '  html += \'            <th style="min-width:125px;text-align:center;">연락처</th>\';';
  html += '  html += \'            <th style="width:75px;text-align:center;">담당자</th>\';';
  html += '  html += \'            <th style="min-width:110px;text-align:right;">예상 공사금액</th>\';';
  html += '  html += \'            <th style="width:100px;text-align:center;">공사 예정일</th>\';';
  html += '  html += \'            <th style="width:105px;text-align:center;">관리</th>\';';
  html += '  html += \'          </tr>\';';
  html += '  html += \'        </thead>\';';
  html += '  html += \'        <tbody>\';';
  html += '  const allItems = sitesList || [];';
  html += '  allItems.forEach((it, idx) => {';
  html += '    const s = it.site || it;';
  html += '    const e = s.estimateData || {};';
  html += '    const isSelected = (s.siteName === selectedPcSiteName);';
  html += '    const rowAmtStr = formatEstimateAmtStr(e.expectedAmount);';
  html += '    const phoneClean = (e.clientPhone || "").replace(/[^0-9+]/g, "");';
  html += '    const eRawPhone = String(e.clientPhone || "").trim();';
  html += '    const eHasPhone = Boolean(phoneClean && phoneClean.length >= 7 && eRawPhone !== "-" && eRawPhone !== "미등록");';
  html += '    const searchStr = (s.siteName + " " + (e.clientName || "") + " " + (e.clientPhone || "") + " " + (e.memo || "") + " " + (e.nextAction || "") + " " + (e.manager || "") + " " + (e.scope || "") + " " + (e.status || "")).toLowerCase();';
  html += '    html += \'          <tr class="pc-est-table-row\' + (isSelected ? \' selected-row\' : \'\') + \'" data-search="\' + escapeHtml(searchStr) + \'" data-sitename="\' + encodeURIComponent(s.siteName) + \'" onclick="selectPcSite(decodeURIComponent(this.dataset.sitename)); openEditEstimateModal(decodeURIComponent(this.dataset.sitename));" title="클릭 시 신규현장 정보 수정">\';';
  html += '    html += \'            <td style="text-align:center;color:#94a3b8;font-weight:700;">\' + (idx + 1) + \'</td>\';';
  html += '    html += \'            <td><strong style="color:\' + (isSelected ? \'#1d4ed8\' : \'#0f172a\') + \';font-size:13px;">\' + escapeHtml(s.siteName) + \'</strong></td>\';';
  html += '    html += \'            <td style="text-align:center;">\' + buildEstimateBadgeHtml("status", e.status || "신규 문의") + \'</td>\';';
  html += '    html += \'            <td style="text-align:center;">\' + buildEstimateBadgeHtml("priority", e.priority || "보통") + \'</td>\';';
  html += '    html += \'            <td style="text-align:center;">\' + buildEstimateBadgeHtml("scope", e.scope || "전체공사") + \'</td>\';';
  html += '    html += \'            <td style="text-align:center;">\' + buildEstimateBadgeHtml("source", e.source || "온라인") + \'</td>\';';
  html += '    html += \'            <td style="text-align:center;font-weight:600;color:#1e293b;">\' + (e.clientName ? escapeHtml(e.clientName) : \'<span style="color:#94a3b8;">-</span>\') + \'</td>\';';
  html += '    html += \'            <td style="text-align:center;font-size:12px;">\' + (eHasPhone ? (\'<a href="tel:\' + escapeHtml(phoneClean) + \'" style="color:#2563eb;text-decoration:none;font-weight:600;" onclick="event.stopPropagation();" title="고객 전화 걸기">📞 \' + escapeHtml(e.clientPhone) + \'</a>\') : \'<span style="color:#94a3b8;">-</span>\') + \'</td>\';';
  html += '    html += \'            <td style="text-align:center;"><span class="pc-manager-pill"><span>\' + escapeHtml(e.manager || "조항만") + \'</span></span></td>\';';
  html += '    html += \'            <td style="text-align:right;font-weight:700;color:#2563eb;">\' + rowAmtStr + \'</td>\';';
  html += '    html += \'            <td style="text-align:center;font-size:12px;color:#475569;">\' + escapeHtml(formatEstimateDateYMD(e.expectedDate)) + \'</td>\';';
  html += '    html += \'            <td style="text-align:center;white-space:nowrap;"><button type="button" class="pc-task-btn-edit" onclick="event.stopPropagation();openEditEstimateModal(decodeURIComponent(this.dataset.sitename))" data-sitename="\' + encodeURIComponent(s.siteName) + \'">수정</button><button type="button" class="pc-task-btn-del" style="margin-left:4px;padding:3px 7px;font-size:11.5px;font-weight:700;border:1px solid #fca5a5;background:#fef2f2;color:#dc2626;border-radius:5px;cursor:pointer;" onclick="event.stopPropagation();confirmDeleteSite(decodeURIComponent(this.dataset.sitename), decodeURIComponent(this.dataset.scope))" data-sitename="\' + encodeURIComponent(s.siteName) + \'" data-scope="newSite" title="신규현장 삭제">삭제</button></td>\';';
  html += '    html += \'          </tr>\';';
  html += '  });';
  html += '  html += \'        </tbody>\';';
  html += '  html += \'      </table>\';';
  html += '  html += \'    </div>\';';
  html += '  html += \'  </div>\';';
  html += '  html += \'</div>\';';
  html += '  return html;';
  html += '}';
  html += '';
  html += '';
  html += 'function renderPcSiteDashboard(matchedSites) {';
  html += '  const container = document.getElementById("contentArea");';
  html += '  if (!container) return;';
  html += '  if (!matchedSites || matchedSites.length === 0) {';
  html += '    const isDoneTab = (currentFilter === "done");';
  html += '    const scopeName = (currentScope === "single") ? "단건" : ((currentScope === "as") ? "AS" : ((currentScope === "newSite") ? "신규현장" : "현장"));';
  html += '    const emptyIcon = isDoneTab ? "✅" : ((currentScope === "single") ? "⚡" : ((currentScope === "as") ? "🔧" : ((currentScope === "newSite") ? "📋" : "🏗️")));';
  html += '    const emptyMsg = isDoneTab ? ("조건에 맞는 완료 " + scopeName + "이(가) 없습니다.") : ("조건에 맞는 진행 " + scopeName + "이(가) 없습니다.");';
  html += '    container.innerHTML = \'<div class="empty-state" style="padding:60px 20px;text-align:center;"><div style="font-size:36px;margin-bottom:12px;">\' + emptyIcon + \'</div><p style="font-size:14px;font-weight:700;color:#64748b;margin-bottom:12px;">\' + emptyMsg + \'</p><button type="button" class="btn-cal-filter-reset" onclick="resetAllCalendarFilters()" style="margin:0 auto;">🔄 필터 초기화하고 전체 \' + scopeName + \' 보기</button></div>\';';
  html += '    return;';
  html += '  }';
  html += '  const sitesList = matchedSites.slice();';
  html += '  const isDoneView = (currentFilter === "done");';
  html += '  if (currentScope === "newSite") {';
  html += '    if (pcSiteSortMode === "inquiry") {';
  html += '      sitesList.sort((a, b) => {';
  html += '        const aDate = (a.site.estimateData && a.site.estimateData.inquiryDate) || "";';
  html += '        const bDate = (b.site.estimateData && b.site.estimateData.inquiryDate) || "";';
  html += '        if (aDate && bDate && aDate !== bDate) return bDate.localeCompare(aDate);';
  html += '        if (aDate && !bDate) return -1;';
  html += '        if (!aDate && bDate) return 1;';
  html += '        return (a.site.siteName || "").localeCompare(b.site.siteName || "", "ko");';
  html += '      });';
  html += '    } else {';
  html += '      const prioOrder = { "긴급": 1, "높음": 2, "보통": 3, "낮음": 4 };';
  html += '      sitesList.sort((a, b) => {';
  html += '        const aPrio = (a.site.estimateData && a.site.estimateData.priority) || "보통";';
  html += '        const bPrio = (b.site.estimateData && b.site.estimateData.priority) || "보통";';
  html += '        const aScore = prioOrder[aPrio] || 99;';
  html += '        const bScore = prioOrder[bPrio] || 99;';
  html += '        if (aScore !== bScore) return aScore - bScore;';
  html += '        const aDate = (a.site.estimateData && a.site.estimateData.inquiryDate) || "";';
  html += '        const bDate = (b.site.estimateData && b.site.estimateData.inquiryDate) || "";';
  html += '        if (aDate && bDate && aDate !== bDate) return bDate.localeCompare(aDate);';
  html += '        return (a.site.siteName || "").localeCompare(b.site.siteName || "", "ko");';
  html += '      });';
  html += '    }';
  html += '  } else if (pcSiteSortMode === "rate") {';
  html += '    sitesList.sort((a, b) => {';
  html += '      const rDiff = (b.site.progressRate || 0) - (a.site.progressRate || 0);';
  html += '      if (rDiff !== 0) return rDiff;';
  html += '      if (isDoneView) {';
  html += '        const bLat = b.latestFilteredMs || 0;';
  html += '        const aLat = a.latestFilteredMs || 0;';
  html += '        if (bLat !== aLat) return bLat - aLat;';
  html += '      } else {';
  html += '        const aEar = a.earliestFilteredMs || 0;';
  html += '        const bEar = b.earliestFilteredMs || 0;';
  html += '        if (aEar && bEar && aEar !== bEar) return aEar - bEar;';
  html += '      }';
  html += '      return (a.site.siteName || "").localeCompare(b.site.siteName || "", "ko");';
  html += '    });';
  html += '  } else if (pcSiteSortMode === "name") {';
  html += '    sitesList.sort((a, b) => (a.site.siteName || "").localeCompare(b.site.siteName || "", "ko"));';
  html += '  } else {';
  html += '    if (isDoneView) {';
  html += '      sitesList.sort((a, b) => {';
  html += '        const bLat = b.latestFilteredMs || 0;';
  html += '        const aLat = a.latestFilteredMs || 0;';
  html += '        if (bLat !== aLat) return bLat - aLat;';
  html += '        return (a.site.siteName || "").localeCompare(b.site.siteName || "", "ko");';
  html += '      });';
  html += '    } else {';
  html += '      sitesList.sort((a, b) => {';
  html += '        const aToday = a.site.hasTodayTask ? 1 : 0;';
  html += '        const bToday = b.site.hasTodayTask ? 1 : 0;';
  html += '        if (aToday !== bToday) return bToday - aToday;';
  html += '        const aEar = a.earliestFilteredMs || 0;';
  html += '        const bEar = b.earliestFilteredMs || 0;';
  html += '        if (aEar && bEar && aEar !== bEar) return aEar - bEar;';
  html += '        if (aEar && !bEar) return -1;';
  html += '        if (!aEar && bEar) return 1;';
  html += '        return (a.site.siteName || "").localeCompare(b.site.siteName || "", "ko");';
  html += '      });';
  html += '    }';
  html += '  }';
  html += '  const isSortChange = pcSiteSortJustChanged;';
  html += '  let curItem = null;';
  html += '  if (isSortChange) {';
  html += '    curItem = sitesList[0];';
  html += '    selectedPcSiteName = curItem ? curItem.site.siteName : "";';
  html += '    pcSiteSortJustChanged = false;';
  html += '  } else {';
  html += '    curItem = sitesList.find(it => it.site.siteName === selectedPcSiteName);';
  html += '    if (!curItem) {';
  html += '      if (checkedSites && checkedSites.size === 1) {';
  html += '        const singleName = Array.from(checkedSites)[0];';
  html += '        if (singleName !== "__NONE__") {';
  html += '          curItem = sitesList.find(it => it.site.siteName === singleName);';
  html += '        }';
  html += '      }';
  html += '      if (!curItem) {';
  html += '        curItem = sitesList[0];';
  html += '      }';
  html += '      selectedPcSiteName = curItem ? curItem.site.siteName : "";';
  html += '    }';
  html += '  }';
  html += '  const curSite = curItem.site;';
  html += '  const allCurTasks = curSite.tasks || [];';
  html += '  let earliestDateStr = "";';
