  html += '  dHtml += \'          <div class="pc-metric-tile-lbl">완료 공정</div>\';';
  html += '  dHtml += \'          <div class="pc-metric-tile-val" style="color:#10b981;">\' + compTotal + \'<span style="font-size:12px;font-weight:700;color:#10b981;margin-left:2px;">건 (\' + pctDone + \'%)</span></div>\';';
  html += '  dHtml += \'        </div>\';';
  html += '  dHtml += \'        <div class="pc-metric-tile\' + (pcSiteDetailFilter === "prog" ? " active" : "") + \'" onclick="setPcSiteDetailFilter(\\\'prog\\\')" title="현재 진행 공정 목록 보기">\';';
  html += '  dHtml += \'          <div class="pc-metric-tile-lbl">현재 진행 공정</div>\';';
  html += '  dHtml += \'          <div class="pc-metric-tile-val" style="color:#2563eb;">\' + progTotal + \'<span style="font-size:12px;font-weight:700;color:#2563eb;margin-left:2px;">건</span></div>\';';
  html += '  dHtml += \'        </div>\';';
  html += '  dHtml += \'        <div class="pc-metric-tile\' + (delayTotal > 0 ? " delay" : "") + (pcSiteDetailFilter === "delay" ? " active" : "") + \'" onclick="setPcSiteDetailFilter(\\\'delay\\\')" title="공정 지연 목록 보기">\';';
  html += '  dHtml += \'          <div class="pc-metric-tile-lbl">공정 지연 ⚠️</div>\';';
  html += '  dHtml += \'          <div class="pc-metric-tile-val">\' + delayTotal + \'<span style="font-size:12px;font-weight:700;margin-left:2px;">건\' + (delayTotal > 0 ? \' <span style="font-size:10px;font-weight:800;color:#dc2626;">조치필요</span>\' : \'\') + \'</span></div>\';';
  html += '  dHtml += \'        </div>\';';
  html += '  dHtml += \'      </div>\';';
  html += '  dHtml += \'      <div class="pc-prog-summary-wrap">\';';
  html += '  dHtml += \'        <div class="pc-prog-legend-row">\';';
  html += '  dHtml += \'          <span>전체 공정 진척도 요약</span>\';';
  html += '  dHtml += \'          <div class="pc-legend-items">\';';
  html += '  dHtml += \'            <span class="pc-legend-item"><span class="pc-legend-dot" style="background:#10b981;"></span> 완료 \' + pctDone + \'%</span>\';';
  html += '  dHtml += \'            <span class="pc-legend-item"><span class="pc-legend-dot" style="background:#2563eb;"></span> 진행 \' + pctProg + \'%</span>\';';
  html += '  dHtml += \'            <span class="pc-legend-item"><span class="pc-legend-dot" style="background:#ef4444;"></span> 지연 \' + pctDelay + \'%</span>\';';
  html += '  dHtml += \'            <span class="pc-legend-item"><span class="pc-legend-dot" style="background:#cbd5e1;"></span> 예정 \' + pctPlan + \'%</span>\';';
  html += '  dHtml += \'          </div>\';';
  html += '  dHtml += \'        </div>\';';
  html += '  dHtml += \'        <div class="pc-multi-track">\';';
  html += '  dHtml += \'          <div style="width:\' + pctDone + \'%;background:#10b981;" title="완료 \' + pctDone + \'%"></div>\';';
  html += '  dHtml += \'          <div style="width:\' + pctProg + \'%;background:#2563eb;" title="진행 \' + pctProg + \'%"></div>\';';
  html += '  dHtml += \'          <div style="width:\' + pctDelay + \'%;background:#ef4444;" title="지연 \' + pctDelay + \'%"></div>\';';
  html += '  dHtml += \'          <div style="width:\' + pctPlan + \'%;background:#e2e8f0;" title="예정 \' + pctPlan + \'%"></div>\';';
  html += '  dHtml += \'        </div>\';';
  html += '  dHtml += \'      </div>\';';
  html += '  dHtml += \'    </div>\';';
  html += '  const filteredTasks = allCurTasks.filter(t => {';
  html += '    const stClean = (t.status || "").replace(/\\s+/g, "");';
  html += '    const isDone = (stClean.indexOf("완료") !== -1 || stClean.indexOf("취소") !== -1);';
  html += '    const isProg = (stClean.indexOf("진행") !== -1);';
  html += '    const isDelay = (t.isDelayed === true && !isDone);';
  html += '    const isPlan = (!isDone && !isProg && !isDelay);';
  html += '    if (pcSiteDetailFilter === "prog" && !isProg) return false;';
  html += '    if (pcSiteDetailFilter === "delay" && !isDelay) return false;';
  html += '    if (pcSiteDetailFilter === "plan" && !isPlan) return false;';
  html += '    if (pcSiteDetailFilter === "done" && !isDone) return false;';
  html += '    if (pcSiteTaskSearchQuery) {';
  html += '      const q = pcSiteTaskSearchQuery;';
  html += '      const matchT = (t.taskName || "").toLowerCase().indexOf(q) !== -1;';
  html += '      const matchM = (t.manager || "").toLowerCase().indexOf(q) !== -1;';
  html += '      const matchP = (t.partner || "").toLowerCase().indexOf(q) !== -1;';
  html += '      const matchMemo = (t.memo || "").toLowerCase().indexOf(q) !== -1;';
  html += '      if (!matchT && !matchM && !matchP && !matchMemo) return false;';
  html += '    }';
  html += '    return true;';
  html += '  });';
  html += '  dHtml += \'    <div class="pc-tasks-table-card">\';';
  html += '  dHtml += \'      <div class="pc-tasks-toolbar">\';';
  html += '  dHtml += \'        <div class="pc-tab-pills">\';';
  html += '  dHtml += \'          <button type="button" class="pc-tab-pill\' + (pcSiteDetailFilter === "all" ? " active" : "") + \'" onclick="setPcSiteDetailFilter(\\\'all\\\')">전체 공정 \' + validTotal + \'</button>\';';
  html += '  dHtml += \'          <button type="button" class="pc-tab-pill\' + (pcSiteDetailFilter === "prog" ? " active" : "") + \'" onclick="setPcSiteDetailFilter(\\\'prog\\\')">진행중 \' + progTotal + \'</button>\';';
  html += '  dHtml += \'          <button type="button" class="pc-tab-pill delay-pill\' + (pcSiteDetailFilter === "delay" ? " active" : "") + \'" onclick="setPcSiteDetailFilter(\\\'delay\\\')">⚠️ 지연 \' + delayTotal + \'</button>\';';
  html += '  dHtml += \'          <button type="button" class="pc-tab-pill\' + (pcSiteDetailFilter === "plan" ? " active" : "") + \'" onclick="setPcSiteDetailFilter(\\\'plan\\\')">예정 \' + planTotal + \'</button>\';';
  html += '  dHtml += \'          <button type="button" class="pc-tab-pill\' + (pcSiteDetailFilter === "done" ? " active" : "") + \'" onclick="setPcSiteDetailFilter(\\\'done\\\')">완료 \' + compTotal + \'</button>\';';
  html += '  dHtml += \'        </div>\';';
  html += '  dHtml += \'        <div style="display:flex;align-items:center;gap:8px;">\';';
  html += '  dHtml += \'          <input type="text" id="pcSiteTaskSearchInput" style="padding:6px 12px;border:1.5px solid #e2e8f0;border-radius:7px;font-size:12px;outline:none;width:190px;" placeholder="검색" value="\' + escapeHtml(pcSiteTaskSearchQuery) + \'" oninput="onPcSiteTaskSearch(this.value)">\';';
  html += '  dHtml += \'        </div>\';';
  html += '  dHtml += \'      </div>\';';
  html += '  dHtml += \'      <table class="pc-tasks-table">\';';
  html += '  dHtml += \'        <thead><tr><th style="width:38px;text-align:center;padding:10px 4px;"><input type="checkbox" id="pcSiteTaskSelectAll" onchange="toggleSelectAllPcSiteTasks(this.checked)" title="전체 선택/해제" style="cursor:pointer;width:15px;height:15px;accent-color:#2563eb;"></th><th style="width:88px;text-align:center;">상태</th><th style="width:120px;min-width:100px;">공종</th><th style="width:190px;">일정</th><th style="width:105px;text-align:center;">담당자</th><th style="width:160px;min-width:150px;">협력업체</th><th style="min-width:180px;">비고 및 특이사항</th><th style="width:105px;text-align:center;">관리</th></tr></thead>\';';
  html += '  dHtml += \'        <tbody>\';';
  html += '  if (filteredTasks.length === 0) {';
  html += '    dHtml += \'          <tr><td colspan="8" style="text-align:center;padding:40px;color:#94a3b8;font-weight:600;">조건에 맞는 공정이 없습니다.</td></tr>\';';
  html += '  } else {';
  html += '    filteredTasks.forEach(task => {';
  html += '      const rawStatus = String(task.status || "").trim();';
  html += '      const stClean = rawStatus.replace(/\\s+/g, "");';
  html += '      const isDone = (stClean.indexOf("완료") !== -1 || stClean.indexOf("✅") !== -1);';
  html += '      const isDelayed = (task.isDelayed === true && !isDone);';
  html += '      const isProg = (stClean.indexOf("진행") !== -1 || stClean.indexOf("▶") !== -1);';
  html += '      const isCancel = (stClean.indexOf("취소") !== -1 || stClean.indexOf("중단") !== -1);';
  html += '      const isAs = (stClean.indexOf("AS") !== -1 || stClean.indexOf("A/S") !== -1 || stClean.indexOf("as") !== -1 || stClean.indexOf("🛠") !== -1);';
  html += '      let badgeCls = "plan";';
  html += '      let badgeIcon = "⏳";';
  html += '      let badgeText = rawStatus || "예정";';
  html += '      if (isDelayed) { badgeCls = "delay"; badgeIcon = "⚠️"; badgeText = "지연"; }';
  html += '      else if (isDone) { badgeCls = "done"; badgeIcon = "✅"; badgeText = "완료"; }';
  html += '      else if (isProg) { badgeCls = "prog"; badgeIcon = "▶️"; badgeText = rawStatus || "진행중"; }';
  html += '      else if (isAs) { badgeCls = "as"; badgeIcon = "🛠️"; badgeText = rawStatus || "A/S"; }';
  html += '      else if (isCancel) { badgeCls = "cancel"; badgeIcon = "⛔"; badgeText = rawStatus || "취소"; }';
  html += '      const dateStr = (task.startDateStr || "") + (task.endDateStr && task.endDateStr !== task.startDateStr ? " ~ " + task.endDateStr : "");';
  html += '      let ddayChip = "";';
  html += '      if (isDelayed && task.startDateStr) {';
  html += '        const diffD = Math.max(1, Math.ceil((new Date(todayStr) - new Date(task.startDateStr)) / (1000 * 60 * 60 * 24)));';
  html += '        ddayChip = \' <span class="pc-c-delay-tag">+\' + diffD + \'일 경과</span>\';';
  html += '      }';
  html += '      const tMgr = formatManagerName(task.manager);';
  html += '      const searchTargetStr = ((task.taskName || "") + " " + (task.manager || "") + " " + (task.memo || "") + " " + (task.partner || "")).toLowerCase();';
  html += '      const encCurSite = encodeURIComponent(curSite.siteName || "");';
  html += '      const isTaskChecked = checkedSiteTasks.has((curSite.siteName || "") + "::" + task.row);';
  html += '      dHtml += \'          <tr class="pc-task-row\' + (isDelayed ? \' delay-highlight\' : \'\') + (isTaskChecked ? \' row-selected\' : \'\') + \'" data-search="\' + escapeHtml(searchTargetStr) + \'" data-status="\' + escapeHtml(task.status || "") + \'" data-delayed="\' + (isDelayed ? "true" : "false") + \'" ondblclick="openEditModal(\\\'\' + task.row + \'\\\', \\\'\' + encCurSite + \'\\\')" title="더블클릭하여 공정 수정">\';';
  html += '      dHtml += \'            <td style="text-align:center;padding:12px 4px;" onclick="event.stopPropagation()"><input type="checkbox" class="pc-site-task-cb" data-site="\' + encCurSite + \'" data-row="\' + task.row + \'" data-task="\' + escapeHtml(task.taskName || "") + \'" \' + (isTaskChecked ? \'checked\' : \'\') + \' onchange="onPcSiteTaskCheckboxChange(event)" style="cursor:pointer;width:15px;height:15px;accent-color:#2563eb;"></td>\';';
  html += '      dHtml += \'            <td style="text-align:center;"><span class="pc-status-pill \' + badgeCls + \'"><span class="pill-icon">\' + badgeIcon + \'</span><span>\' + escapeHtml(badgeText) + \'</span></span></td>\';';
  html += '      const isSh = (task.isShared === true || String(task.isShared).toLowerCase() === "true" || String(task.isShared) === "1" || String(task.isShared) === "Y" || String(task.isShared) === "공유");';
  html += '      const shareIconHtml = isSh ? \'<span style="display:inline-block;width:12px;height:12px;border-radius:2.5px;background:#2563eb;margin-right:7px;vertical-align:middle;box-shadow:0 1px 2px rgba(37,99,235,0.25);flex-shrink:0;" title="공정 공유 (ON)" aria-label="공유"></span>\' : \'<span style="display:inline-block;width:12px;height:12px;border-radius:2.5px;background:#ef4444;margin-right:7px;vertical-align:middle;box-shadow:0 1px 2px rgba(239,68,68,0.25);flex-shrink:0;" title="미공유 (OFF)" aria-label="미공유"></span>\';';
  html += '      dHtml += \'            <td>\' + shareIconHtml + \'<strong style="color:#0f172a;font-size:13px;vertical-align:middle;">\' + escapeHtml(task.taskName) + \'</strong></td>\';';
  html += '      dHtml += \'            <td><span style="\' + (isDelayed ? \'color:#dc2626;font-weight:800;\' : \'font-weight:600;\') + \'">\' + escapeHtml(dateStr || "일정 미정") + \'</span>\' + ddayChip + \'</td>\';';
  html += '      dHtml += \'            <td style="text-align:center;">\' + (tMgr ? \'<span class="pc-manager-pill"><span class="mgr-icon">👤</span><span>\' + escapeHtml(tMgr) + \'</span></span>\' : \'<span style="color:#94a3b8;font-size:11.5px;">미등록</span>\') + \'</td>\';';
  html += '      const pcPPhone = task.partner ? getPartnerPhoneNumber(task.partner) : "";';
  html += '      const pcPCallHtml = pcPPhone ? (\' <a href="tel:\' + escapeHtml(pcPPhone.replace(/[^0-9+]/g, "")) + \'" onclick="event.stopPropagation()" style="display:inline-flex;align-items:center;justify-content:center;width:18px;height:18px;border-radius:50%;background:#22c55e;color:#fff;text-decoration:none;font-size:10px;vertical-align:middle;margin-left:4px;" title="전화 걸기: \' + escapeHtml(pcPPhone) + \'">📞</a>\') : "";';
  html += '      dHtml += \'            <td>\' + (task.partner ? \'<span class="pc-partner-pill">\' + escapeHtml(task.partner) + pcPCallHtml + \'</span>\' : \'<span style="color:#94a3b8;font-size:11.5px;">미등록</span>\') + \'</td>\';';
  html += '      dHtml += \'            <td><span style="\' + (isDelayed ? \'color:#dc2626;font-size:12px;\' : \'color:#475569;font-size:12px;\') + \'">\' + escapeHtml(task.memo || "-") + \'</span></td>\';';
  html += '      const encTaskName = encodeURIComponent(task.taskName || "");';
  html += '      const encTaskSheet = encodeURIComponent(task.sheetName || curSite.scope || "");';
  html += '      dHtml += \'            <td style="text-align:center;white-space:nowrap;"><button type="button" class="pc-task-btn-edit" onclick="event.stopPropagation();openEditModal(\\\'\' + task.row + \'\\\', \\\'\' + encCurSite + \'\\\')">수정</button><button type="button" class="pc-task-btn-del" style="margin-left:4px;padding:3px 7px;font-size:11.5px;font-weight:700;border:1px solid #fca5a5;background:#fef2f2;color:#dc2626;border-radius:5px;cursor:pointer;" onclick="event.stopPropagation();confirmDeleteSingleTask(decodeURIComponent(this.dataset.site), this.dataset.row, decodeURIComponent(this.dataset.task), decodeURIComponent(this.dataset.sheet))" data-site="\' + encCurSite + \'" data-row="\' + task.row + \'" data-task="\' + encTaskName + \'" data-sheet="\' + encTaskSheet + \'" title="이 공정 삭제">삭제</button></td>\';';
  html += '      dHtml += \'          </tr>\';';
