  html += '  dHtml += \'        </tbody>\';';
  html += '  dHtml += \'      </table>\';';
  html += '  dHtml += \'    </div>\';';
  html += '  dHtml += \'  </div>\';';
  html += '  dHtml += \'  <button type="button" id="pcScrollTopBtn" class="pc-scroll-top-btn" onclick="scrollPcDetailTop()" title="맨 위로 이동">⬆ 맨 위로</button>\';';
  html += '  dHtml += \'</div>\';';
  html += '  container.innerHTML = dHtml;';
  html += '  if (hadSearchFocus) {';
