  html += 'const mobileExpandedEstimateSites = new Set();';
  html += '';
  html += 'function toggleMobileEstimateCard(siteEnc) {';
  html += '  const siteName = decodeURIComponent(siteEnc);';
  html += '  if (mobileExpandedEstimateSites.has(siteName)) {';
  html += '    mobileExpandedEstimateSites.delete(siteName);';
  html += '  } else {';
  html += '    mobileExpandedEstimateSites.add(siteName);';
  html += '  }';
  html += '  renderList();';
  html += '}';
  html += '';
  html += 'function renderMobileEstimateDashboard(matchedSites, query) {';
  html += '  const container = document.getElementById("contentArea");';
  html += '  if (!container || !rawData || !Array.isArray(rawData.sites)) return;';
  html += '  const isDoneMode = (currentFilter === "done");';
