  html += '  mHtml += \'    <span>📊</span> 시트 열기 ↗\';';
  html += '  mHtml += \'  </button>\';';
  html += '  mHtml += \'</div>\';';
  html += '  if (targetList.length === 0) {';
  html += '    mHtml += \'<div style="text-align:center;padding:36px 16px;color:#94a3b8;font-size:13px;background:#ffffff;border-radius:10px;border:1px dashed #cbd5e1;">\';';
  html += '    mHtml += \'  <div style="font-size:24px;margin-bottom:6px;">📋</div>\';';
  html += '    mHtml += \'  <div>\' + (isDoneMode ? "계약 완료된 신규현장이 없습니다." : "진행 중인 신규현장이 없습니다.") + \'</div>\';';
  html += '    mHtml += \'</div>\';';
  html += '    container.innerHTML = mHtml;';
