  html += '    html += \'          </button>\';';
  html += '    html += \'          <button type="button" class="mob-site-upload-action-btn" onclick="event.stopPropagation();openSiteFileUploadModal(decodeURIComponent(\\\'\' + siteEnc + \'\\\'))" title="현장 드라이브 폴더로 사진/파일 업로드" style="display:inline-flex;align-items:center;justify-content:center;gap:6px;padding:8px 8px;background:#eff6ff;color:#1d4ed8;border:1.5px solid #93c5fd;border-radius:8px;font-size:12px;font-weight:800;cursor:pointer;transition:all 0.15s ease;box-shadow:0 1px 2px rgba(37,99,235,0.12);">\';';
  html += '    html += \'            <span style="font-size:13.5px;">📤</span>\';';
