  html += '      const stIcon = getTaskStatusIcon(task.status);';
  html += '      html += \'      <span class="status-tag \' + statusClass + \'">\' + (task.isDelayed ? "⚠️ 지연" : ((stIcon ? stIcon + " " : "") + escapeHtml(task.status || "예정"))) + \'</span>\';';
  html += '      html += \'    </div>\';';
