  html += '';
  html += 'function extractSheetModalDateRange() {';
  html += '  const dateInput = document.getElementById("sheetDateInput");';
  html += '  const hiddenPicker = document.getElementById("sheetNativeDatePicker");';
  html += '  const rawVal = dateInput ? String(dateInput.value || "") : "";';
  html += '  const matches = [];';
  html += '  const re = /(\\d{2,4})[-./]\\s*(\\d{1,2})[-./]\\s*(\\d{1,2})/g;';
  html += '  let m;';
  html += '  while ((m = re.exec(rawVal)) !== null) {';
  html += '    let y = parseInt(m[1], 10);';
  html += '    if (y < 100) y += 2000;';
  html += '    const mo = parseInt(m[2], 10);';
  html += '    const da = parseInt(m[3], 10);';
  html += '    matches.push(y + "-" + (mo < 10 ? "0" + mo : mo) + "-" + (da < 10 ? "0" + da : da));';
  html += '  }';
  html += '  if (matches.length >= 2) {';
  html += '    const s = matches[0] <= matches[1] ? matches[0] : matches[1];';
  html += '    const e = matches[0] <= matches[1] ? matches[1] : matches[0];';
  html += '    return { startIso: s, endIso: e };';
  html += '  }';
  html += '  if (matches.length === 1) {';
  html += '    return { startIso: matches[0], endIso: matches[0] };';
  html += '  }';
  html += '  if (hiddenPicker && hiddenPicker.value && /^\\d{4}-\\d{2}-\\d{2}$/.test(hiddenPicker.value)) {';
  html += '    return { startIso: hiddenPicker.value, endIso: hiddenPicker.value };';
  html += '  }';
  html += '  return { startIso: "", endIso: "" };';
  html += '}';
  html += '';
  html += 'function getSheetModalActiveManagers() {';
  html += '  const sel1 = document.getElementById("sheetManagerSelect");';
  html += '  const cus1 = document.getElementById("sheetManagerCustomInput");';
  html += '  const sel2 = document.getElementById("sheetManagerSelect2");';
  html += '  const cus2 = document.getElementById("sheetManagerCustomInput2");';
  html += '  const list = [];';
  html += '  if (sel1) {';
  html += '    const v1 = (sel1.value === "__CUSTOM__") ? (cus1 ? cus1.value.trim() : "") : sel1.value.trim();';
  html += '    if (v1) list.push(v1);';
  html += '  }';
  html += '  if (sel2) {';
  html += '    const v2 = (sel2.value === "__CUSTOM__") ? (cus2 ? cus2.value.trim() : "") : sel2.value.trim();';
  html += '    if (v2 && list.indexOf(v2) === -1) list.push(v2);';
  html += '  }';
  html += '  return list;';
  html += '}';
  html += '';
  html += 'function getSheetModalActiveSiteName() {';
  html += '  if (isCreateMode) {';
  html += '    const siteSel = document.getElementById("sheetSiteSelect");';
  html += '    const siteCustom = document.getElementById("sheetSiteCustomInput");';
  html += '    if (!siteSel) return "";';
  html += '    return (siteSel.value === "__CUSTOM__") ? (siteCustom ? siteCustom.value.trim() : "") : siteSel.value.trim();';
  html += '  }';
  html += '  return curSiteName || "";';
  html += '}';
  html += '';
  html += 'function checkSheetScheduleConflicts() {';
  html += '  const banner = document.getElementById("sheetConflictBanner");';
  html += '  if (!banner) return;';
  html += '  if (curEstimateEditSite) { banner.style.display = "none"; banner.innerHTML = ""; return; }';
  html += '  if (isCreateMode) {';
  html += '    const catEl = (typeof document !== "undefined" && typeof document.querySelector === "function") ? document.querySelector(\'input[name="sheetCategory"]:checked\') : null;';
  html += '    if (catEl && catEl.value === "newSite") { banner.style.display = "none"; banner.innerHTML = ""; return; }';
  html += '  }';
  html += '  const range = extractSheetModalDateRange();';
  html += '  if (!range.startIso || !rawData || !Array.isArray(rawData.sites)) {';
  html += '    banner.style.display = "none";';
  html += '    banner.innerHTML = "";';
  html += '    return;';
  html += '  }';
  html += '  const partnerVal = getSelectedPartnerValue(isCreateMode);';
  html += '  const cleanPartner = String(partnerVal || "").trim();';
  html += '  const partnerCore = cleanPartner.indexOf("_") !== -1 ? cleanPartner.substring(cleanPartner.indexOf("_") + 1).trim() : cleanPartner;';
  html += '  const mgrs = getSheetModalActiveManagers();';
  html += '  const activeSite = getSheetModalActiveSiteName();';
  html += '  if (!cleanPartner && mgrs.length === 0) {';
  html += '    banner.style.display = "none";';
  html += '    banner.innerHTML = "";';
  html += '    return;';
  html += '  }';
  html += '  const partnerConflicts = [];';
  html += '  const managerConflicts = [];';
  html += '  for (let si = 0; si < rawData.sites.length; si++) {';
  html += '    const s = rawData.sites[si];';
  html += '    if (!s || s.isArchived || s.scope === "newSite" || !Array.isArray(s.tasks)) continue;';
  html += '    for (let ti = 0; ti < s.tasks.length; ti++) {';
  html += '      const t = s.tasks[ti];';
  html += '      if (!t || !t.startDateStr) continue;';
  html += '      const stClean = String(t.status || "").replace(/\\s+/g, "");';
  html += '      if (stClean.indexOf("취소") !== -1) continue;';
  html += '      if (!isCreateMode && curTaskObj && t.row === curTaskObj.row && s.siteName === curSiteName) continue;';
  html += '      const tStart = t.startDateStr;';
  html += '      const tEnd = t.endDateStr || tStart;';
  html += '      if (tStart > range.endIso || range.startIso > tEnd) continue;';
  html += '      const dShort = (tStart === tEnd) ? tStart.slice(5) : (tStart.slice(5) + "~" + tEnd.slice(5));';
  html += '      if (cleanPartner) {';
  html += '        const tPartner = String(t.partner || "").trim();';
  html += '        if (tPartner) {';
  html += '          const tCore = tPartner.indexOf("_") !== -1 ? tPartner.substring(tPartner.indexOf("_") + 1).trim() : tPartner;';
  html += '          if (tPartner === cleanPartner || (partnerCore && tCore === partnerCore)) {';
  html += '            partnerConflicts.push({ siteName: s.siteName, taskName: t.taskName, dateStr: dShort, partner: tPartner });';
  html += '          }';
  html += '        }';
  html += '      }';
  html += '      if (mgrs.length > 0 && s.siteName !== activeSite) {';
  html += '        const tMgrRaw = String(t.manager || "").trim();';
  html += '        if (tMgrRaw) {';
  html += '          const tMgrList = tMgrRaw.split(/[,/]/).map(x => x.trim()).filter(Boolean);';
  html += '          const matched = mgrs.filter(m => tMgrList.indexOf(m) !== -1);';
  html += '          if (matched.length > 0) {';
  html += '            managerConflicts.push({ siteName: s.siteName, taskName: t.taskName, dateStr: dShort, managers: matched.join(", ") });';
  html += '          }';
  html += '        }';
  html += '      }';
  html += '    }';
  html += '  }';
  html += '  if (partnerConflicts.length === 0 && managerConflicts.length === 0) {';
  html += '    banner.style.display = "none";';
  html += '    banner.innerHTML = "";';
  html += '    return;';
  html += '  }';
  html += '  let bHtml = "";';
  html += '  if (partnerConflicts.length > 0) {';
  html += '    banner.style.background = "#fef2f2";';
  html += '    banner.style.borderColor = "#fca5a5";';
  html += '    banner.style.color = "#991b1b";';
  html += '    bHtml += \'<div style="font-weight:800;font-size:11.5px;margin-bottom:3px;">⚠️ [협력업체 더블부킹 주의] <b>\' + escapeHtml(cleanPartner) + \'</b> 업체는 해당 날짜에 이미 <b>\' + partnerConflicts.length + \'건</b>의 일정이 있습니다!</div>\';';
  html += '    partnerConflicts.slice(0, 3).forEach(c => {';
  html += '      bHtml += \'<div style="font-size:11px;padding-left:6px;">• [<b>\' + escapeHtml(c.siteName) + \'</b>] \' + escapeHtml(c.taskName) + \' (\' + escapeHtml(c.dateStr) + \')</div>\';';
  html += '    });';
  html += '    if (partnerConflicts.length > 3) bHtml += \'<div style="font-size:10.5px;padding-left:6px;opacity:0.85;">외 \' + (partnerConflicts.length - 3) + \'건 더 있음</div>\';';
  html += '  } else {';
  html += '    banner.style.background = "#fffbeb";';
  html += '    banner.style.borderColor = "#fcd34d";';
  html += '    banner.style.color = "#92400e";';
  html += '  }';
  html += '  if (managerConflicts.length > 0) {';
  html += '    const topMargin = partnerConflicts.length > 0 ? "margin-top:6px;padding-top:5px;border-top:1px dashed #fca5a5;" : "";';
  html += '    bHtml += \'<div style="font-size:11px;\' + topMargin + \'">👥 <strong>[담당자 타 현장 일정]</strong> 같은 날 다른 현장에 <b>\' + managerConflicts.length + \'건</b> 배정됨: \';';
  html += '    bHtml += managerConflicts.slice(0, 3).map(c => \'[<b>\' + escapeHtml(c.siteName) + \'</b>] \' + escapeHtml(c.taskName) + \'(\' + escapeHtml(c.managers) + \')\').join(", ");';
  html += '    if (managerConflicts.length > 3) bHtml += " 외 " + (managerConflicts.length - 3) + "건";';
  html += '    bHtml += \'</div>\';';
  html += '  }';
  html += '  banner.innerHTML = bHtml;';
  html += '  banner.style.display = "block";';
  html += '}';
  html += '';
  html += 'function shiftYmdByDays(ymdStr, diffDays) {';
  html += '  if (!ymdStr || !diffDays) return ymdStr || "";';
  html += '  const parts = String(ymdStr).split("-");';
  html += '  if (parts.length !== 3) return ymdStr;';
  html += '  const dt = new Date(parseInt(parts[0], 10), parseInt(parts[1], 10) - 1, parseInt(parts[2], 10));';
  html += '  dt.setDate(dt.getDate() + diffDays);';
  html += '  const y = dt.getFullYear(), m = dt.getMonth() + 1, d = dt.getDate();';
  html += '  return y + "-" + (m < 10 ? "0" + m : m) + "-" + (d < 10 ? "0" + d : d);';
  html += '}';
  html += '';
  html += 'function buildShiftedTaskDateDisplay(taskObj, diffDays) {';
  html += '  if (!taskObj || !taskObj.startDateStr || !diffDays) return (taskObj && taskObj.dateDisplay) || "";';
  html += '  const newStart = shiftYmdByDays(taskObj.startDateStr, diffDays);';
  html += '  const origEnd = taskObj.endDateStr || taskObj.startDateStr;';
  html += '  const newEnd = shiftYmdByDays(origEnd, diffDays);';
  html += '  const prevVal = String(taskObj.dateDisplay || "");';
  html += '  const timeMatch = prevVal.match(/(\\s+\\d{1,2}:\\d{2}(?:\\s*~\\s*\\d{1,2}:\\d{2})?)$/);';
  html += '  const timeSuffix = timeMatch ? timeMatch[1] : "";';
  html += '  if (newStart === newEnd) {';
  html += '    return formatYmdToDisplayWithDow(newStart) + timeSuffix;';
  html += '  }';
  html += '  return formatYmdToDisplayWithDow(newStart) + " ~ " + formatYmdToDisplayWithDow(newEnd);';
  html += '}';
  html += '';
  html += 'function getCascadeShiftContext() {';
  html += '  if (isCreateMode || curEstimateEditSite || !curTaskObj || !curSiteName || !curTaskObj.startDateStr || curTaskObj.isArchived) {';
  html += '    return { diffDays: 0, tasks: [] };';
  html += '  }';
  html += '  const range = extractSheetModalDateRange();';
  html += '  if (!range.startIso) return { diffDays: 0, tasks: [] };';
  html += '  const origStart = curTaskObj.startDateStr;';
  html += '  if (range.startIso === origStart) return { diffDays: 0, tasks: [] };';
  html += '  const p1 = origStart.split("-");';
  html += '  const p2 = range.startIso.split("-");';
  html += '  if (p1.length !== 3 || p2.length !== 3) return { diffDays: 0, tasks: [] };';
  html += '  const d1 = new Date(parseInt(p1[0], 10), parseInt(p1[1], 10) - 1, parseInt(p1[2], 10));';
  html += '  const d2 = new Date(parseInt(p2[0], 10), parseInt(p2[1], 10) - 1, parseInt(p2[2], 10));';
  html += '  const diffDays = Math.round((d2.getTime() - d1.getTime()) / 86400000);';
  html += '  if (!diffDays || isNaN(diffDays) || !rawData || !Array.isArray(rawData.sites)) return { diffDays: 0, tasks: [] };';
  html += '  const siteObj = rawData.sites.find(s => s && s.siteName === curSiteName && !s.isArchived && (s.scope || "site") === (curTaskObj.scope || "site")) || rawData.sites.find(s => s && s.siteName === curSiteName && !s.isArchived);';
  html += '  if (!siteObj || !Array.isArray(siteObj.tasks)) return { diffDays: 0, tasks: [] };';
  html += '  const subTasks = siteObj.tasks.filter(t => {';
  html += '    if (!t || t === curTaskObj || t.row === curTaskObj.row || !t.startDateStr) return false;';
  html += '    const st = String(t.status || "").replace(/\\s+/g, "");';
  html += '    if (st.indexOf("완료") !== -1 || st.indexOf("취소") !== -1) return false;';
  html += '    return (t.startDateStr > origStart) || (t.startDateStr === origStart && (t.row || 0) > (curTaskObj.row || 0));';
  html += '  });';
  html += '  return { diffDays: diffDays, tasks: subTasks };';
  html += '}';
  html += '';
  html += 'function updateCascadeShiftUI() {';
  html += '  const box = document.getElementById("sheetCascadeShiftBox");';
  html += '  const chk = document.getElementById("sheetCascadeShiftChk");';
  html += '  const titleEl = document.getElementById("sheetCascadeShiftTitle");';
  html += '  const descEl = document.getElementById("sheetCascadeShiftDesc");';
  html += '  if (!box) return;';
  html += '  const ctx = getCascadeShiftContext();';
  html += '  if (!ctx.diffDays || ctx.tasks.length === 0) {';
  html += '    box.style.display = "none";';
  html += '    if (chk) chk.checked = false;';
  html += '    return;';
  html += '  }';
  html += '  const dirStr = ctx.diffDays > 0 ? ("+" + ctx.diffDays + "일 뒤로 밀기") : (ctx.diffDays + "일 앞으로 당기기");';
  html += '  if (titleEl) titleEl.innerText = "⏩ 이 공정 이후 후속 일정 " + ctx.tasks.length + "건도 함께 " + dirStr;';
  html += '  if (descEl) {';
  html += '    const names = ctx.tasks.slice(0, 4).map(t => t.taskName).join(", ") + (ctx.tasks.length > 4 ? " 외 " + (ctx.tasks.length - 4) + "건" : "");';
  html += '    descEl.innerText = "대상 공정: " + names + " (완료 공정 제외)";';
  html += '  }';
  html += '  box.style.display = "block";';
  html += '}';
  html += '';
  html += 'let mReportYear = new Date().getFullYear();';
  html += 'let mReportMonth = new Date().getMonth() + 1;';
  html += 'let mReportTab = "partner";';
  html += 'let mReportScope = "all";';
  html += '';
  html += 'function openMonthlyReportModal() {';
  html += '  if (typeof calYear === "number" && calYear > 2000 && typeof calMonth === "number" && calMonth >= 1 && calMonth <= 12) {';
  html += '    mReportYear = calYear;';
  html += '    mReportMonth = calMonth;';
  html += '  } else {';
  html += '    const now = new Date();';
  html += '    mReportYear = now.getFullYear();';
  html += '    mReportMonth = now.getMonth() + 1;';
  html += '  }';
  html += '  const sInp = document.getElementById("monthlyReportSearchInput");';
  html += '  if (sInp) sInp.value = "";';
  html += '  const overlay = document.getElementById("monthlyReportModalOverlay");';
  html += '  if (overlay) {';
  html += '    overlay.style.display = "flex";';
  html += '    overlay.classList.add("show");';
  html += '  }';
  html += '  renderMonthlyReportContent();';
  html += '}';
  html += '';
  html += 'function closeMonthlyReportModal(e) {';
  html += '  const overlay = document.getElementById("monthlyReportModalOverlay");';
  html += '  if (e && e.target !== overlay && !e.target.classList.contains("sheet-close")) return;';
  html += '  if (overlay) {';
  html += '    overlay.classList.remove("show");';
  html += '    overlay.style.display = "none";';
  html += '  }';
  html += '}';
  html += '';
  html += 'function changeReportMonth(delta) {';
  html += '  mReportMonth += delta;';
  html += '  if (mReportMonth < 1) { mReportMonth = 12; mReportYear--; }';
  html += '  else if (mReportMonth > 12) { mReportMonth = 1; mReportYear++; }';
  html += '  renderMonthlyReportContent();';
  html += '}';
  html += '';
  html += 'function resetReportMonthToCurrent() {';
  html += '  const now = new Date();';
  html += '  mReportYear = now.getFullYear();';
  html += '  mReportMonth = now.getMonth() + 1;';
  html += '  renderMonthlyReportContent();';
  html += '}';
  html += '';
  html += 'function switchMonthlyReportTab(tab) {';
  html += '  mReportTab = tab || "partner";';
  html += '  const tabs = { partner: "mRepTabPartner", manager: "mRepTabManager", site: "mRepTabSite" };';
  html += '  Object.keys(tabs).forEach(k => {';
  html += '    const btn = document.getElementById(tabs[k]);';
  html += '    if (!btn) return;';
  html += '    if (k === mReportTab) {';
  html += '      btn.style.background = "#2563eb";';
  html += '      btn.style.color = "#ffffff";';
  html += '      btn.style.fontWeight = "800";';
  html += '    } else {';
  html += '      btn.style.background = "transparent";';
  html += '      btn.style.color = "#475569";';
  html += '      btn.style.fontWeight = "700";';
  html += '    }';
  html += '  });';
  html += '  renderMonthlyReportContent();';
  html += '}';
  html += '';
  html += 'function setMonthlyReportScope(sc) {';
  html += '  mReportScope = sc || "all";';
  html += '  document.querySelectorAll(".mrep-scope-chip").forEach(btn => {';
  html += '    const active = (btn.dataset.scope === mReportScope);';
  html += '    btn.style.borderColor = active ? "#2563eb" : "#cbd5e1";';
  html += '    btn.style.background = active ? "#eff6ff" : "#ffffff";';
  html += '    btn.style.color = active ? "#1d4ed8" : "#475569";';
  html += '    btn.style.fontWeight = active ? "800" : "700";';
  html += '  });';
  html += '  renderMonthlyReportContent();';
  html += '}';
  html += '';
  html += 'function collectMonthlyReportData() {';
  html += '  const ym = mReportYear + "-" + (mReportMonth < 10 ? "0" + mReportMonth : mReportMonth);';
  html += '  const monthStart = ym + "-01";';
  html += '  const lastDay = new Date(mReportYear, mReportMonth, 0).getDate();';
  html += '  const monthEnd = ym + "-" + (lastDay < 10 ? "0" + lastDay : lastDay);';
  html += '  const sInp = document.getElementById("monthlyReportSearchInput");';
  html += '  const q = sInp ? String(sInp.value || "").trim().toLowerCase() : "";';
  html += '  const partnerMap = {};';
  html += '  const managerMap = {};';
  html += '  const siteMap = {};';
  html += '  let totalTasks = 0, doneTasks = 0, totalWorkDays = 0;';
  html += '  const activeSiteSet = {};';
  html += '  const activePartnerSet = {};';
  html += '  if (rawData && Array.isArray(rawData.sites)) {';
  html += '    rawData.sites.forEach(s => {';
  html += '      if (!s || s.scope === "newSite" || !Array.isArray(s.tasks)) return;';
  html += '      const sScope = s.scope || "site";';
  html += '      if (mReportScope !== "all" && sScope !== mReportScope) return;';
  html += '      s.tasks.forEach(t => {';
  html += '        if (!t || !t.startDateStr) return;';
  html += '        const stClean = String(t.status || "").replace(/\\s+/g, "");';
  html += '        if (stClean.indexOf("취소") !== -1) return;';
  html += '        const tStart = t.startDateStr;';
  html += '        const tEnd = t.endDateStr || tStart;';
  html += '        if (tStart > monthEnd || monthStart > tEnd) return;';
  html += '        const pName = String(t.partner || "").trim() || "(협력업체 미지정)";';
  html += '        const mNameRaw = String(t.manager || "").trim();';
  html += '        const tName = String(t.taskName || "").trim();';
  html += '        if (q) {';
  html += '          const hay = (s.siteName + " " + tName + " " + pName + " " + mNameRaw + " " + (t.memo || "")).toLowerCase();';
  html += '          if (hay.indexOf(q) === -1) return;';
  html += '        }';
  html += '        const cStart = tStart < monthStart ? monthStart : tStart;';
  html += '        const cEnd = tEnd > monthEnd ? monthEnd : tEnd;';
  html += '        const d1 = new Date(parseInt(cStart.slice(0,4),10), parseInt(cStart.slice(5,7),10)-1, parseInt(cStart.slice(8,10),10));';
  html += '        const d2 = new Date(parseInt(cEnd.slice(0,4),10), parseInt(cEnd.slice(5,7),10)-1, parseInt(cEnd.slice(8,10),10));';
  html += '        const days = Math.max(1, Math.round((d2.getTime() - d1.getTime()) / 86400000) + 1);';
  html += '        const isDone = stClean.indexOf("완료") !== -1;';
  html += '        const dLabel = (cStart === cEnd) ? cStart.slice(5) : (cStart.slice(5) + "~" + cEnd.slice(5));';
  html += '        totalTasks++;';
  html += '        if (isDone) doneTasks++;';
  html += '        totalWorkDays += days;';
  html += '        activeSiteSet[s.siteName] = true;';
  html += '        if (pName !== "(협력업체 미지정)") activePartnerSet[pName] = true;';
  html += '        if (!partnerMap[pName]) partnerMap[pName] = { name: pName, totalDays: 0, taskCount: 0, doneCount: 0, sites: {}, items: [] };';
  html += '        partnerMap[pName].totalDays += days;';
  html += '        partnerMap[pName].taskCount += 1;';
  html += '        if (isDone) partnerMap[pName].doneCount += 1;';
  html += '        partnerMap[pName].sites[s.siteName] = true;';
  html += '        partnerMap[pName].items.push({ siteName: s.siteName, taskName: tName, dateStr: dLabel, days: days, status: t.status || "예정", isDone: isDone });';
  html += '        const mParts = mNameRaw ? mNameRaw.split(/[,/]/).map(x => x.trim()).filter(Boolean) : ["(담당자 미지정)"];';
  html += '        mParts.forEach(m => {';
  html += '          if (!managerMap[m]) managerMap[m] = { name: m, totalDays: 0, taskCount: 0, doneCount: 0, delayCount: 0, sites: {}, items: [] };';
  html += '          managerMap[m].totalDays += days;';
  html += '          managerMap[m].taskCount += 1;';
  html += '          if (isDone) managerMap[m].doneCount += 1;';
  html += '          if (t.isDelayed) managerMap[m].delayCount += 1;';
  html += '          managerMap[m].sites[s.siteName] = true;';
  html += '          managerMap[m].items.push({ siteName: s.siteName, taskName: tName, dateStr: dLabel, days: days, partner: pName, isDone: isDone });';
  html += '        });';
  html += '        if (!siteMap[s.siteName]) siteMap[s.siteName] = { name: s.siteName, scope: sScope, totalDays: 0, taskCount: 0, doneCount: 0, partners: {}, items: [] };';
  html += '        siteMap[s.siteName].totalDays += days;';
  html += '        siteMap[s.siteName].taskCount += 1;';
  html += '        if (isDone) siteMap[s.siteName].doneCount += 1;';
  html += '        if (pName !== "(협력업체 미지정)") siteMap[s.siteName].partners[pName] = true;';
  html += '        siteMap[s.siteName].items.push({ taskName: tName, dateStr: dLabel, days: days, partner: pName, manager: mNameRaw, isDone: isDone });';
  html += '      });';
  html += '    });';
  html += '  }';
  html += '  return {';
  html += '    totalSites: Object.keys(activeSiteSet).length,';
  html += '    totalPartners: Object.keys(activePartnerSet).length,';
  html += '    totalTasks: totalTasks,';
  html += '    doneTasks: doneTasks,';
  html += '    totalWorkDays: totalWorkDays,';
  html += '    partners: Object.values(partnerMap).sort((a, b) => {';
  html += '      if (a.name === "(협력업체 미지정)") return 1;';
  html += '      if (b.name === "(협력업체 미지정)") return -1;';
  html += '      return (b.totalDays - a.totalDays) || (b.taskCount - a.taskCount);';
  html += '    }),';
  html += '    managers: Object.values(managerMap).sort((a, b) => {';
  html += '      if (a.name === "(담당자 미지정)") return 1;';
  html += '      if (b.name === "(담당자 미지정)") return -1;';
  html += '      return (b.taskCount - a.taskCount) || (b.totalDays - a.totalDays);';
  html += '    }),';
  html += '    sites: Object.values(siteMap).sort((a, b) => (b.taskCount - a.taskCount) || (b.totalDays - a.totalDays))';
  html += '  };';
  html += '}';
  html += '';
  html += 'function renderMonthlyReportContent() {';
  html += '  const lbl = document.getElementById("monthlyReportMonthLabel");';
