  html += '      \'<div style="background:#f8fafc;border:1px solid #e2e8f0;border-radius:8px;padding:7px 8px;text-align:center;"><div style="font-size:10px;color:#64748b;font-weight:700;">가동 현장</div><div style="font-size:15px;font-weight:900;color:#0f172a;margin-top:2px;">\' + data.totalSites + \'곳</div></div>\' +';
  html += '      \'<div style="background:#eff6ff;border:1px solid #bfdbfe;border-radius:8px;padding:7px 8px;text-align:center;"><div style="font-size:10px;color:#1d4ed8;font-weight:700;">투입 업체</div><div style="font-size:15px;font-weight:900;color:#1d4ed8;margin-top:2px;">\' + data.totalPartners + \'곳</div></div>\' +';
  html += '      \'<div style="background:#f0fdf4;border:1px solid #bbf7d0;border-radius:8px;padding:7px 8px;text-align:center;"><div style="font-size:10px;color:#15803d;font-weight:700;">총 공정 (일수)</div><div style="font-size:15px;font-weight:900;color:#15803d;margin-top:2px;">\' + data.totalTasks + \'건 (\' + data.totalWorkDays + \'일)</div></div>\' +';
  html += '      \'<div style="background:#fffbeb;border:1px solid #fde68a;border-radius:8px;padding:7px 8px;text-align:center;"><div style="font-size:10px;color:#b45309;font-weight:700;">월간 완료율</div><div style="font-size:15px;font-weight:900;color:#b45309;margin-top:2px;">\' + compRate + \'%</div></div>\';';
  html += '  }';
  html += '  if (data.totalTasks === 0) {';
  html += '    body.innerHTML = \'<div style="text-align:center;padding:36px 16px;color:#94a3b8;font-size:13px;font-weight:700;background:#ffffff;border-radius:10px;border:1px solid #e2e8f0;">📭 \' + mReportYear + \'년 \' + mReportMonth + \'월에 해당하는 공정 일정이 없습니다.</div>\';';
  html += '    return;';
