  html += '      const phone = !isUnassigned ? getPartnerPhoneNumber(p.name) : "";';
  html += '      const siteCnt = Object.keys(p.sites).length;';
  html += '      htmlOut += \'<div style="background:#ffffff;border:1px solid \' + (isUnassigned ? "#e2e8f0" : "#cbd5e1") + \';border-radius:10px;padding:10px 12px;box-shadow:0 1px 2px rgba(0,0,0,0.03);">\';';
  html += '      htmlOut += \'<div style="display:flex;align-items:center;justify-content:space-between;gap:8px;flex-wrap:wrap;margin-bottom:6px;">\';';
  html += '      htmlOut += \'<div style="display:flex;align-items:center;gap:6px;flex-wrap:wrap;">\';';
  html += '      htmlOut += \'<span style="font-size:13.5px;font-weight:900;color:\' + (isUnassigned ? "#64748b" : "#0f172a") + \';">\' + escapeHtml(p.name) + \'</span>\';';
  html += '      if (phone) htmlOut += \'<a href="tel:\' + escapeHtml(phone.replace(/[^0-9+]/g, "")) + \'" style="font-size:11px;color:#15803d;background:#dcfce7;padding:1px 6px;border-radius:5px;text-decoration:none;font-weight:700;">📞 \' + escapeHtml(phone) + \'</a>\';';
  html += '      htmlOut += \'</div>\';';
  html += '      htmlOut += \'<div style="display:flex;align-items:center;gap:5px;">\';';
  html += '      htmlOut += \'<span style="font-size:11.5px;font-weight:900;color:#1d4ed8;background:#eff6ff;border:1px solid #bfdbfe;padding:2px 8px;border-radius:6px;">총 \' + p.totalDays + \'일 투입 (\' + p.taskCount + \'건 · \' + siteCnt + \'개 현장)</span>\';';
  html += '      htmlOut += \'<button type="button" data-pname="\' + encodeURIComponent(p.name) + \'" onclick="copySinglePartnerReport(decodeURIComponent(this.dataset.pname))" style="border:1px solid #cbd5e1;background:#f8fafc;color:#334155;border-radius:5px;padding:2px 7px;font-size:10.5px;font-weight:800;cursor:pointer;" title="이 업체의 월간 투입 내역만 복사">📋 복사</button>\';';
  html += '      htmlOut += \'</div></div>\';';
  html += '      htmlOut += \'<div style="display:flex;flex-wrap:wrap;gap:5px;">\';';
  html += '      p.items.forEach(it => {';
  html += '        const bg = it.isDone ? "#f0fdf4" : "#f8fafc";';
  html += '        const bd = it.isDone ? "#bbf7d0" : "#e2e8f0";';
  html += '        htmlOut += \'<span style="font-size:11px;background:\' + bg + \';border:1px solid \' + bd + \';border-radius:6px;padding:3px 7px;color:#334155;"><b>[\' + escapeHtml(it.siteName) + \']</b> \' + escapeHtml(it.taskName) + \' <span style="color:#2563eb;font-weight:700;">(\' + escapeHtml(it.dateStr) + (it.days > 1 ? " · " + it.days + "일" : "") + \')</span>\' + (it.isDone ? " ✅" : "") + \'</span>\';';
  html += '      });';
  html += '      htmlOut += \'</div></div>\';';
  html += '    });';
  html += '  } else if (mReportTab === "manager") {';
  html += '    data.managers.forEach(m => {';
  html += '      const siteCnt = Object.keys(m.sites).length;';
  html += '      const mRate = m.taskCount > 0 ? Math.round((m.doneCount / m.taskCount) * 100) : 0;';
  html += '      htmlOut += \'<div style="background:#ffffff;border:1px solid #cbd5e1;border-radius:10px;padding:10px 12px;">\';';
  html += '      htmlOut += \'<div style="display:flex;align-items:center;justify-content:space-between;gap:8px;flex-wrap:wrap;margin-bottom:6px;">\';';
  html += '      htmlOut += \'<span style="font-size:13.5px;font-weight:900;color:#0f172a;">👤 \' + escapeHtml(m.name) + \'</span>\';';
  html += '      htmlOut += \'<div style="display:flex;align-items:center;gap:5px;font-size:11px;font-weight:800;">\';';
  html += '      htmlOut += \'<span style="background:#eff6ff;color:#1d4ed8;padding:2px 7px;border-radius:6px;">담당 현장 \' + siteCnt + \'곳</span>\';';
  html += '      htmlOut += \'<span style="background:#f0fdf4;color:#15803d;padding:2px 7px;border-radius:6px;">공정 \' + m.taskCount + \'건 (완료 \' + mRate + \'%)</span>\';';
  html += '      if (m.delayCount > 0) htmlOut += \'<span style="background:#fef2f2;color:#dc2626;padding:2px 7px;border-radius:6px;">⚠️ 지연 \' + m.delayCount + \'건</span>\';';
  html += '      htmlOut += \'</div></div>\';';
  html += '      htmlOut += \'<div style="font-size:11px;color:#475569;line-height:1.5;"><b>참여 현장:</b> \' + Object.keys(m.sites).map(s => escapeHtml(s)).join(", ") + \'</div>\';';
  html += '      htmlOut += \'</div>\';';
  html += '    });';
  html += '  } else {';
  html += '    data.sites.forEach(s => {';
  html += '      const sRate = s.taskCount > 0 ? Math.round((s.doneCount / s.taskCount) * 100) : 0;';
  html += '      const pList = Object.keys(s.partners);';
  html += '      htmlOut += \'<div style="background:#ffffff;border:1px solid #cbd5e1;border-radius:10px;padding:10px 12px;">\';';
  html += '      htmlOut += \'<div style="display:flex;align-items:center;justify-content:space-between;gap:8px;flex-wrap:wrap;margin-bottom:5px;">\';';
  html += '      htmlOut += \'<span style="font-size:13.5px;font-weight:900;color:#0f172a;">🏗️ \' + escapeHtml(s.name) + \'</span>\';';
  html += '      htmlOut += \'<span style="font-size:11.5px;font-weight:800;color:#1d4ed8;background:#eff6ff;padding:2px 8px;border-radius:6px;">이달 공정 \' + s.taskCount + \'건 (총 \' + s.totalDays + \'일 · 완료 \' + sRate + \'%)</span>\';';
  html += '      htmlOut += \'</div>\';';
  html += '      if (pList.length > 0) htmlOut += \'<div style="font-size:11px;color:#475569;margin-bottom:5px;"><b>투입 업체(\' + pList.length + \'곳):</b> \' + pList.map(p => escapeHtml(p)).join(", ") + \'</div>\';';
  html += '      htmlOut += \'<div style="display:flex;flex-wrap:wrap;gap:4px;">\';';
  html += '      s.items.forEach(it => {';
  html += '        htmlOut += \'<span style="font-size:10.5px;background:#f8fafc;border:1px solid #e2e8f0;border-radius:5px;padding:2px 6px;color:#334155;">\' + escapeHtml(it.taskName) + \' (\' + escapeHtml(it.dateStr) + \')\' + (it.isDone ? " ✅" : "") + \'</span>\';';
  html += '      });';
  html += '      htmlOut += \'</div></div>\';';
  html += '    });';
  html += '  }';
  html += '  body.innerHTML = htmlOut;';
  html += '}';
  html += '';
  html += 'function copySinglePartnerReport(partnerName) {';
  html += '  const data = collectMonthlyReportData();';
  html += '  const p = data.partners.find(x => x.name === partnerName);';
  html += '  if (!p) return;';
  html += '  let lines = ["[우성아이디 " + mReportYear + "년 " + mReportMonth + "월 투입 내역 - " + p.name + "]"];';
  html += '  lines.push("■ 총 투입: " + p.totalDays + "일 (" + p.taskCount + "건 / " + Object.keys(p.sites).length + "개 현장)");';
  html += '  p.items.forEach((it, idx) => {';
  html += '    lines.push((idx + 1) + ". [" + it.siteName + "] " + it.taskName + " (" + it.dateStr + ", " + it.days + "일) - " + it.status);';
  html += '  });';
  html += '  copyTextToClipboard(lines.join("\\n"), "📋 [" + p.name + "] 월간 투입 내역이 복사되었습니다!");';
  html += '}';
  html += '';
  html += 'function copyMonthlyReportSummary() {';
  html += '  const data = collectMonthlyReportData();';
  html += '  let lines = ["📊 [우성아이디 " + mReportYear + "년 " + mReportMonth + "월 가동 리포트]"];';
  html += '  lines.push("• 가동 현장: " + data.totalSites + "곳 | 투입 업체: " + data.totalPartners + "곳 | 총 공정: " + data.totalTasks + "건(" + data.totalWorkDays + "일)");';
  html += '  lines.push("----------------------------------------");';
  html += '  if (mReportTab === "partner") {';
  html += '    data.partners.forEach(p => {';
  html += '      const detail = p.items.map(it => "[" + it.siteName + "]" + it.taskName + "(" + it.dateStr + ")").join(", ");';
  html += '      lines.push("■ " + p.name + " : 총 " + p.totalDays + "일 (" + p.taskCount + "건) ➔ " + detail);';
  html += '    });';
  html += '  } else if (mReportTab === "manager") {';
  html += '    data.managers.forEach(m => {';
  html += '      lines.push("■ " + m.name + " : 담당 현장 " + Object.keys(m.sites).length + "곳 / 공정 " + m.taskCount + "건 (완료 " + m.doneCount + "건)");';
  html += '    });';
  html += '  } else {';
  html += '    data.sites.forEach(s => {';
  html += '      lines.push("■ " + s.name + " : 공정 " + s.taskCount + "건 (총 " + s.totalDays + "일 / 완료 " + s.doneCount + "건)");';
  html += '    });';
  html += '  }';
  html += '  copyTextToClipboard(lines.join("\\n"), "📋 " + mReportYear + "년 " + mReportMonth + "월 리포트 전체 내역이 복사되었습니다!");';
  html += '}';
  html += '';
  html += 'function populateDetailTaskSelectOptions(tasks, currentTaskName) {';
  html += '  const sel = document.getElementById("sheetDetailTaskSelect");';
  html += '  const custom = document.getElementById("sheetDetailTaskCustomInput");';
  html += '  if (!sel) return;';
  html += '  sel.innerHTML = \'<option value="">공종을 선택하세요</option>\';';
  html += '  const defaultTasks = [';
  html += '    "철거", "설비", "누수보수", "전기", "전기입선", "전기마감", "조명", "에어컨",';
  html += '    "목공", "도어설치", "중문", "창호", "창호실측", "타일", "줄눈", "도기", "SMC",';
  html += '    "필름", "도장", "도배", "마루", "바닥", "가구", "주방", "보양", "청소", "마감",';
  html += '    "상담", "현장실측", "AS"';
  html += '  ];';
  html += '  const allTasks = [];';
  html += '  const seen = {};';
  html += '  (tasks && tasks.length > 0 ? tasks : defaultTasks).forEach(t => {';
  html += '    const name = String(t || "").trim();';
  html += '    if (name && !seen[name]) {';
  html += '      seen[name] = true;';
  html += '      allTasks.push(name);';
  html += '    }';
  html += '  });';
  html += '  allTasks.forEach(t => {';
  html += '    const opt = document.createElement("option");';
  html += '    opt.value = t;';
  html += '    opt.innerText = t;';
  html += '    sel.appendChild(opt);';
  html += '  });';
  html += '  const cur = String(currentTaskName || "").trim();';
  html += '  let found = false;';
  html += '  for (let i = 0; i < sel.options.length; i++) {';
  html += '    if (sel.options[i].value === cur) { found = true; break; }';
  html += '  }';
  html += '  if (cur && found) {';
  html += '    sel.value = cur;';
  html += '  } else if (cur) {';
  html += '    const extraOpt = document.createElement("option");';
  html += '    extraOpt.value = cur;';
  html += '    extraOpt.innerText = cur;';
  html += '    sel.appendChild(extraOpt);';
  html += '    sel.value = cur;';
  html += '  } else {';
  html += '    sel.value = "";';
  html += '  }';
  html += '  if (custom) { custom.value = ""; custom.style.display = "none"; }';
  html += '}';
  html += '';
  html += 'function startDetailTaskEdit() {';
  html += '  const curName = (curTaskObj && curTaskObj.taskName) || (document.getElementById("sheetTaskName") ? document.getElementById("sheetTaskName").innerText : "") || "";';
  html += '  populateDetailTaskSelectOptions(rawData ? rawData.tasks : [], curName);';
  html += '  const disp = document.getElementById("sheetTaskDisplayWrap");';
  html += '  const editWrap = document.getElementById("sheetTaskEditWrap");';
  html += '  if (disp) disp.style.display = "none";';
  html += '  if (editWrap) {';
  html += '    editWrap.style.display = "flex";';
  html += '    const sel = document.getElementById("sheetDetailTaskSelect");';
  html += '    if (sel) sel.focus();';
  html += '  }';
  html += '}';
  html += '';
