  html += '';
  html += 'function openWideModalView() {';
  html += '  if (typeof google !== "undefined" && google.script && google.script.run) {';
  html += '    google.script.run.openSiteScheduleModal();';
  html += '  }';
  html += '}';
  html += '';
  html += 'function goToCurrentTaskSheetRow() {';
  html += '  if (!curTaskObj || !curTaskObj.row) {';
  html += '    showToast("⚠️ 이동할 시트 행 정보가 없습니다.");';
  html += '    return;';
  html += '  }';
  html += '  const targetRow = curTaskObj.row;';
  html += '  const isArch = !!curTaskObj.isArchived;';
  html += '  const siteStr = curSiteName || "";';
  html += '  const taskStr = (curTaskObj && curTaskObj.taskName) || "";';
  html += '  const dateInputEl = document.getElementById("sheetDateInput");';
  html += '  const dateStr = (dateInputEl && dateInputEl.value) ? dateInputEl.value.trim() : ((curTaskObj && (curTaskObj.dateDisplay || curTaskObj.startDateStr)) || "");';
  html += '  const targetSheetNameForFocus = (curTaskObj && curTaskObj.sheetName) ? curTaskObj.sheetName : (isArch ? "완료현장" : "현장데이터");';
  html += '  showToast("📍 [" + (siteStr || "현장") + " - " + (taskStr || "공정") + "] 시트 행 위치로 이동 중...");';
  html += '  google.script.run';
  html += '    .withSuccessHandler(res => {';
  html += '      const actualRow = (res && res.row) ? res.row : targetRow;';
  html += '      if (curTaskObj) curTaskObj.row = actualRow;';
  html += '      if (actualRow !== targetRow) {';
  html += '        loadDataSilently();';
  html += '      }';
  html += '      showToast("✅ [" + (siteStr || "현장") + " - " + (taskStr || "공정") + "] " + actualRow + "행으로 이동했습니다!");';
  html += '      if (res && res.sheetUrl && isMobileMode) {';
  html += '        window.open(res.sheetUrl, "_blank");';
  html += '      }';
  html += '    })';
  html += '    .withFailureHandler(err => {';
  html += '      showToast("⚠️ 이동 실패: " + ((err && err.message) || err));';
  html += '    })';
  html += '    .focusSheetRow(targetRow, isArch, siteStr, taskStr, dateStr);';
  html += '}';
  html += '';
  html += 'let isCreateMode = false;';
  html += 'let isSheetModalHistoryActive = false;';
  html += 'let ignoreNextSheetPopstate = false;';
  html += 'let hasTopHistoryBridge = false;';
  html += '';
  html += 'function isBottomSheetVisible() {';
  html += '  const overlayEl = document.getElementById("sheetOverlay");';
  html += '  return Boolean(overlayEl && overlayEl.classList.contains("show"));';
  html += '}';
  html += '';
  html += 'function closeBottomSheetFromBack() {';
  html += '  if (typeof flushQuickShareSync === "function") flushQuickShareSync();';
  html += '  isSheetModalHistoryActive = false;';
  html += '  closeCustomDatePicker();';
  html += '  const overlayEl = document.getElementById("sheetOverlay");';
  html += '  if (overlayEl) overlayEl.classList.remove("show");';
  html += '  isCreateMode = false;';
  html += '  curEstimateEditSite = null;';
  html += '  const catRow = document.getElementById("sheetCategorySelectRow");';
  html += '  if (catRow) catRow.style.display = "block";';
  html += '}';
  html += '';
  html += 'function pushBottomSheetHistoryState() {';
  html += '  if (isSheetModalHistoryActive) return;';
  html += '  isSheetModalHistoryActive = true;';
  html += '  if (hasTopHistoryBridge) {';
  html += '    try {';
  html += '      window.top.postMessage({ type: "ORCA_SHEET_MODAL_OPEN" }, "*");';
  html += '      return;';
  html += '    } catch (ePostOpen) {}';
  html += '  }';
  html += '  try {';
  html += '    if (window.top && window.top !== window) {';
  html += '      window.top.postMessage({ type: "ORCA_SHEET_MODAL_OPEN" }, "*");';
  html += '    }';
  html += '  } catch (eTopOpen) {}';
  html += '  try {';
  html += '    if (window.history && typeof window.history.pushState === "function") {';
  html += '      window.history.pushState({ orcaSheetModal: true }, "");';
  html += '    }';
  html += '  } catch (ePush) {}';
  html += '}';
  html += '';
  html += 'function popBottomSheetHistoryStateIfNeeded() {';
  html += '  if (!isSheetModalHistoryActive) return;';
  html += '  isSheetModalHistoryActive = false;';
  html += '  if (hasTopHistoryBridge) {';
  html += '    try {';
  html += '      window.top.postMessage({ type: "ORCA_SHEET_MODAL_CLOSED_BY_UI" }, "*");';
  html += '      return;';
  html += '    } catch (ePostClose) {}';
  html += '  }';
  html += '  try {';
  html += '    if (window.top && window.top !== window) {';
  html += '      window.top.postMessage({ type: "ORCA_SHEET_MODAL_CLOSED_BY_UI" }, "*");';
  html += '    }';
  html += '  } catch (eTopClose) {}';
  html += '  try {';
  html += '    if (window.history && typeof window.history.back === "function") {';
  html += '      ignoreNextSheetPopstate = true;';
  html += '      window.history.back();';
  html += '    }';
  html += '  } catch (eBack) {}';
  html += '}';
  html += '';
  html += 'window.addEventListener("popstate", function() {';
  html += '  if (ignoreNextSheetPopstate) {';
  html += '    ignoreNextSheetPopstate = false;';
  html += '    return;';
  html += '  }';
  html += '  if (isBottomSheetVisible() || isSheetModalHistoryActive) {';
  html += '    closeBottomSheetFromBack();';
  html += '    return;';
  html += '  }';
  html += '  if (!hasTopHistoryBridge) {';
  html += '    var doExit = confirm("우성아이디 대시보드를 종료하시겠습니까?");';
  html += '    if (doExit) {';
  html += '      window.close();';
  html += '    } else {';
  html += '      try { window.history.pushState({ page: "home" }, ""); } catch(eStay) {}';
  html += '    }';
  html += '  }';
  html += '});';
  html += '';
  html += 'window.addEventListener("message", function(ev) {';
  html += '  const data = ev && ev.data;';
  html += '  if (!data || typeof data !== "object") return;';
  html += '  if (data.type === "ORCA_BRIDGE_PONG") {';
  html += '    hasTopHistoryBridge = true;';
  html += '  } else if (data.type === "ORCA_BACK_BUTTON") {';
  html += '    if (isBottomSheetVisible() || isSheetModalHistoryActive) {';
  html += '      closeBottomSheetFromBack();';
  html += '    }';
  html += '  } else if (data.type === "ORCA_ESCAPE_KEY") {';
  html += '    if (typeof handleGlobalEscape === "function") {';
  html += '      handleGlobalEscape();';
  html += '    }';
  html += '  }';
  html += '});';
  html += 'try {';
  html += '  if (window.top && window.top !== window) {';
  html += '    window.top.postMessage({ type: "ORCA_BRIDGE_PING" }, "*");';
  html += '  }';
  html += '} catch (eInitPing) {}';
  html += '';
  html += 'function findSiteDefaultManager(siteName) {';
  html += '  if (!siteName || !rawData || !Array.isArray(rawData.sites)) return "";';
  html += '  const sObj = rawData.sites.find(s => s && s.siteName === siteName && !s.isArchived);';
  html += '  if (!sObj || !Array.isArray(sObj.tasks)) return "";';
  html += '  for (let i = 0; i < sObj.tasks.length; i++) {';
  html += '    const m = String((sObj.tasks[i] && sObj.tasks[i].manager) || "").trim();';
  html += '    if (m && m !== "김종혁" && m !== "영하") return m;';
  html += '  }';
  html += '  return "";';
  html += '}';
  html += '';
  html += 'function updateSheetModalSiteInfo(siteName) {';
  html += '  const sInfoBanner = document.getElementById("sheetSiteInfoBanner");';
  html += '  if (!sInfoBanner) return;';
  html += '  if (curEstimateEditSite) { sInfoBanner.style.display = "none"; sInfoBanner.innerHTML = ""; return; }';
  html += '  const cleanVal = String(siteName || "").trim();';
  html += '  if (!cleanVal) { sInfoBanner.style.display = "none"; return; }';
  html += '  const sInfo = getSiteInfoFromMap(cleanVal);';
  html += '  if (sInfo && (sInfo.address || sInfo.doorPassword || sInfo.officePhone || sInfo.memo)) {';
  html += '    let bHtml = \'<div style="display:flex;align-items:center;justify-content:space-between;gap:6px;flex-wrap:wrap;">\';';
  html += '    bHtml += \'<div style="display:flex;align-items:center;gap:8px;flex-wrap:wrap;font-size:11px;">\';';
  html += '    if (sInfo.address) bHtml += \'<span style="display:inline-flex;align-items:center;gap:4px;cursor:pointer;" data-addr="\' + encodeURIComponent(sInfo.address) + \'" onclick="event.stopPropagation();copyTextToClipboard(decodeURIComponent(this.dataset.addr), \\\'현장 주소가 복사되었습니다!\\\')" title="터치하여 현장 주소 복사">📍 <strong>\' + escapeHtml(sInfo.address) + \'</strong> <span style="font-size:9.5px;color:#2563eb;background:#eff6ff;padding:0.5px 4px;border-radius:3px;border:1px solid #bfdbfe;">복사</span></span><button type="button" style="border:1px solid #fde047;background:#fef9c3;color:#854d0e;border-radius:4px;padding:1px 5px;font-size:10px;font-weight:800;cursor:pointer;" data-addr="\' + encodeURIComponent(sInfo.address) + \'" onclick="event.stopPropagation();openMobileMapNavigation(decodeURIComponent(this.dataset.addr))" title="길안내 실행">🚗길안내</button>\';';
  html += '    if (sInfo.doorPassword) bHtml += \'<span style="display:inline-flex;align-items:center;gap:3px;cursor:pointer;background:#eff6ff;padding:1px 6px;border-radius:4px;border:1px solid #bfdbfe;" data-pwd="\' + encodeURIComponent(sInfo.doorPassword) + \'" onclick="event.stopPropagation();copyTextToClipboard(decodeURIComponent(this.dataset.pwd), \\\'도어락 비밀번호가 복사되었습니다!\\\')" title="터치하여 도어락 비밀번호 복사">🔑 비번: <strong style="color:#2563eb;">\' + escapeHtml(sInfo.doorPassword) + \'</strong> <span style="font-size:9.5px;color:#2563eb;font-weight:700;">복사</span></span>\';';
  html += '    if (sInfo.officePhone) bHtml += \'<span>📞 <a href="tel:\' + escapeHtml(sInfo.officePhone) + \'" style="color:#0f172a;text-decoration:none;font-weight:700;" onclick="event.stopPropagation()">\' + escapeHtml(sInfo.officePhone) + \'</a></span>\';';
  html += '    bHtml += \'</div>\';';
  html += '    bHtml += \'<button type="button" class="btn-site-info-edit" style="padding:2px 7px;font-size:10.5px;" data-site="\' + encodeURIComponent(cleanVal) + \'" onclick="openSiteInfoEditModal(decodeURIComponent(this.dataset.site), event)">✏️ 수정</button>\';';
  html += '    bHtml += \'</div>\';';
  html += '    if (sInfo.memo) {';
  html += '      bHtml += \'<div style="margin-top:3px;font-size:11px;color:#9f1239;background:#fff1f2;border:1px solid #fecdd3;border-radius:5px;padding:3px 7px;">⚠️ \' + escapeHtml(sInfo.memo) + \'</div>\';';
  html += '    }';
  html += '    sInfoBanner.innerHTML = bHtml;';
  html += '    sInfoBanner.style.display = "block";';
  html += '  } else {';
  html += '    sInfoBanner.innerHTML = \'<div style="display:flex;align-items:center;justify-content:space-between;gap:6px;font-size:11px;color:#94a3b8;"><span>📍 현장 정보(주소/비번) 미등록</span><button type="button" class="btn-site-info-edit" style="padding:2px 7px;font-size:10.5px;" data-site="\' + encodeURIComponent(cleanVal) + \'" onclick="openSiteInfoEditModal(decodeURIComponent(this.dataset.site), event)">+ 등록</button></div>\';';
  html += '    sInfoBanner.style.display = "block";';
  html += '  }';
  html += '}';
  html += '';
  html += 'function populateSiteSelectOptions(prefillSite, filterScope) {';
  html += '  const sel = document.getElementById("sheetSiteSelect");';
  html += '  if (!sel) return;';
  html += '  const customInp = document.getElementById("sheetSiteCustomInput");';
  html += '  const autoBadge = document.getElementById("sheetCategoryAutoBadge");';
  html += '  let curScope = filterScope;';
  html += '  if (!curScope) {';
  html += '    const catRadio = (typeof document !== "undefined" && typeof document.querySelector === "function")';
  html += '      ? document.querySelector(\'input[name="sheetCategory"]:checked\') : null;';
  html += '    curScope = catRadio ? catRadio.value : (currentScope || "site");';
  html += '  }';
  html += '  let optsHtml = \'<option value="">현장을 선택하세요</option>\';';
  html += '  const matchingSites = [];';
  html += '  const otherSites = [];';
  html += '  if (rawData && Array.isArray(rawData.sites)) {';
  html += '    rawData.sites.forEach(s => {';
  html += '      if (!s || !s.siteName || s.scope === "newSite") return;';
  html += '      const isPrefilledTarget = Boolean(prefillSite && s.siteName === prefillSite);';
  html += '      if (!isPrefilledTarget) {';
  html += '        if (s.isArchived || s.isAllCompleted) return;';
  html += '        const tasks = Array.isArray(s.tasks) ? s.tasks : [];';
  html += '        if (tasks.length > 0) {';
  html += '          const hasActive = tasks.some(t => {';
  html += '            const st = String((t && t.status) || "").replace(/\\s+/g, "");';
  html += '            return st.indexOf("완료") === -1 && st.indexOf("취소") === -1;';
  html += '          });';
  html += '          if (!hasActive) return;';
  html += '        }';
  html += '      }';
  html += '      const sScope = s.scope || "site";';
  html += '      if (curScope === "all" || sScope === curScope || isPrefilledTarget) {';
  html += '        if (matchingSites.indexOf(s.siteName) === -1) matchingSites.push(s.siteName);';
  html += '      } else {';
  html += '        if (otherSites.indexOf(s.siteName) === -1) otherSites.push(s.siteName);';
  html += '      }';
  html += '    });';
  html += '  }';
  html += '  matchingSites.sort();';
  html += '  matchingSites.forEach(name => {';
  html += '    optsHtml += \'<option value="\' + escapeHtml(name) + \'">\' + escapeHtml(name) + \'</option>\';';
  html += '  });';
  html += '  if (otherSites.length > 0) {';
  html += '    otherSites.sort();';
  html += '    optsHtml += \'<optgroup label="── 다른 분류 현장 ──">\';';
  html += '    otherSites.forEach(name => {';
  html += '      optsHtml += \'<option value="\' + escapeHtml(name) + \'">\' + escapeHtml(name) + \'</option>\';';
  html += '    });';
  html += '    optsHtml += \'</optgroup>\';';
  html += '  }';
  html += '  optsHtml += \'<option value="__CUSTOM__">➕ 새 현장 직접 입력...</option>\';';
  html += '  sel.innerHTML = optsHtml;';
  html += '  if (prefillSite) {';
  html += '    let exists = false;';
  html += '    if (sel.options && sel.options.length > 0) {';
  html += '      for (let i = 0; i < sel.options.length; i++) {';
  html += '        if (sel.options[i].value === prefillSite) { exists = true; break; }';
  html += '      }';
  html += '    } else if (matchingSites.indexOf(prefillSite) !== -1 || otherSites.indexOf(prefillSite) !== -1) {';
  html += '      exists = true;';
  html += '    }';
  html += '    if (exists) {';
  html += '      sel.value = prefillSite;';
  html += '      if (customInp) { customInp.style.display = "none"; customInp.value = ""; }';
  html += '    } else {';
  html += '      sel.value = "__CUSTOM__";';
  html += '      if (customInp) {';
  html += '        customInp.value = prefillSite;';
  html += '        customInp.style.display = "block";';
  html += '      }';
  html += '    }';
  html += '  } else {';
  html += '    sel.value = "";';
  html += '    if (customInp) { customInp.style.display = "none"; customInp.value = ""; }';
  html += '    if (autoBadge) autoBadge.style.display = "none";';
  html += '  }';
  html += '}';
  html += '';
  html += 'function onSheetSiteChange(siteVal) {';
  html += '  const customInp = document.getElementById("sheetSiteCustomInput");';
  html += '  const autoBadge = document.getElementById("sheetCategoryAutoBadge");';
  html += '  if (siteVal === "__CUSTOM__") {';
  html += '    if (customInp) {';
  html += '      customInp.style.display = "block";';
  html += '      customInp.value = "";';
  html += '      customInp.focus();';
  html += '    }';
  html += '    if (autoBadge) autoBadge.style.display = "none";';
  html += '    updateSheetModalSiteInfo("");';
  html += '    return;';
  html += '  }';
  html += '  if (customInp) {';
  html += '    customInp.style.display = "none";';
  html += '    customInp.value = "";';
  html += '  }';
  html += '  if (!siteVal) {';
  html += '    if (autoBadge) autoBadge.style.display = "none";';
  html += '    updateSheetModalSiteInfo("");';
  html += '    return;';
  html += '  }';
  html += '  let detectedScope = "";';
  html += '  if (rawData && Array.isArray(rawData.sites)) {';
  html += '    const detectedSite = rawData.sites.find(s => s.siteName === siteVal);';
  html += '    if (detectedSite) {';
  html += '      detectedScope = detectedSite.scope || "site";';
  html += '    }';
  html += '  }';
  html += '  if (detectedScope) {';
  html += '    const targetRadio = document.querySelector(\'input[name="sheetCategory"][value="\' + detectedScope + \'"]\');';
  html += '    if (targetRadio) {';
  html += '      targetRadio.checked = true;';
  html += '      if (autoBadge) {';
  html += '        const scopeLabel = (detectedScope === "single") ? "단건" : ((detectedScope === "as") ? "AS" : "종합현장");';
  html += '        autoBadge.innerText = "✨ " + scopeLabel + " 자동 감지";';
  html += '        autoBadge.style.display = "inline-block";';
  html += '        setTimeout(() => {';
  html += '          if (autoBadge) autoBadge.style.display = "none";';
  html += '        }, 3500);';
  html += '      }';
  html += '    }';
  html += '  } else {';
  html += '    if (autoBadge) autoBadge.style.display = "none";';
  html += '  }';
  html += '  updateSheetModalSiteInfo(siteVal);';
  html += '  const taskNameEl = document.getElementById("sheetTaskName");';
  html += '  if (taskNameEl && isCreateMode) {';
  html += '    taskNameEl.innerText = siteVal ? ("현장: " + siteVal) : "현장·공종·날짜를 입력해 등록하세요";';
  html += '  }';
  html += '  const siteMgr = findSiteDefaultManager(siteVal);';
  html += '  const mgrSelect = document.getElementById("sheetManagerSelect");';
  html += '  const mgrCustom = document.getElementById("sheetManagerCustomInput");';
  html += '  if (siteMgr && mgrSelect) {';
  html += '    populateManagerSelectOptions(rawData ? rawData.members : []);';
  html += '    let found = false;';
  html += '    for (let i = 0; i < mgrSelect.options.length; i++) {';
  html += '      if (mgrSelect.options[i].value === siteMgr) { found = true; break; }';
  html += '    }';
  html += '    if (found) {';
  html += '      mgrSelect.value = siteMgr;';
  html += '      if (mgrCustom) { mgrCustom.value = ""; mgrCustom.style.display = "none"; }';
  html += '    }';
  html += '  }';
  html += '  checkSheetScheduleConflicts();';
  html += '}';
  html += '';
  html += 'function onSheetSiteCustomInput(customVal) {';
  html += '  updateSheetModalSiteInfo(customVal);';
  html += '  checkSheetScheduleConflicts();';
  html += '}';
  html += '';
  html += 'function onSheetCategoryChange(cat) {';
  html += '  const autoBadge = document.getElementById("sheetCategoryAutoBadge");';
  html += '  if (autoBadge) autoBadge.style.display = "none";';
  html += '  const regularCreate = document.getElementById("sheetRegularCreateFields");';
  html += '  const newSiteBox = document.getElementById("sheetNewSiteBox");';
  html += '  const editBox = document.getElementById("sheetEditBox");';
  html += '  const statusWrap = document.getElementById("sheetStatusSecWrap");';
  html += '  const shareWrap = document.getElementById("sheetShareSecWrap");';
  html += '  const memoWrap = document.getElementById("sheetMemoSecWrap");';
  html += '  const siteNameEl = document.getElementById("sheetSiteName");';
  html += '  const taskNameEl = document.getElementById("sheetTaskName");';
  html += '  const saveBtn = document.getElementById("sheetSaveBtn");';
  html += '';
  html += '  if (cat === "newSite") {';
  html += '    if (regularCreate) regularCreate.style.display = "none";';
  html += '    if (newSiteBox) newSiteBox.style.display = "block";';
  html += '    if (editBox) editBox.style.display = "none";';
  html += '    if (statusWrap) statusWrap.style.display = "none";';
  html += '    if (shareWrap) shareWrap.style.display = "none";';
  html += '    if (memoWrap) memoWrap.style.display = "none";';
  html += '    if (siteNameEl) siteNameEl.innerText = "📋 새 신규현장 견적 등록";';
  html += '    if (taskNameEl) taskNameEl.innerText = "신규 문의/견적 정보를 입력하세요";';
  html += '    if (saveBtn) saveBtn.innerText = "💾 신규현장 저장하기";';
  html += '    const inqInput = document.getElementById("sheetNewSiteInquiryDateInput");';
  html += '    if (inqInput && !inqInput.value) {';
  html += '      const now = new Date();';
  html += '      const y = now.getFullYear(), m = now.getMonth() + 1, d = now.getDate();';
  html += '      inqInput.value = y + "-" + (m < 10 ? "0" + m : m) + "-" + (d < 10 ? "0" + d : d);';
  html += '    }';
  html += '    const mgrSel = document.getElementById("sheetNewSiteManagerSelect");';
  html += '    if (mgrSel && rawData && Array.isArray(rawData.members) && rawData.members.length > 0) {';
  html += '      const curMgr = mgrSel.value || "조항만";';
  html += '      let mHtml = "";';
  html += '      rawData.members.forEach(m => {';
  html += '        if (!m || m === "김종혁" || m === "영하") return;';
  html += '        mHtml += \'<option value="\' + escapeHtml(m) + \'"\' + (m === curMgr ? " selected" : "") + \'>\' + escapeHtml(m) + \'</option>\';';
  html += '      });';
  html += '      mgrSel.innerHTML = mHtml;';
  html += '      if (!mgrSel.value && mgrSel.options.length > 0) mgrSel.selectedIndex = 0;';
  html += '    }';
  html += '  } else {';
  html += '    if (regularCreate) regularCreate.style.display = "block";';
  html += '    if (newSiteBox) newSiteBox.style.display = "none";';
  html += '    if (editBox) editBox.style.display = "block";';
  html += '    if (statusWrap) statusWrap.style.display = "block";';
  html += '    if (shareWrap) shareWrap.style.display = "block";';
  html += '    if (memoWrap) memoWrap.style.display = "block";';
  html += '    if (siteNameEl) siteNameEl.innerText = "➕ 새 공정 일정 등록";';
  html += '    if (taskNameEl) taskNameEl.innerText = curSiteName ? ("현장: " + curSiteName) : "현장·공종·날짜를 입력해 등록하세요";';
  html += '    if (saveBtn) saveBtn.innerText = "➕ 일정 등록하기";';
  html += '    const sel = document.getElementById("sheetSiteSelect");';
  html += '    const curVal = sel ? sel.value : "";';
  html += '    const customInp = document.getElementById("sheetSiteCustomInput");';
  html += '    const customVal = customInp ? customInp.value : "";';
  html += '    const effectiveSite = (curVal === "__CUSTOM__") ? (customVal || "__CUSTOM__") : (curVal || curSiteName || "");';
  html += '    populateSiteSelectOptions(effectiveSite === "__CUSTOM__" ? "" : effectiveSite, cat);';
  html += '    if (effectiveSite === "__CUSTOM__") {';
  html += '      if (sel) sel.value = "__CUSTOM__";';
  html += '      if (customInp) { customInp.style.display = "block"; customInp.value = customVal; }';
  html += '    }';
  html += '  }';
  html += '}';
  html += '';
  html += 'function pickQuickTaskName(name) {';
  html += '  const sel = document.getElementById("sheetTaskSelect");';
  html += '  if (sel) sel.value = name;';
  html += '  const inp = document.getElementById("sheetTaskInput");';
  html += '  if (inp) inp.value = name;';
  html += '  if (name === "AS") selectSheetStatus("AS");';
  html += '}';
  html += '';
  html += 'function openEditEstimateModal(siteNameOrEnc) {';
  html += '  if (!siteNameOrEnc) return;';
  html += '  const siteName = (siteNameOrEnc.indexOf("%") !== -1) ? decodeURIComponent(siteNameOrEnc) : siteNameOrEnc;';
  html += '  if (!rawData || !Array.isArray(rawData.sites)) return;';
  html += '  const siteObj = rawData.sites.find(s => (s.scope || "site") === "newSite" && s.siteName === siteName) || rawData.sites.find(s => s.siteName === siteName);';
  html += '  if (!siteObj) {';
  html += '    showToast("⚠️ 신규현장 정보를 찾을 수 없습니다: " + siteName);';
  html += '    return;';
  html += '  }';
  html += '  curEstimateEditSite = siteObj;';
  html += '  isCreateMode = false;';
  html += '  curSiteName = siteObj.siteName;';
  html += '  curTaskObj = null;';
  html += '  closeCustomDatePicker();';
  html += '  const sInfoBanner = document.getElementById("sheetSiteInfoBanner");';
  html += '  if (sInfoBanner) { sInfoBanner.style.display = "none"; sInfoBanner.innerHTML = ""; }';
  html += '  const catRow = document.getElementById("sheetCategorySelectRow");';
  html += '  if (catRow) catRow.style.display = "none";';
  html += '  const createBox = document.getElementById("sheetCreateFields");';
  html += '  if (createBox) createBox.style.display = "block";';
  html += '  const regularCreate = document.getElementById("sheetRegularCreateFields");';
  html += '  if (regularCreate) regularCreate.style.display = "none";';
