  html += 'function findLiveTaskInRawData(siteName, taskRef) {';
  html += '  if (!taskRef || !rawData || !Array.isArray(rawData.sites)) return taskRef;';
  html += '  const refId = taskRef.taskId || taskRef.id || "";';
  html += '  const refTempId = taskRef._tempId || "";';
  html += '  const refSheet = taskRef.sheetName || "";';
  html += '  const refArch = !!taskRef.isArchived;';
  html += '  for (let pass = 0; pass < 2; pass++) {';
  html += '    for (let si = 0; si < rawData.sites.length; si++) {';
  html += '      const s = rawData.sites[si];';
  html += '      if (!s || !Array.isArray(s.tasks)) continue;';
  html += '      if (pass === 0 && siteName && s.siteName !== siteName) continue;';
  html += '      for (let ti = 0; ti < s.tasks.length; ti++) {';
  html += '        const t = s.tasks[ti];';
  html += '        if (!t) continue;';
  html += '        if (refId && (t.taskId === refId || t.id === refId || t._tempId === refId)) return t;';
  html += '        if (refTempId && (t.taskId === refTempId || t._tempId === refTempId)) return t;';
  html += '        if (taskRef.row && taskRef.row !== 99999 && t.row === taskRef.row && !!t.isArchived === refArch && (!refSheet || !t.sheetName || t.sheetName === refSheet)) {';
  html += '          return t;';
  html += '        }';
  html += '        if (pass === 0 && siteName && s.siteName === siteName && taskRef.taskName && t.taskName === taskRef.taskName && ((taskRef.startDateStr && t.startDateStr === taskRef.startDateStr) || (taskRef.dateDisplay && t.dateDisplay === taskRef.dateDisplay))) {';
  html += '          return t;';
  html += '        }';
  html += '      }';
  html += '    }';
  html += '  }';
  html += '  return taskRef;';
  html += '}';
