  html += '';
  html += 'function scheduleQuickTaskSync() {';
  html += '  if (isCreateMode || !curTaskObj) return;';
  html += '  clientMutationSeq++;';
  html += '  const liveTask = findLiveTaskInRawData(curSiteName, curTaskObj);';
  html += '  if (liveTask) liveTask.isShared = selectedShare;';
  html += '  const targetTask = liveTask || curTaskObj;';
  html += '  curTaskObj.status = selectedStatus;';
  html += '  curTaskObj.isShared = selectedShare;';
  html += '  applyOptimisticTaskUpdate(targetTask, selectedStatus, selectedShare, targetTask.memo || "", targetTask.dateDisplay || "", targetTask.manager || "", targetTask.partner, targetTask.taskName);';
  html += '  if (quickShareSyncTimer) clearTimeout(quickShareSyncTimer);';
  html += '  const snapTask = targetTask;';
  html += '  const snapSite = curSiteName || "";';
  html += '  const snapStatus = selectedStatus || "예정";';
  html += '  const snapShare = selectedShare;';
  html += '  quickShareSyncFn = function() {';
  html += '    if (!snapTask || !snapTask.row || typeof google === "undefined" || !google.script || !google.script.run) return;';
  html += '    const tSheet = snapTask.sheetName ? snapTask.sheetName : (snapTask.isArchived ? "완료현장" : "현장데이터");';
  html += '    const origDate = snapTask.dateDisplay || snapTask.startDateStr || "";';
  html += '    const origTask = snapTask.taskName || "";';
  html += '    const origMgr = snapTask.manager || "";';
  html += '    const tId = snapTask.taskId || snapTask.id || "";';
  html += '    google.script.run';
  html += '      .withSuccessHandler(function(res) {';
  html += '        if (res && res.success) {';
  html += '          if (res.row) snapTask.row = res.row;';
  html += '          if (res.movedToCompleted) loadDataSilently();';
  html += '        }';
  html += '      })';
  html += '      .withFailureHandler(function() {})';
  html += '      .updateScheduleStatusFromWeb(snapTask.row, snapStatus, snapShare, snapTask.memo || "", origDate, origMgr, !!snapTask.isArchived, snapSite, origTask, snapTask.partner || "", tSheet, origDate, origTask, origMgr, tId, snapTask.memo || "");';
  html += '  };';
  html += '  quickShareSyncTimer = setTimeout(function() {';
  html += '    quickShareSyncTimer = null;';
  html += '    if (typeof quickShareSyncFn === "function") { const fn = quickShareSyncFn; quickShareSyncFn = null; fn(); }';
  html += '  }, 280);';
  html += '}';
  html += '';
  html += 'function selectSheetStatus(s) {';
  html += '  selectedStatus = s;';
  html += '  updateSheetStatusBtns();';
  html += '  scheduleQuickTaskSync();';
  html += '}';
  html += '';
  html += 'function updateSheetStatusBtns() {';
  html += '  const cleanSel = (selectedStatus || "예정").replace(/\\s+/g, "");';
  html += '  const labelMap = { "예정": "예정", "진행중": "▶️ 진행 중", "완료": "✅ 완료", "AS": "🛠️ AS" };';
  html += '  document.querySelectorAll(".sheet-status-btn").forEach(b => {';
  html += '    const rawSt = b.dataset.status || "";';
  html += '    const st = rawSt.replace(/\\s+/g, "");';
  html += '    const isAct = (cleanSel.indexOf(st) !== -1 || st.indexOf(cleanSel) !== -1);';
  html += '    b.classList.toggle("active", isAct);';
  html += '    const baseTxt = labelMap[st] || rawSt;';
  html += '    b.innerText = isAct ? (baseTxt + " ✓") : baseTxt;';
  html += '  });';
  html += '  const badge = document.getElementById("sheetStatusStateBadge");';
  html += '  if (badge) {';
  html += '    if (cleanSel.indexOf("완료") !== -1) {';
  html += '      badge.innerText = "현재: ✅ 완료";';
  html += '      badge.style.background = "#ecfdf5";';
  html += '      badge.style.color = "#059669";';
  html += '      badge.style.borderColor = "#a7f3d0";';
  html += '    } else if (cleanSel.indexOf("진행") !== -1) {';
  html += '      badge.innerText = "현재: ▶️ 진행 중";';
  html += '      badge.style.background = "#eff6ff";';
  html += '      badge.style.color = "#2563eb";';
  html += '      badge.style.borderColor = "#bfdbfe";';
  html += '    } else if (cleanSel.indexOf("AS") !== -1) {';
  html += '      badge.innerText = "현재: 🛠️ AS";';
  html += '      badge.style.background = "#fff7ed";';
  html += '      badge.style.color = "#ea580c";';
  html += '      badge.style.borderColor = "#fed7aa";';
  html += '    } else {';
  html += '      badge.innerText = "현재: ⏳ 예정";';
  html += '      badge.style.background = "#f1f5f9";';
  html += '      badge.style.color = "#475569";';
  html += '      badge.style.borderColor = "#cbd5e1";';
  html += '    }';
  html += '  }';
  html += '}';
  html += '';
  html += 'function selectSheetShare(val) {';
  html += '  selectedShare = Boolean(val);';
  html += '  updateSheetShareBtns();';
  html += '  scheduleQuickTaskSync();';
  html += '}';
  html += '';
  html += 'function updateSheetShareBtns() {';
  html += '  const btnOn = document.getElementById("sheetShareOn");';
  html += '  const btnOff = document.getElementById("sheetShareOff");';
  html += '  const badge = document.getElementById("sheetShareStateBadge");';
  html += '  if (btnOn) {';
  html += '    btnOn.classList.toggle("active-on", selectedShare);';
  html += '    btnOn.innerText = selectedShare ? "🟦 공유 (ON) ✓" : "🟦 공유 (ON)";';
  html += '  }';
  html += '  if (btnOff) {';
  html += '    btnOff.classList.toggle("active-off", !selectedShare);';
  html += '    btnOff.innerText = !selectedShare ? "🟥 미공유 (OFF) ✓" : "🟥 미공유 (OFF)";';
  html += '  }';
  html += '  if (badge) {';
  html += '    if (selectedShare) {';
  html += '      badge.innerText = "현재: 🟦 공유 켜짐";';
  html += '      badge.style.background = "#eff6ff";';
  html += '      badge.style.color = "#1d4ed8";';
  html += '      badge.style.borderColor = "#bfdbfe";';
  html += '    } else {';
  html += '      badge.innerText = "현재: 🟥 미공유 (OFF)";';
  html += '      badge.style.background = "#fef2f2";';
  html += '      badge.style.color = "#dc2626";';
  html += '      badge.style.borderColor = "#fecaca";';
  html += '    }';
  html += '  }';
  html += '}';
  html += '';
  html += 'function applyOptimisticTaskUpdate(taskObj, newStatus, newShare, newMemo, newDateStr, newMgr, newPartner, newTaskName) {';
  html += '  if (!taskObj) return;';
  html += '  if (newTaskName) taskObj.taskName = newTaskName;';
  html += '  taskObj.status = newStatus;';
  html += '  taskObj.isShared = !!newShare;';
  html += '  taskObj.memo = newMemo;';
  html += '  taskObj.manager = newMgr;';
  html += '  if (newPartner !== undefined) taskObj.partner = newPartner;';
  html += '  const now = new Date();';
  html += '  const ty = now.getFullYear(), tm = now.getMonth() + 1, td = now.getDate();';
  html += '  const todayIso = ty + "-" + (tm < 10 ? "0" + tm : tm) + "-" + (td < 10 ? "0" + td : td);';
  html += '  if (newDateStr) {';
  html += '    taskObj.dateDisplay = newDateStr;';
  html += '    const matches = [];';
  html += '    const re = /(\\d{2,4})[-./]\\s*(\\d{1,2})[-./]\\s*(\\d{1,2})/g;';
  html += '    let m;';
  html += '    while ((m = re.exec(newDateStr)) !== null) {';
  html += '      let y = parseInt(m[1], 10);';
  html += '      if (y < 100) y += 2000;';
  html += '      const mo = parseInt(m[2], 10);';
  html += '      const da = parseInt(m[3], 10);';
  html += '      matches.push({ iso: y + "-" + (mo < 10 ? "0" + mo : mo) + "-" + (da < 10 ? "0" + da : da), ms: new Date(y, mo - 1, da).getTime() });';
  html += '    }';
  html += '    if (matches.length > 0) {';
  html += '      taskObj.startDateStr = matches[0].iso;';
  html += '      taskObj.endDateStr = (matches.length > 1) ? matches[1].iso : matches[0].iso;';
  html += '      taskObj.dateMs = matches[0].ms;';
  html += '    }';
  html += '  }';
  html += '  const stClean = String(newStatus || "").replace(/\\s+/g, "");';
  html += '  const isDone = (stClean.indexOf("완료") !== -1 || stClean.indexOf("취소") !== -1);';
  html += '  if (taskObj.startDateStr) {';
  html += '    const eIso = taskObj.endDateStr || taskObj.startDateStr;';
  html += '    taskObj.isToday = (taskObj.startDateStr <= todayIso && todayIso <= eIso);';
  html += '    taskObj.isDelayed = (!isDone && !taskObj.isArchived && eIso < todayIso);';
  html += '  } else if (isDone) {';
  html += '    taskObj.isDelayed = false;';
  html += '  }';
  html += '  if (rawData && Array.isArray(rawData.sites)) {';
  html += '    let activeSitesCnt = 0, todayCnt = 0, delayCnt = 0;';
  html += '    rawData.sites.forEach(s => {';
  html += '      let comp = 0, canc = 0, prog = 0, del = 0, act = 0;';
  html += '      (s.tasks || []).forEach(t => {';
  html += '        const sc = String(t.status || "").replace(/\\s+/g, "");';
  html += '        if (sc.indexOf("완료") !== -1) comp++;';
  html += '        else if (sc.indexOf("취소") !== -1) canc++;';
  html += '        else {';
  html += '          act++;';
  html += '          if (sc.indexOf("진행") !== -1) prog++;';
  html += '        }';
  html += '        if (t.isDelayed) del++;';
  html += '        if (!t.isArchived) {';
  html += '          if (t.isToday) todayCnt++;';
  html += '          if (t.isDelayed) delayCnt++;';
  html += '        }';
  html += '      });';
  html += '      const totalT = (s.tasks || []).length;';
  html += '      const validT = totalT - canc;';
  html += '      const allDone = (totalT > 0 && act === 0);';
  html += '      s.completedTasksCount = comp;';
  html += '      s.canceledTasksCount = canc;';
  html += '      s.inProgressTasksCount = prog;';
  html += '      s.delayedTasksCount = del;';
  html += '      s.activeTasksCount = act;';
  html += '      s.validTasksCount = validT;';
  html += '      s.isAllCompleted = allDone;';
  html += '      s.progressRate = (validT > 0) ? (allDone ? 100 : Math.min(100, Math.max(0, Math.round((comp / validT) * 100)))) : 0;';
  html += '      if (!allDone) activeSitesCnt++;';
  html += '    });';
  html += '    if (rawData.kpi) {';
  html += '      rawData.kpi.activeSites = activeSitesCnt;';
  html += '      rawData.kpi.todayCount = todayCnt;';
  html += '      rawData.kpi.delayedCount = delayCnt;';
  html += '    }';
  html += '    renderDashboardPayload(rawData);';
  html += '  }';
  html += '}';
  html += '';
  html += 'function saveSheetTask() {';
  html += '  const saveBtn = document.getElementById("sheetSaveBtn");';
  html += '  const memoEl = document.getElementById("sheetMemoInput");';
  html += '  const memoVal = memoEl ? memoEl.value.trim() : "";';
  html += '  const dateInput = document.getElementById("sheetDateInput");';
  html += '  const dateVal = dateInput ? dateInput.value.trim() : "";';
  html += '  const mgrSelect = document.getElementById("sheetManagerSelect");';
  html += '  const mgrCustom = document.getElementById("sheetManagerCustomInput");';
  html += '  const mgrSelect2 = document.getElementById("sheetManagerSelect2");';
  html += '  const mgrCustom2 = document.getElementById("sheetManagerCustomInput2");';
  html += '  let mgrVal1 = "";';
  html += '  if (mgrSelect) {';
  html += '    mgrVal1 = (mgrSelect.value === "__CUSTOM__") ? (mgrCustom ? mgrCustom.value.trim() : "") : mgrSelect.value.trim();';
  html += '  }';
  html += '  let mgrVal2 = "";';
  html += '  if (mgrSelect2) {';
  html += '    mgrVal2 = (mgrSelect2.value === "__CUSTOM__") ? (mgrCustom2 ? mgrCustom2.value.trim() : "") : mgrSelect2.value.trim();';
  html += '  }';
  html += '  let mgrVal = "";';
  html += '  if (mgrVal1 && mgrVal2) {';
  html += '    mgrVal = (mgrVal1 === mgrVal2) ? mgrVal1 : (mgrVal1 + ", " + mgrVal2);';
  html += '  } else {';
  html += '    mgrVal = mgrVal1 || mgrVal2;';
  html += '  }';
  html += '  if (curEstimateEditSite) {';
  html += '    const siteObj = curEstimateEditSite;';
  html += '    const nameInput = document.getElementById("sheetNewSiteNameInput");';
  html += '    const siteVal = nameInput ? nameInput.value.trim() : "";';
  html += '    if (!siteVal) {';
  html += '      showToast("⚠️ 현장/고객명을 입력해주세요.");';
  html += '      if (nameInput) nameInput.focus();';
  html += '      return;';
  html += '    }';
  html += '    const statusSel = document.getElementById("sheetNewSiteStatusSelect");';
  html += '    const prioritySel = document.getElementById("sheetNewSitePrioritySelect");';
  html += '    const scopeSel = document.getElementById("sheetNewSiteScopeSelect");';
  html += '    const sourceSel = document.getElementById("sheetNewSiteSourceSelect");';
  html += '    const clientNameInp = document.getElementById("sheetNewSiteClientNameInput");';
  html += '    const clientPhoneInp = document.getElementById("sheetNewSiteClientPhoneInput");';
  html += '    const mgrSel = document.getElementById("sheetNewSiteManagerSelect");';
  html += '    const expAmtInp = document.getElementById("sheetNewSiteExpectedAmountInput");';
  html += '    const contractAmtInp = document.getElementById("sheetNewSiteContractAmountInput");';
  html += '    const inqDateInp = document.getElementById("sheetNewSiteInquiryDateInput");';
  html += '    const expDateInp = document.getElementById("sheetNewSiteExpectedDateInput");';
  html += '    const consultDateInp = document.getElementById("sheetNewSiteConsultDateInput");';
  html += '    const visitDateInp = document.getElementById("sheetNewSiteVisitDateInput");';
  html += '    const estSendDateInp = document.getElementById("sheetNewSiteEstSendDateInput");';
  html += '    const addrInp = document.getElementById("sheetNewSiteAddressInput");';
  html += '    const nextActInp = document.getElementById("sheetNewSiteNextActionInput");';
  html += '    const failReasonSel = document.getElementById("sheetNewSiteFailReasonSelect");';
  html += '    const memoInp = document.getElementById("sheetNewSiteMemoInput");';
  html += '    const origSiteName = siteObj.siteName;';
  html += '    const rowNum = (siteObj.estimateData && siteObj.estimateData.row) || null;';
  html += '    const estPayload = {';
  html += '      row: rowNum,';
  html += '      originalSiteName: origSiteName,';
  html += '      origSiteName: origSiteName,';
  html += '      siteName: siteVal,';
  html += '      status: (statusSel && statusSel.value) || "신규 문의",';
  html += '      priority: (prioritySel && prioritySel.value) || "보통",';
  html += '      scope: (scopeSel && scopeSel.value) || "전체공사",';
  html += '      source: (sourceSel && sourceSel.value) || "소개",';
  html += '      clientName: (clientNameInp && clientNameInp.value.trim()) || "",';
  html += '      clientPhone: (clientPhoneInp && clientPhoneInp.value.trim()) || "",';
  html += '      manager: (mgrSel && mgrSel.value) || "조항만",';
  html += '      expectedAmount: (expAmtInp && expAmtInp.value.trim()) || "",';
  html += '      contractAmount: (contractAmtInp && contractAmtInp.value.trim()) || "",';
  html += '      inquiryDate: (inqDateInp && inqDateInp.value) || "",';
  html += '      expectedDate: (expDateInp && expDateInp.value) || "",';
  html += '      consultDate: (consultDateInp && consultDateInp.value) || "",';
  html += '      visitDate: (visitDateInp && visitDateInp.value) || "",';
  html += '      estimateSendDate: (estSendDateInp && estSendDateInp.value) || "",';
  html += '      address: (addrInp && addrInp.value.trim()) || "",';
  html += '      nextAction: (nextActInp && nextActInp.value.trim()) || "",';
  html += '      failReason: (failReasonSel && failReasonSel.value) || "",';
  html += '      memo: (memoInp && memoInp.value.trim()) || ""';
  html += '    };';
  html += '    const prevEstimateSnapshot = Object.assign({}, siteObj.estimateData || {});';
  html += '    const prevSiteName = siteObj.siteName;';
  html += '    const eColorHex = (estPayload.priority === "긴급" ? "#ef4444" : (estPayload.priority === "높음" ? "#f97316" : "#0284c7"));';
  html += '    siteObj.siteName = siteVal;';
  html += '    siteObj.colorHex = eColorHex;';
  html += '    siteObj.colorCode = (estPayload.priority === "긴급" ? "11" : (estPayload.priority === "높음" ? "6" : "1"));';
  html += '    siteObj.primaryManager = estPayload.manager;';
  html += '    siteObj.manager = estPayload.manager;';
  html += '    siteObj.estimateData = Object.assign({}, siteObj.estimateData || {}, estPayload);';
  html += '    if (selectedPcSiteName === origSiteName) { selectedPcSiteName = siteVal; }';
  html += '    const isDone = (estPayload.status === "계약 완료");';
  html += '    siteObj.isArchived = isDone;';
  html += '    siteObj.isAllCompleted = isDone;';
  html += '    closeCustomDatePicker();';
  html += '    const overlayEl = document.getElementById("sheetOverlay");';
  html += '    if (overlayEl) overlayEl.classList.remove("show");';
  html += '    popBottomSheetHistoryStateIfNeeded();';
  html += '    curEstimateEditSite = null;';
  html += '    if (rawData) renderDashboardPayload(rawData);';
  html += '    showToast("💾 [" + siteVal + "] 신규현장 정보가 수정되었습니다.");';
  html += '    if (typeof google !== "undefined" && google.script && google.script.run) {';
  html += '      google.script.run';
  html += '        .withSuccessHandler(res => {';
  html += '          if (res && res.success) { loadDataSilently(); }';
  html += '          else {';
  html += '            showToast("⚠️ 수정 실패: " + ((res && res.error) || "알 수 없는 오류"));';
  html += '            siteObj.siteName = prevSiteName;';
  html += '            siteObj.estimateData = prevEstimateSnapshot;';
  html += '            if (rawData) renderDashboardPayload(rawData);';
  html += '          }';
  html += '        })';
  html += '        .withFailureHandler(err => {';
  html += '          showToast("❌ 서버 오류: " + ((err && err.message) || err));';
  html += '          siteObj.siteName = prevSiteName;';
  html += '          siteObj.estimateData = prevEstimateSnapshot;';
  html += '          if (rawData) renderDashboardPayload(rawData);';
  html += '        })';
  html += '        .updateEstimateRowFromWeb(estPayload);';
  html += '    } else {';
  html += '      const apiUrl = (typeof SCRIPT_URL !== "undefined" ? SCRIPT_URL : (window.location.href.split("?")[0]));';
  html += '      fetch(apiUrl + "?action=updateEstimateRow", {';
